"""台帳（data/studio/ledger.jsonl）だけを読んで、本ごとの「齢 → 再生」の並びを出す。API 0単位。

**なぜ要るか（2026-09-07 18:3x JST・optimizer・Opus が実測して足した）**:
§7 は「その回に見た1点」で書かれ続け、2回 続けて外れた。

  1本目 EkNqtkK49Bw   9.6h 127 → 28.4h 122 まで **19時間 平ら** → 30.6h 129 → 32.6h **139**
  2本目 nQbVxuWpWw8   4.4h 28 → 6.6h 28 で平ら → 8.6h **68**（2時間で +40 ＝ 2.4倍）

09/07 16:3x の §7 は「1本目は 6時間で 100%」「2本目が 28回 で止まった」と書いたが、
**どちらも平らな区間の中で見た点**だった。同じ日の旧作りと並べた「38%」も同じで、
2時間 あとには 68 対 73 ＝ **93%** になっている（旧作りのほうは 7.6h 73 → 9.6h 73 で平ら）。
＝ **平らは「止まった」ではない。** 数え直しの間隔なのか配信の波なのかは台帳からは決められないが、
どちらでも **齢の浅い1点で本と本を比べてはいけない** ことは決まる。

だからこの道具は、1本につき**並び全部**と、直近の伸び（+N回/時）を出す。
**覆る条件**: 平らな区間のあとに一度も伸びない本が 3本 続いたら、平らは本当に止まりで、
そのときは「最後の点」で比べてよい（この註と §7 の警告を消す）。
"""
from __future__ import annotations

import datetime as dt
import re
import statistics
import json
from pathlib import Path

from .common import JST, ROOT, ledger_rows, now_jst


def _at(row: dict) -> dt.datetime:
    return dt.datetime.fromisoformat(row["at"]).astimezone(JST)


def ours(rows: list[dict]) -> set[str]:
    """こちらの作りの本（scheduled 行が持つ video_id）。旧作りと分けて並べるため。"""
    return {r["video_id"] for r in rows if r.get("event") == "scheduled" and r.get("video_id")}


def series(rows: list[dict]) -> dict[str, list[dict]]:
    """id → measured の点（齢の順）。同じ齢の重複は後の行を採る。"""
    out: dict[str, dict[float, dict]] = {}
    for r in rows:
        if r.get("event") != "measured" or "age_h" not in r:
            continue
        out.setdefault(r["id"], {})[round(float(r["age_h"]), 1)] = r
    return {vid: [pts[k] for k in sorted(pts)] for vid, pts in out.items()}


def returned_private(rows: list[dict]) -> dict[str, dict]:
    """id → 最後の `unscheduled` 行。**公開されたあと private へ戻した本**だけを採る。

    **なぜ日ごとの本数から抜くか**（2026-09-09 08:5x JST・optimizer・Opus が踏んだ）:
    旧 `reschedule.py` が 09/02 に打った publishAt が **09/08 23:00 JST** に発火して
    `Yy7GmcGoQ6I` が public になり、**7分後**（23:0x）に前の回が private へ戻して
    台帳に `unscheduled` を書いた。だが `lines()` は `measured` の点を持つ本を全部 数えるので、
    見出しは **10時間 たっても「09/08（2本）」**のままで、行は **「0.1h 0回」で凍った**まま
    `within_h`（72時間）ぶん 並び続ける —— private の本は `measure` が二度と見ないので、
    この点は**永久に更新されない**。

    **凍った 0回 の点が読み違えられる形**: §7 は「お試し配信は毎回 来るか」を
    浅い齢の再生で見ている（§7 の 4〜5h の行）。**7分だけ public だった本の 0回** は
    その問いの答えではないのに、並びの上では「0回 の本」と同じ形をしている。
    §7 が 09/07 16:3x に踏んだ穴（**その日に出た本を1本も見ていなかった**）と同じ型で、
    向きだけが逆 —— あちらは数え落とし、こちらは**数えすぎ**。

    **消さない**（オーナー 08/31・§8）。**行は印字するが、日の本数には入れない。**

    **覆る条件**: 戻した本がもう一度 公開されたら、その `measured` は `unscheduled` より
    後の刻で付くので、ここは自動で外れる（`_at` で比べているのはそのため）。
    「7分」を閾にはしていない —— **どれだけ長く public だったかではなく、
    いま private かどうか**で決めている。public のまま置くと決めた本が出たら、
    その本には `unscheduled` を書かないこと。
    """
    out: dict[str, dict] = {}
    for r in rows:
        if r.get("event") == "unscheduled" and r.get("id"):
            out[r["id"]] = r
    ser = series(rows)
    return {vid: r for vid, r in out.items()
            if vid in ser and _at(ser[vid][-1]) <= _at(r)}


def pending(rows: list[dict]) -> dict[str, tuple[dt.datetime, str]]:
    """id → （公開予定の刻, 題）。`measure` が毎回 書く `pending` 行から（最後の行を採る）。

    **なぜ日ごとの本数に「予約」を足すか**（2026-09-08 23:0x JST・optimizer・Opus が踏んだ）:
    この道具は `measured`（＝**公開ずみ**）だけを数えるので、**その日に出る予定の本は 1本 も数に入らない。**
    実測 09/08: 旧作りの `Yy7GmcGoQ6I` が 08/19 に上げられ 09/02 に `reschedule.py` で
    **09/08 23:00 JST** の publishAt を打たれたまま private で待っていた。`status` の「きょうの枠」には
    private として出ていたが、**この道具の日の見出しは 22時間 ずっと「09/08（1本）」**で、
    §7 は 15:0x〜21:4x の **5回 続けて**「3本目は **1本 だけの日** に出た」と書き、
    「同じ条件の 2点目」を 09/09 に期待していた。23:00 にその本が出て、**09/08 は 2本 の日になった。**
    ＝ §1 の「量は毒」がそのまま効く軸（その日の本数）が、**判定を書いている当の数から抜けていた。**
    **覆る条件**: 予約が「その日に本当に出る」ことの確からしさが崩れたら（予約のまま出なかった本が出たら）、
    見出しは「＋予約」ではなく別の印を使う（`pending` 行は残るので数え直せる）。
    """
    out: dict[str, tuple[dt.datetime, str]] = {}
    for r in rows:
        if r.get("event") != "pending" or not r.get("publish_at"):
            continue
        out[r["id"]] = (dt.datetime.fromisoformat(r["publish_at"]).astimezone(JST), r.get("title", ""))
    return out


def published_at(points: list[dict]) -> dt.datetime:
    """公開の刻 ＝ 最初の点の「いつ測ったか」から齢を引く（API を撃たずに日で束ねるため）。"""
    p = points[0]
    return _at(p) - dt.timedelta(hours=float(p["age_h"]))


def envelope(pts: list[dict]) -> list[int]:
    """齢の順の点を、**それまでの最大**（単調な包絡）に直した再生の並びを返す。API 0単位。

    **なぜ（2026-09-09 20:0x JST・optimizer・Opus。この回に撃って確かめた）**:
    `videos.list` は伸びている本を **遅れの違う複数の複製**から返す（`yt.settle_stats` の註 ＝ 19:1x の実測 2つ）。
    19:1x は「複製は2つ・低いほうは 2時間 前の値」と書きましたが、**この回に 10回 撃つと 3つ**出ました:

        gv1u7n_pCAQ（齢 10h・伸び中）  **886 が 6回・637 が 3回・823 が 1回**
          637 ＝ **17:16 の台帳の行そのもの（2.8時間 前）**・823 ＝ 19:08 の `status` の値（1時間 前）
        lQHX9LJ80Sg（34h）             **501 が 8回・493 が 2回**
        nQbVxuWpWw8（58h）・PhQ2KvuQASQ（59h）  差 0（10回 とも同じ）

    ＝ **1点の台帳の値は、真の再生を最大 28%（886 に対し 637 ＝ -249回）下に外します。**

    **読み直しを増やす手では埋まりません**（19:1x が 12回 撃って測ってある）: 同じ `lQHX9LJ80Sg` を
    19:14 に **3回 とも 468**・12回 とも 468 と読んだ回に、別の 3回 の当てでは 499 が 1度 出ています。
    ＝ **遅れている複製が「多数派」になる回が在る**ので、`settle_stats` の `max` でも救えません
    （実測: 19:14 の台帳の行は **468**、その 47分後 の 20:01 は **501**・10回 撃つと 501 が 8回）。

    **救えるのは、次の回です** —— 再生は減らないので、**それまでの最大**が、その齢での下限として
    いちばん良い推定になります。1点で救えないものを、並びで救う形。

    **効く先**: (1) `lines()` の並びと `_growth()` が、複製の取り違えで **偽の減り**（09/09 19:09 の
    711 → 637 ＝ **-74回**）と **偽の平ら**を出さなくなる。(2) §7 が 09/09 15:0x〜19:1x の 5周 にわたり
    「3本目は 3回 続けて +0 ＝ 500回 を越えない側」と書いた当のものが、**遅れている複製を 5回 読んでいた**
    ことが並びに出る（30.3h〜33.2h の 468 が 5点 続き、34.0h で 501）。

    **生の値は消しません** —— 台帳は足すだけで、`drops()` は生の組を数え続けます（§7 が引いている数なので）。
    `lines()` は上げた点に **`(生 N)`** を添えて、どこを上げたかが読めるようにします。

    **覆る条件**: (1) 再生が**本当に**減る道が出たら（本を非公開に戻す・YouTube が数を取り消す）、
    包絡はその減りを隠します —— `drops()` の生の減りが **-5回 より大きい**組で、
    同じ本の次の点が戻らなかった回が出たら、そこは包絡ではなく生で読むこと。
    (2) 伸びている本で 10回 読んで差が 0 の回が 1週間 続いたら、複製が揃った ＝ 包絡ごと要らない
    （`settle_stats` の覆る条件 (2) と同じ刻に外す）。

    **【2026-09-10 08:0x・optimizer・Opus】覆る条件 (1) が引かれ、その門（-5回）では引けないことも分かりました。**
    上の (1) は「本当の減り」を **減りの大きさ**（-5回 より大きい組）で拾う形でしたが、
    **台帳に在る本当の減りは全部 -1〜-2回** で、**門を1件も通りません**（＝ 06:3x の
    「出どころの無い覆る条件は、引かれないのではなく **引けない**」の族。JOURNAL 06:3x）。
    **分けるのは大きさではなく、下回っていた時間です**（撃って数えた・API 0単位）:

        nQbVxuWpWw8  68 → 66（齢 37.2h）  生が包絡を下回ったまま **32.4時間**（42点）
        9zkfjEH48PY  60 → 59（齢 92.8h）  **76.3時間**（64点）
        kzefG44_APU  191 → 189（齢 29.3h） **95.4時間**（70点）
        lywTMXD6WDM  216 → 214（齢 32.6h） **63.0時間**（57点）
        qyVdpAoT_40  157 → 156（齢 33.5h） **63.0時間**（57点）

    **複製の遅れの実測は 最大 2.8時間**（上の 637 ＝ 2.8時間 前の値）なので、
    **32〜95時間 は遅れでは説明できません** ＝ YouTube が数を**下へ数え直した**側です
    （無効な再生の取り消し。1本 -1〜-2回）。**素の包絡は、それを永久に上げたままにします。**

    **直し**: 峰は「**そのあと 1度も戻らず**、しかも判定に足るだけ時間が経った」ときだけ捨てる
    （`ENVELOPE_LAG_H` ＝ 遅れの実測 2.8時間 の 2倍 の 6.0時間）。
    ＝ **遅れの窪み（すぐ戻る）は今までどおり上げ、数え直し（戻らない）は生へ落ちます。**
    捨てた峰は `recounts()` が並べ、`report()` が毎周 印字します。

    **なぜ `n_values` では見えないか**（§7 (h) の当のもの）: 数え直しは**周と周のあいだ**に起き、
    同じ周の 3回 読みは 3回 とも新しい値を返します ＝ **`n_values` は必ず 1**。
    ＝ (h) の「0件」は「数え直しが無い」ではなく、**この道では見えない**。数え直しはここで数えること。

    **覆る条件**: (1) 戻らない減りが 6時間 より短い時間で戻った回が出たら、遅れの実測が伸びた
    ＝ `ENVELOPE_LAG_H` をその実測の 2倍 へ。(2) 数え直しが 1本で 5回 を越えたら、
    それは取り消しではなく別の機構 ＝ 生で読むこと（包絡ごと外す）。
    """
    cap = ceiling(pts)
    out: list[int] = []
    hi = None
    for p in pts:
        v = int(p["views"])
        hi = v if hi is None else max(hi, v)
        out.append(hi if cap is None else min(hi, cap))
    return out


#: 複製の遅れの実測（最大 2.8時間・`envelope` の註）の **2倍**。
#: この時間を越えて生が包絡を下回ったままなら、遅れでは説明できない ＝ 数え直し。
ENVELOPE_LAG_H = 6.0


def ceiling(pts: list[dict]) -> int | None:
    """**支えられている いちばん高い水準**（＝ 包絡の天井）。API 0単位。

    水準 v が「支えられている」＝ **最後に v 以上を見た点から `ENVELOPE_LAG_H` しか経っていない**。
    それより古い峰は、遅れの窪みでは説明できない（遅れの実測は 最大 2.8時間）＝ **数え直し**なので、
    天井にしない。**まだ 6時間 経っていない峰は必ず支えられている** ので、
    伸び中の本の最新の点は、いつもそのまま上がります。

    **見るのは点1つではなく水準です** —— 同じ峰が 2点 続く回が在り（実測 `nQbVxuWpWw8` の 68 は
    23:03 と 23:08 の 2点）、**点ごとに「この点より後ろに同じ値が在るか」で見ると、
    前の点は後ろの点に支えられ、後ろの点は…と続いて、どの点も『戻らなかった』にならず、
    峰が永久に残ります**（この回に一度そう書いて、実物で外した）。水準を高いほうから見れば、その口が無い。
    **ただし、この行の中の `>=` は効いていません** —— 陽性対照を撃つと落ちませんでした。
    `>=` を `==` に変えても**実物 45本 とも天井は同じ**で、降順に見るかぎり必ず同じ答えになります
    （高い水準が支えられていれば そちらで返るので、低い水準に「より新しい高い点」は残らない）。
    **効いているのは「降順に水準で見る」ほうだけ**なので、`>=` に主張を持たせないこと
    （§5 の教訓の形3つ目「陽性対照は落ちるまで撃つ。落ちなければ、疑うのは道具ではなく検査のデータ」の 3件目）。

    **並びは後ろから読み直します**（天井は系列の最後の点から決まる）—— 台帳は毎周 全部を
    読み直すので、数え直しが分かった回に**過去の点も**その水準へ落ちます（＝ 減りが
    「起きた所」に出る。6時間 遅れて段が付く形にはしない）。
    """
    if not pts:
        return None
    last_age = float(pts[-1]["age_h"])
    for v in sorted({int(p["views"]) for p in pts}, reverse=True):
        seen = max(float(p["age_h"]) for p in pts if int(p["views"]) >= v)
        if last_age - seen <= ENVELOPE_LAG_H:
            return v
    return int(pts[-1]["views"])


def recounts(rows: list[dict]) -> list[dict]:
    """**数え直し**（生が包絡を `ENVELOPE_LAG_H` より長く下回ったまま戻らなかった峰）を並べる。API 0単位。

    §7 (h) は「48h を越えた本で `n_values > 1` が出るか」で数え直しを見張っていましたが、
    **数え直しは周と周のあいだに起き、同じ周の 3回 読みは秒の間隔しか離れていません**
    ＝ その道では構造的に見えません。**数え直しはここで数えること。**

    **【2026-09-10 10:2x に書き直した】**もとは「**`n_values` は必ず 1**（台帳の `n_values > 1` は
    8行 とも伸び中の本・48h 超は 0行）」と書いていましたが、**この回に 48h 超で 1行 出ました**
    （`EkNqtkK49Bw` 96.3h・142 対 141）。**割れること自体は数え直しの印ではありません** ——
    割れるのは**複製の遅れ**で、伸びた直後なら齢がいくつでも起きます。
    同じ周の中で遅れと数え直しを分けるのは `shakes()`（**推定が動かなかった周の数**で見る）。
    """
    out: list[dict] = []
    for vid, pts in series(rows).items():
        cap = ceiling(pts)
        top = max(int(p["views"]) for p in pts)
        if cap is None or cap >= top:
            continue
        seen = max(float(p["age_h"]) for p in pts if int(p["views"]) >= top)
        out.append({
            "id": vid,
            "from": top,
            "to": cap,
            "age_h": seen,
            "hours_below": float(pts[-1]["age_h"]) - seen,
            "points_below": sum(1 for p in pts if float(p["age_h"]) > seen),
        })
    return sorted(out, key=lambda r: -r["hours_below"])

FLAT_MIN_H = 2.0
#: 「平ら」と呼ぶ最短の長さ（時間）。これより短い区間は、測りの間隔（床 41分）と区別が付かない。

FLAT_STOP_H = 24.0
#: **まだ伸びが戻っていない平ら**を「止まった」と数える長さ。**戻った中でいちばん長い平ら
#: （`EkNqtkK49Bw` の 20.9時間）より上**に置くこと ——下に置くと、その本を取り逃す。


#: 「落ち着いた」と呼ぶのに要る、**推定が動かなかった周の数**（この周を含む）。
#: 複製の遅れの実測は 最大 2.8時間（`envelope` の註）＝ 床 42分 なら 4周ぶん。3周 は その手前。
SETTLED_ROUNDS = 3


def _lag_evidence(pts: list[dict], k: int, low: int) -> dict:
    """`pts[k]` の割れた読みの**低いほう**が、**遅れた複製で説明が付くか**。

    返すのは 3つ: `floor`（窓の先頭でその本が持っていた値）・`explained`（`low >= floor` か）・
    `held_h`（その値を台帳が**そのまま持っていた**なら何時間 前か。無ければ None）。

    **判定に使うのは `explained`**（範囲）で、`held_h` は**証拠として並べるだけ**です ——
    再生は減らないので、遅れた複製が返せるのは**その本がこの窓で通った値**、つまり
    「窓の先頭の値 以上・いまの値 以下」。台帳が 41分ごとにしか見ていない以上、
    **複製が座っている値を台帳が1度も書いていないことはあり得ます**（点と点のあいだ）ので、
    完全一致だけを条件にすると、そこを第3の口に化かします。

    **なぜこれが分ける物差しか**（2026-09-10 13:4x JST・optimizer・Opus）:
    10:2x は「落ち着いたかは齢ではなく**推定が動かなかった周の数**」で分けました。
    **その周の数は代理で、直接の問いは同じ回の中に既に書かれています** ——
    この関数の呼び手（`shakes`）の覆る条件 (2)「`lag` の行の低いほうが、その本について
    **台帳が前に書いた値のどれとも一致しない**回が出たら、低い側は遅れた複製ではない」。
    **10:2x が手で撃った検算そのもの**（「低いほう 141 は 41分 前の台帳の行の値そのもの」・
    19:1x の「低いほうの 637 は 2時間 前の台帳の行の値そのもの」）が、道具に入っていませんでした。

    **代理が外れた実測**（この回に踏んだ・`1huadpEk6HY` 齢 148.1h・**5 対 6**）:
    この本は **5 が 11周 続き、12:04 に 6 へ伸びた**。13:07 の 3回 読みが 5 と 6 に割れ、
    高いほうの読みは 12:04・12:32・13:07 の **3周 とも 6** ＝ 周の数の門は
    「推定が動いていない」と読み、**`still`（第3の口）と札を貼りました**。
    **ところが低い 5 は、83分 前（11:44）の台帳の行の値そのもの**です ＝ 遅れの側。
    **周の数は本の速さで意味が変わります** —— 3周 は 1本/日 の速い本では 1.7時間 ですが、
    6日で 1回 しか伸びない本では、複製が古い値に座っている窓のほうがずっと長い。
    **遅れは周ではなく時間で起きるので、周で数えると遅い本ほど第3の口に化けます。**

    窓は `ENVELOPE_LAG_H`（6時間）——`recounts` が「遅れでは説明できない」と決めている
    のと**同じ数を同じ向きに**使います（複製の遅れの実測は 最大 2.8時間・§6）。

    **覆る条件**: (1) `still` が出た行の低い値が、窓を 12時間 に広げれば台帳に在る、
    という回が出たら、窓は 6時間 では足りない（`ENVELOPE_LAG_H` ごと見直すこと ——
    `recounts` と同じ数なので、片方だけ動かさない）。
    (2) 低い値が台帳に在っても、その値が**その本の初回の測りより前**しか無いなら、
    それは遅れではなく別の口（いまは 1本も無い）。
    (3) 周の数（`rounds`）は返り値に残してあります —— 2つが割れた行を次の回が
    列挙で比べられるように。3本 続けて同じ答えなら、片方を落としてよい。
    """
    out: dict = {"floor": None, "explained": False, "held_h": None}
    if not pts[k].get("at"):
        return out
    now = _at(pts[k])
    win = [q for q in pts[:k]
           if q.get("at") and (now - _at(q)).total_seconds() / 3600.0 <= ENVELOPE_LAG_H]
    if not win:
        return out
    out["floor"] = int(win[0]["views"])
    out["explained"] = low >= out["floor"]
    for q in reversed(win):
        if int(q["views"]) == low:
            out["held_h"] = (now - _at(q)).total_seconds() / 3600.0
            break
    return out


def _settled_after(pts: list[dict], k: int, low: int, high: int) -> str | None:
    """割れた読みの**あとの点**が、どちらの側に落ち着いたか。API 0単位。

    返すのは `"low"`（低い側が水準になった ＝ **数え直しが本当だった**）・
    `"high"`（高い側が続いた ＝ 低い読みは複製の揺れ）・`"between"`・
    `None`（**まだ点が無い ＝ 言えない**）。

    **なぜ足したか**（2026-09-10 17:3x JST・optimizer・Opus）:
    `shakes` の覆る条件 (1) は「`still` が出たら、その本を `recounts()` も挙げているかを
    **先に見ること**」と書いていますが、**その手は道具に入っておらず、次の回が手で見る形**でした
    （METHOD が repo でいちばん多い壊れ方と呼ぶもの ——「言っている所と、している所が別」）。
    いまは `shakes` が join して `recount` の札を貼ります。
    **ただし札だけでは、どちらが本当かは決まりません** —— 数え直しなら**低いほうが新しい値**で、
    複製の遅れなら**高いほうが新しい値**です。**この関数は、その決着を台帳が自分で付けるようにします**
    （次の回は覚えていなくてよい・撃てば出る）。

    **この回に踏んだ実物**（`lywTMXD6WDM` 齢 103.4h・**213 対 214**）: 台帳の 73点 は
    **216（初点・齢 30.6h）→ 214（齢 32.6h）→ 214 が 71点 続く**で、**213 は 1度も無い**。
    窓（6時間）の先頭は 214 なので `_lag_evidence` は「遅れでは説明が付かない」＝ `still` と貼りました。
    **ところが同じ本は `recounts()` が挙げている 5本 の 1つ**（216→214）です ＝
    **この本の再生は、実測で 1度 下がっています。**
    `_lag_evidence` の「再生は減らない」という前提は、**数え直しの本では成り立ちません** ——
    2度目の数え直し（214→213）なら、**低い 213 が新しい値で、高い 214 が遅れた複製**です。
    ＝ **同じ形が「第3の口」と「2度目の数え直し」の両方で出るので、割れた瞬間には分けられません。**
    分けられるのは**あと**です: 213 が水準になれば数え直し・214 に戻れば揺れ。

    **`settle_stats` は最大を採る**ので、数え直しの側だったときは
    **6時間（`ENVELOPE_LAG_H`）のあいだ古い高い値に座ります** ——
    そこは `recounts()`／`ceiling()` が包絡を落として拾う所で、二重には直さないこと。

    **覆る条件**: (1) `after == "low"` の行が出たら、その本の `still`／`recount` は
    **数え直しの側で決着**（＝ 第3の口の分子には数えない）。
    (2) `after == "high"` の行が出たら、低い読みは台帳の窓に無い値を返した複製 ＝
    **そこで初めて第3の口**（`settle_stats` の覆る条件へ）。
    (3) `recount` の札が付いた行が 3行 続けて `after == "high"` なら、
    `recounts()` との join は効いていない ＝ 札を外して `still` に戻すこと。
    """
    later = [int(q["views"]) for q in pts[k + 1:]]
    if not later:
        return None
    top = max(later)
    if top >= high:
        return "high"
    if top <= low:
        return "low"
    return "between"


def shakes(rows: list[dict]) -> list[dict]:
    """同じ周の 3回 読みで**値が割れた行**（`n_values > 1`）を並べ、
    **遅れている複製**か **第3の口**かを分ける。API 0単位。

    **なぜ足したか**（2026-09-10 10:2x・optimizer・Opus。この回に §7 (h) の覆る条件 (3) が
    初めて引かれ、**引いた数を見たら第3の口ではありませんでした**）:
    (3) は「`n_values > 1` が **齢 48h 超の行**で 1度でも出たら、遅れでも数え直しでもない
    第3の口 ＝ `settle_stats` の覆る条件どおり中央値へ」でした。実測 10:20 に
    **`EkNqtkK49Bw` 齢 96.3h・142 対 141・n=2** が出て、門は引かれます。
    **ところが低いほう（141）は、その 41分 前（09:39）の台帳の行の値そのもの**でした ——
    同じ本は **140（12周 続けて）→ 141（09:39）→ 142（この回）**と**伸びており**、
    低い側は 1周 遅れた複製です。`yt.settle_stats` が 09/09 19:1x に
    「低いほうの 637 は 2時間 前の台帳の行の値そのもの」と書いた**同じ形** ＝ **遅れの側**。
    数え直しなら値は**下がって戻りません**が、`recounts()`（周と周のあいだを包絡で見る側）は
    この本を挙げていません（挙がっているのは別の 5本）。

    **門が見ていた変数が違いました**: 19:1x の実測は「**揺れるのは伸びている本だけ**」で、
    (3) はそれを**齢**へ翻訳しています。**齢 48h 超は「落ち着いた」ではありません** ——
    `EkNqtkK49Bw` は 齢 96.3h で、この周に 141 → 142 と伸びました。
    伸びた直後の本は、齢がいくつでも複製が割れます。

    **中央値へ移していたら悪くなりました**（この回に数で確かめた）: 141/141/142 の中央値は
    **141** ＝ **いちばん新しい値を捨てる**。伸び中の本ではもっと重く、09/09 19:14 の
    `gv1u7n_pCAQ`（637 対 829・**192回**）は 3回 読みの並び次第で中央値が 637 に落ちます
    ＝ **`max` が直した当の -74回 の誤りへ戻ります。**

    **分ける物差し（2026-09-10 13:4x に、周の数から移した ——`_lag_evidence` の註）:
    低い読みが、その本が この窓（`ENVELOPE_LAG_H` 6時間）で通った値か。**
    再生は減らないので、遅れた複製が返せるのは「窓の先頭の値 以上・いまの値 以下」だけ:

        低い読み ≧ 窓の先頭の値   → **遅れ**（`lag`）
        低い読み < 窓の先頭の値   → **第3の口**（`still`。遅れでは説明が付かない）

    **10:2x はここに「推定が動かなかった周の数」を置きました。それは代理で、
    13:4x に実物で外れました** —— `1huadpEk6HY`（齢 148.1h・**5 対 6**）は 5 が 11周 続いて
    12:04 に 6 へ伸び、13:07 に割れた。高い読みは 3周 とも 6 ＝ 周の門は `still` と貼りますが、
    **低い 5 は 83分 前の台帳の行の値そのもの**でした。**遅れは周ではなく時間で起きるので、
    周で数えると「伸びるのが遅い本」ほど第3の口に化けます**（3周 は速い本で 1.7時間・
    6日に1回しか伸びない本では複製が古い値に座る窓のほうが長い）。
    `rounds` は返り値に残してあるので、2つが割れた行は次の回が列挙で比べられます。

    **実物 15行 の列挙（13:4x に撃ち直した）: 15行 とも `lag`**（低い読みは 窓の先頭 から
    0.09〜2.55時間 前に台帳がそのまま持っていた値 ＝ §6 の「複製の遅れの実測 最大 2.8時間」の中）。
    **周の門と範囲の門は 14/15 で一致し、割れたのは `1huadpEk6HY` の 1行 だけ**でした。

    **実物 10行 の列挙（この回に撃った・§5 の教訓の形 4つ目「直した門が実物のどの形を通るかを
    台帳から列挙して確かめる」）**: 台帳の `n_values > 1` は **10行** で、**10行 とも `lag`**。
    うち **7行 はこの周に推定が伸びた行**（468→501・510→512・510→523・523→524・532→534・
    141→142・927→928）、**3行 は 1〜2周 前に伸びた行**（637 対 829/886 の 2行 と 512 対 523）。
    **`still` は 0行。** ＝ **(3) は「引かれた」まま、分子は 0 です。**

    **`recounts()` とは別の口です**: `recounts` は**周と周のあいだ**の数え直しを包絡で見つけ
    （いま 5本）、こちらは**同じ周の 3回 読みの中**を見ます。数え直しは秒の間隔では起きないので、
    **この道が第3の口を見るとしたら、それは「落ち着いた本の複製が割れる」形だけ**です。

    **【2026-09-10 19:0x・optimizer・Opus】`still` が初めて 1行 出て、
    その札だけでは分子に数えられないことが分かりました。`confirmed` を足しました。**
    **引いた数**: 18:38 の `measure` で **`CIPYV_r1Hdo` 齢 101.6h・290 対 287・n=2**。
    287 は台帳に 1度も無く（**24周 続けて 290**）、窓の先頭も 290 なので `_lag_evidence` は
    「遅れでは説明が付かない」＝ `still`。**`recounts()` はこの本を挙げていません。**
    **ところが `recounts()` は、挙げられません** —— あれは生が包絡を
    **`ENVELOPE_LAG_H`（6時間）より長く下回ったまま戻らなかった**峰を拾うので、
    **数え直しが始まった瞬間の `hours_below` は 0** です。
    ＝ **`recounts()` との join が捕まえられるのは「2度目以降の数え直し」だけ**で
    （17:3x が当てた `lywTMXD6WDM` は、1度目の 216→214 が **74.0時間** 前に確定していた）、
    **どの本の 1度目の数え直しも、その瞬間には必ず `still` と貼られます。**
    ＝ **`still` は「第3の口」ではなく「まだ分けられない」の札です。**
    **17:3x の `_settled_after` は、この決着の付け方を既に書いていました**
    （覆る条件 (2)「`after == "high"` の行が出たら、**そこで初めて第3の口**」）——
    **その決めが `shakes_line` の印字に入っておらず**、`after` が `None`（＝ あとの点が無い）でも
    「**第3の口が出ています ＝ 覆る条件 (3) が本当に引かれました**」と言い切っていました
    （同じ文の中で「この回では言えない」とも印字していた ＝ METHOD が repo でいちばん多い
    壊れ方と呼ぶもの・**言っている所と、している所が別**）。
    **値段**: §7 (h) の「`still` が 1行 でも出たら `settle_stats` の側」に従うと、
    max → 中央値 へ移すことになります。**この関数の上の実測が、それは悪くなると数で示しています**
    （141/141/142 の中央値は 141 ＝ いちばん新しい値を捨てる・637 対 886 では **-249回** へ戻る）。
    → **分子は `confirmed`（`still` かつ `after == "high"`）だけ。**
    `still` で `after` がまだ無い／`between` の行は **保留**（決着待ち）で、
    `settle_stats` を動かす理由になりません。

    **【2026-09-10 20:2x・optimizer・Opus】その `confirmed` が 1行 出て、
    **同じ行が「中央値へ移す」を否定しました。分子は `over_max` へ移します。**
    **引いた行**: `CIPYV_r1Hdo` 齢 101.6h（290 対 287）—— 18:38 に `still`、
    19:15 の 3回 読みは **3回とも 287**、19:52 でまた 290 と 287 に割れ、
    `_settled_after` は `after == "high"` ＝ `confirmed` を立てました。
    **そこで実物 28行 の `after` を列挙したら、決着は 27行 で、
    26行 が `high`・1行 が `low`（数え直しの本 `lywTMXD6WDM`）でした。**
    ＝ **低い読みは、決着した 26/27 で「捨ててよい側」**。`max` はその 26行 で正しく、
    中央値は 1行（数え直し）でだけ速く、その 1行 は `recounts()` が 6時間 で自分で直します。

    **そして、どちらへ決着しても中央値の出番はありません**（これがこの回の要点）:

        あとの点が **高い側** へ戻った  → 低い読みは一過性のごみ ＝ **`max` が正解**
        あとの点が **低い側** で水準に  → それは数え直し ＝ **包絡を落とすのは `recounts()` の仕事**
                                        （`max` は最大 `ENVELOPE_LAG_H` だけ遅らせる・値は間違えない）

    ＝ **`n_values` の割れは、`settle_stats` を `max` から動かす理由になりません。**
    動かす理由になるのは **「`max` が、その本の確定した水準より高い値を台帳に書いた」**回だけで、
    それが `over_max`（その本を `recounts()` が挙げていて、その行の `high` が `to` より上）です。
    **実測 いま 0行**（唯一の候補 `lywTMXD6WDM` は high 214・`to` 214 ＝ 越えていない）。

    **【2026-09-11 03:0x・optimizer・Opus】その `over_max` が 3行 出て、**
    **3行 とも「数え直しの手前の平ら」でした ＝ 分子ではありません。門を1つ 足しました。**
    **引いた行**（`CIPYV_r1Hdo`・水準は 290 → 287）: 齢 **101.6h / 102.9h / 103.5h**。
    数え直しが確定した齢（`recounts()` の `age_h` ＝ 峰を最後に見た点）は **103.5h** で、
    **3行 とも その手前か、その点そのもの**です ＝ **その時刻の本当の値は 290 でした。**
    `max` は間違えていません（**うち 2行 は `after == "high"` ＝ 同じ関数が「`max` が正解」と
    印字しながら、同じ行を分子に数えていた** —— 言っている所と、している所が別）。
    **構造として必ずこうなります**: `recounts()` の `to` は**最後に落ち着いた水準**なので、
    水準が落ちる前の点は **どれも `hi > to`**。＝ 20:2x の分子は
    「その本がいつか数え直されたか」を数えており、**`after == "low"`（数え直しで決着 ＝
    包絡を落とすのは `recounts()` の仕事）と同じ物**を別の名前で数えていました。
    **足した門**: その値を**台帳が窓（6時間）の先頭で持っていなかった**こと（`_lag_evidence` の
    `floor`）。＝ 分子は「**水準が落ちたあとに、`max` が古い複製の値を掘り起こして書いた**」行だけ。
    実測 いま **0行**（3行 とも floor 290 ＝ 掘り起こしではない）。
    **陽性対照も差し替えました** —— 20:2x の陽性対照は `_flat` を **290**（＝ 落ちる前の平ら）で
    組んでおり、**分子と同じ間違いを、検査のほうでも作っていました**（§5 の教訓の形4つ目:
    手で作った検査データは、書き手が知っている形にしかならない）。いまは **287 の平ら → 290 を書いた行**
    （掘り起こし）で撃ち、落ちる前の平らのほうは**陰性**で押さえています。

    **【2026-09-12 13:3x・optimizer・Opus】その (1) が実物で引かれ、`settle_stats` は動かしませんでした。**
    **門は「行の数」から「大きさ」へ移ります**（`over_verdict` ＝ 掘り起こしの最大 ÷ 割れの最大・門 10%）。
    引いた行・数・決め・新しい覆る条件 4つ は **`over_verdict` の註**（ここには写さない）。
    要点だけ: 掘り起こし **1回** 対 `max` が直している割れ **249回** ＝ **0.4%** で、
    **2つとも一過性**（低く書けば次の周の包絡が、高く書けば `recounts()` が 6時間 で直す）＝
    **残るのは大きさだけ**なので、回数で倒す門は比べる量を見ていませんでした。
    **同じ回に測った、03:0x の `floor` の門の穴**（直していません・次の回へ）:
    **水準が本当に落ちた本で、落ちたあとに `to` と `top` のあいだの値を書いた行は取り逃します**
    （窓の先頭がまだ峰なので `hi > floor` が偽）。合成で撃って確かめた ——
    峰 290 を齢 100h で最後に見て 287 へ落ちた本の 齢 101h（287 対 289）＝ `over_max` False。
    **実物には 1行 も無いので直していません**（直すなら「`recounts()` の `age_h` より あと」を
    `floor` と **or** で並べること。**and で並べると、いま効いている 03:0x の形が消えます**
    —— 掘り起こしの多くは `hi == top` で、その行は構造として `age_h <= recounts の age_h` です）。

    **覆る条件**: (1) **`over_verdict()["drawn"]` が立ったら**（＝ 大きさが門を越えたら）、
    そこで初めて `settle_stats` の覆る条件（`reads` を 5 に上げてから最大ではなく中央値へ）へ進みます。
    **行が出ただけでは引きません**（13:3x の決め）。**`still` でも `confirmed` でも、
    数え直しの手前の平らでも引きません**（上の 19:0x・20:2x・03:0x の実測）。
    (1-c) 逆に、**掘り起こしの大きさが門を越えないまま 数え直しが 10本 を越えたら**、この分子は
    「起きない事」を見張っているだけ ＝ `settle_stats` の覆る条件ごと閉じてよい
    （**いま 7本**・13:3x に `EkNqtkK49Bw` 146→145 が入った。数は `recounts()` を撃って読むこと）。
    (1-b) 保留の行が **7本 のうちに 3行** を越えて溜まったら、決着が付かない形が普通 ＝
    `_settled_after` の見る先（あとの点）を、点の数ではなく時間（`ENVELOPE_LAG_H`）で切ること。
    (2) `lag` の行の低いほうが、**その本について台帳が前に書いた値のどれとも一致しない**回が
    出たら、低い側は「遅れた複製」ではない ＝ この物差しごと疑うこと。
    (3) 推定が動かない周が `SETTLED_ROUNDS` より長く続く本が普通になったら（＝ 平らが伸びた）、
    3周 では「落ち着いた」を捉えきれない ＝ 周の数を `flats` の境目（いま 60.4時間）に合わせること。
    """
    out: list[dict] = []
    rec_rows = recounts(rows)
    recounted = {r["id"] for r in rec_rows}
    # **確定した水準**（数え直しが落とした先）。挙がっていない本は「まだ分からない」ので入れない。
    levels = {r["id"]: int(r["to"]) for r in rec_rows}
    for vid, pts in series(rows).items():
        for k, p in enumerate(pts):
            if int(p.get("n_values", 1)) <= 1:
                continue
            lo = int(p["views_min"]) if "views_min" in p else int(p["views"])
            hi = int(p["views"])
            window = [int(q["views"]) for q in pts[max(0, k + 1 - SETTLED_ROUNDS):k + 1]]
            # **分けるのは「低い値を、台帳が前に持っていたか」**（2026-09-10 13:4x に
            # 周の数から移した。`held_before` の註・この関数の覆る条件 (2) が正本だった）。
            ev = _lag_evidence(pts, k, lo)
            # **覆る条件 (1)（「その行の本を `recounts()` も挙げているかを先に見ること」）を、
            # 次の回が手で見なくてよいように、ここで当てる**（2026-09-10 17:3x・`_settled_after` の註）。
            if ev["explained"]:
                verdict = "lag"
            elif vid in recounted:
                verdict = "recount"
            else:
                verdict = "still"
            after = _settled_after(pts, k, lo, hi)
            # **分子は札ではなく決着**（2026-09-10 19:0x・上の註）。`recounts()` は
            # 6時間 下回るまで挙げないので、**1度目の数え直しは、その瞬間 必ず `still`**。
            # 第3の口と言えるのは、あとの点が**高い側へ戻った**ときだけ。
            confirmed = verdict == "still" and after == "high"
            # **`settle_stats` を `max` から動かす唯一の分子**（2026-09-10 20:2x・
            # **2026-09-11 03:0x に門を1つ 足した**・上の註）—— その本の確定した水準
            # （`recounts()` の `to`）より `max` が書いた値のほうが高く、**かつ その値を
            # 台帳が窓（`ENVELOPE_LAG_H`）の先頭で持っていなかった**行。
            # 後半が無いと、**数え直しの手前の平らが丸ごと分子に入ります**（水準が落ちる前は
            # `hi > to` が構造的に必ず立つ ＝ 20:2x の分子は「1度目の数え直し」を数え直していた）。
            over_max = (vid in levels and hi > levels[vid]
                        and ev["floor"] is not None and hi > ev["floor"])
            out.append({
                # **掘り起こしの大きさ**（`max` が確定した水準より何回 高く書いたか）。
                # 2026-09-12 13:3x に足した ——(1) は行の**数**しか見ておらず、
                # **1回 の掘り起こしで、249回 を直している側の物差しを倒せる形**でした
                # （`over_verdict` の註）。0 は「掘り起こしではない」。
                "over_by": (hi - levels[vid]) if over_max else 0,
                "id": vid,
                "age_h": float(p["age_h"]),
                "at": p.get("at", ""),
                "low": lo,
                "high": hi,
                "span": hi - lo,
                "rounds": window,
                "floor": ev["floor"],
                "held_h": ev["held_h"],
                "recounted": vid in recounted,
                "after": after,
                "verdict": verdict,
                "confirmed": confirmed,
                "over_max": over_max,
            })
    return out


#: **掘り起こしが `settle_stats` を動かす大きさの門**（2026-09-12 13:3x・optimizer・Opus）。
#: 掘り起こしの最大（`over_by`）が、**同じ台帳の割れの最大（`span`）**の
#: これだけの割合を越えたら、そのとき初めて「最大 → 中央値」を引き比べる。
#: **なぜ割合か**: 2つは**同じ台帳から出る、向きの違う誤差**で、どちらも一過性です
#: （低く書けば次の周の包絡が直す・高く書けば `recounts()` が 6時間 で直す）。
#: **残るのは大きさだけ**なので、比べるのは回数ではなく大きさ ＝ この比。
#: 実測 2026-09-12 13:3x: 掘り起こし **1回** 対 割れ **249回** ＝ **0.4%**（門 10%）。
OVER_SIZE_GATE = 0.10


def over_verdict(rows: list[dict]) -> dict:
    """**掘り起こしが `settle_stats` を動かす大きさに達しているか**（API 0単位）。

    **【2026-09-12 13:3x・optimizer・Opus】`shakes` の覆る条件 (1) が実物で引かれ、
    引いた数を見たら `settle_stats` を動かす理由になりませんでした。** 引いた行:
    `EkNqtkK49Bw` 齢 134.9 / 137.5 / 137.9 / 138.3h（**145 対 146**）——
    145 が 14時間 続いたあと 145/146 が 3.4時間 ゆれ、145 で落ち着いて
    `recounts()` が 146 → 145 を挙げた（この台帳の **7本目**の数え直し）。
    **門（`floor` ＝ 窓の先頭より上）は正しく当たっています** —— 落ちる前が平らな形
    （`CIPYV_r1Hdo`・03:0x）とは別の形で、**これは本物の掘り起こし**です。

    **それでも最大を中央値へ移さないのは、大きさが釣り合わないからです**（撃った数・API 0単位）:

        `max` が直している側（遅れた複製）   同じ周の割れの最大 **249回**
                                            （`gv1u7n_pCAQ` 齢 10.0h・637 対 886）
                                            実測 09/09 19:1x は 637/823 が **6回ずつ**
                                            ＝ **5回 読みの中央値は五分五分で低い側**
        `max` が作っている側（掘り起こし）    **1回**（146 対 水準 145）

    ＝ **中央値へ移すと、1回 を直すために 249回 を落としうる。**
    しかも **2つとも一過性**です —— 低く書いた点は次の周の包絡が上書きし（床 55分）、
    高く書いた点は `recounts()` が `ENVELOPE_LAG_H`（6時間）で落とします。
    **残る差は大きさだけ**なので、**(1) の「1行 でも出たら」は回数の門で、
    比べるべき量を見ていませんでした。**

    **決め: 門を大きさへ移す。** 掘り起こしの最大が、同じ台帳の割れの最大の
    `OVER_SIZE_GATE`（10%）を越えた回に、そこで初めて `reads` 5 と中央値を引き比べる。
    **`reads` は 3 のまま・`settle_stats` は最大のまま**（`studio/yt.py` の註にも同じ決め）。

    **覆る条件**: (1) この比が門を越えたら、その回に `reads=5` を撃って
    **同じ周の 5つの読みの中央値と最大**を並べること（+2単位/周・伸び中の本を必ず含める）。
    (2) 掘り起こしが **3本 以上 の別々の本**で出たら、形が「古い平らな本の 1回」ではない ＝
    比が門の下でも、その回に形を見直すこと（いま **1本**）。
    (3) 割れの最大（分母）が **10回 を下回る**台帳になったら、比そのものが読めません ＝
    そのときは絶対値（掘り起こし **5回** 以上）で切ること。
    (4) `recounts()` が 6時間 で直せない掘り起こし（＝ 高い値が 6時間 より長く居座る）が
    出たら、一過性という前提が外れる ＝ この段ごと引き直すこと。
    derivation は JOURNAL 2026-09-12 13:3x。
    """
    sh = shakes(rows)
    over = [s for s in sh if s["over_max"]]
    worst_over = max((int(s["over_by"]) for s in over), default=0)
    worst_span = max((int(s["span"]) for s in sh), default=0)
    ratio = (worst_over / worst_span) if worst_span else 0.0
    return {
        "rows": len(over),
        "ids": sorted({s["id"] for s in over}),
        "worst_over": worst_over,
        "worst_span": worst_span,
        "ratio": ratio,
        "drawn": bool(worst_over) and ratio >= OVER_SIZE_GATE,
    }


def shakes_line(rows: list[dict]) -> str:
    """`shakes()` を1行で（`report()` が毎周 印字する ——§7 (h) の覆る条件 (3) を、
    撃つだけで分母と分子まで読めるように。次の回は覚えていなくてよい）。"""
    sh = shakes(rows)
    still = [s for s in sh if s["verdict"] == "still"]
    confirmed = [s for s in still if s["confirmed"]]
    pending = [s for s in still if not s["confirmed"]]
    rec = [s for s in sh if s["verdict"] == "recount"]
    over = [s for s in sh if s["over_max"]]
    if not sh:
        return ("**同じ周に割れた読み（`n_values > 1`）: 0行** ＝ §7 (h) の覆る条件 (3) の分子は **0**"
                "（`trend.shakes` の註。分けるのは齢でも周の数でもなく、**低い読みを台帳がこの窓で通ったか**）。")
    worst = max(sh, key=lambda s: s["span"])
    old = [s for s in sh if s["age_h"] > 48]
    lag_n = len(sh) - len(still) - len(rec)
    after_txt = {"low": "低い側が水準になった ＝ **数え直しで決着**",
                 "high": "高い側が続いた ＝ **低い読みは一過性**（`max` が正解・20:2x）",
                 "between": "あいだに落ちた ＝ まだ言えない",
                 None: "**あとの点がまだ無い ＝ この回では言えない**"}
    tail = ""
    if rec:
        tail += ("**数え直しの本で割れています**（`recounts()` が同じ本を挙げている ＝ "
                 "`trend.shakes` の覆る条件 (1) を道具が当てた側。**第3の口には数えません**）: "
                 + "・".join(
                     f"{s['id']} 齢 {s['age_h']:.1f}h（低い {s['low']} は窓の先頭 {s['floor']} より下・"
                     f"{s['low']} 対 {s['high']}。あとの点: {after_txt[s['after']]}）" for s in rec)
                 + "。**この本の再生は実測で1度 下がっているので、「再生は減らない」を前提にした窓の門は当たりません** ——"
                 "2度目の数え直しなら**低いほうが新しい値**です（`trend._settled_after` の註）。")
    if confirmed:
        tail += ("**低い読みが一過性だった行**（`still` かつ あとの点が高い側へ戻った ＝ "
                 "**`max` が正しかった側**。2026-09-10 20:2x に分子から外しました）: "
                 + "・".join(
                     f"{s['id']} 齢 {s['age_h']:.1f}h（低い {s['low']} は窓の先頭 {s['floor']} より下 ＝ "
                     f"遅れでは説明が付かない・{s['low']} 対 {s['high']}。あとの点: {after_txt[s['after']]}）"
                     for s in confirmed)
                 + "。**これは `settle_stats` を動かす理由になりません** —— 決着が高い側なら低い読みは"
                 "捨ててよい側・低い側で水準になれば それは数え直しで、包絡を落とすのは `recounts()` の仕事です"
                 "（`trend.shakes` の 20:2x の註）。")
    if over:
        ov = over_verdict(rows)
        tail += ("**水準が落ちたあとに `max` が古い複製の値を掘り起こした行が出ました**: "
                 + "・".join(f"{s['id']} 齢 {s['age_h']:.1f}h（書いた {s['high']} ＞ 確定した水準 "
                             f"かつ 窓の先頭 {s['floor']} より上 ＝ **+{s['over_by']}回**）"
                             for s in over)
                 + "。**数え直しの手前の平らは、ここに入りません**（2026-09-11 03:0x の門・"
                 "`trend.shakes` の註）。"
                 + (f"**掘り起こしの最大 {ov['worst_over']}回 対 割れの最大 {ov['worst_span']}回 ＝ "
                    f"{ov['ratio'] * 100:.1f}%**（門 {OVER_SIZE_GATE * 100:.0f}%・本 {len(ov['ids'])}本）"
                    + ("** ＝ 門を越えました。この回に `reads=5` の中央値と最大を引き比べること**"
                       "（`trend.over_verdict` の覆る条件 (1)）。"
                       if ov["drawn"] else
                       "** ＝ 門の下 ＝ `settle_stats` は最大のまま・`reads` は 3 のまま**"
                       "（2026-09-12 13:3x の決め。**2つとも一過性で、残る差は大きさだけ** ——"
                       "低く書いた点は次の周の包絡が、高く書いた点は `recounts()` が 6時間 で直します。"
                       "**回数では動かさないこと**・`trend.over_verdict` の註）。")))
    if pending:
        tail += ("**保留（決着待ち）の割れが在ります —— これは「第3の口」ではありません**: "
                 + "・".join(
                     f"{s['id']} 齢 {s['age_h']:.1f}h（低い {s['low']} は窓の先頭 {s['floor']} より下・"
                     f"{s['low']} 対 {s['high']}。あとの点: {after_txt[s['after']]}）" for s in pending)
                 + "。**`recounts()` が挙げていないことを「数え直しではない」と読まないこと** ——"
                 "`recounts()` は生が包絡を 6時間 より長く下回るまで挙げないので、"
                 "**どの本の 1度目の数え直しも、その瞬間は必ずこの形**になります"
                 "（`trend.shakes` の 19:0x の註）。**分子は 0 のままで、`settle_stats` は動かさないこと** ——"
                 "決着は `_settled_after` があとの点で付けます（低い側が水準になれば数え直し ＝ `recounts()` の側・高い側へ戻れば低い読みが一過性 ＝ `max` の側。**どちらでも `settle_stats` は動きません**・20:2x）。")
    if not rec and not still:
        tail += ("**齢 48h 超の行が割れても、低いほうがこの窓で本が通った値なら遅れの側です** ——"
                 "この道の分子は **0** のまま（`trend.shakes` の覆る条件 (1)）。")
    return (f"**同じ周に割れた読み（`n_values > 1`）: {len(sh)}行**（うち齢 48h 超 **{len(old)}行**）"
            f" —— **遅れ {lag_n}行 / 数え直しの本 {len(rec)}行 / "
            f"低い読みが一過性 {len(confirmed)}行 / 保留 {len(pending)}行 / "
            f"**`max` が水準を掘り起こした行 {len(over)}行**"
            f"（＝ `settle_stats` を動かす唯一の分子・20:2x／門は 03:0x ＋ "
            f"**大きさ 13:3x**（`over_verdict`。**行の数では動かしません**））**"
            f"（`trend.shakes`。**分けるのは齢でも周の数でもなく、「低い読みを台帳がこの窓で通ったか」**"
            "・**その本を `recounts()` が挙げていれば数え直しの側**）。"
            f"いちばん大きい割れは {worst['id']} 齢 {worst['age_h']:.1f}h の **{worst['span']}回**"
            f"（{worst['low']} 対 {worst['high']}）。" + tail)

def flats(rows: list[dict]) -> dict:
    """**齢 48h 前の「平らな区間」が、そのあと伸びを取り戻したか**を数える。API 0単位。

    **なぜ（2026-09-10 08:4x JST・optimizer・Opus）**: この道具の冒頭の註は「**平らは『止まった』ではない**」を
    **2本**（`EkNqtkK49Bw` の 19時間・`nQbVxuWpWw8` の 2時間）で言っており、その覆る条件は
    「平らな区間のあとに一度も伸びない本が **3本** 続いたら、平らは本当に止まり」でした。
    **その 3本 を数える所が、どこにもありませんでした** ——しかも**文字どおり読むと、
    落ち着いた本は全部そこに当たります**（どの本も最後は平らで終わり、そのあと伸びない）。
    ＝ **引けない条件ではなく、いつでも引けてしまう条件**でした（06:3x の族の裏返し）。

    **数えられる形にした**（この回に台帳から撃った実測 —— `MINFLAT` 2.0時間・齢 48h 前）:

        EkNqtkK49Bw  齢 9.6→30.5h（**20.9時間** 平ら・127回） → **伸びた**（最終 140回）
        nQbVxuWpWw8  齢 4.4→6.6h（2.2時間・28回）           → **伸びた**（最終 66回）
        lQHX9LJ80Sg  齢 18.3→20.9h（2.6時間・393回）        → **伸びた**（最終 536回）
        lQHX9LJ80Sg  齢 30.3→33.2h（2.9時間・468回）        → **伸びた**（＝ §7 が 5周「止まった」と読んだ所）
        lQHX9LJ80Sg  齢 37.9→40.2h（2.3時間・512回）        → **伸びた**
        ＝ **戻った 5件 / 戻らないまま 6時間 以上 見た 0件**

    **【2026-09-10 08:2x に直した（optimizer・Opus）—— 下の 08:4x の形は、`stayed` を 1件も数えられませんでした】**
    門が **平らの「終わり」** に置かれていました（`ages[j] < 48.0`）。ところが
    **伸びが戻らない平らは、定義から並びの最後の点まで続きます**（途中に高い点が在れば包絡が上がり、
    それは「戻った」側）。＝ **`ages[j]` は必ず「いまの齢」**なので、落ち着いた本（齢 48h 超）の
    平らは **1件も通りません**。台帳の実測（この回に列挙した・`flats(rows)["runs"]`）:

        EkNqtkK49Bw  齢 34.6→94.2h（**59.6時間** 平ら・140回）→ 戻らない  … `ages[j]`=94.2 で**捨てられていた**
        nQbVxuWpWw8  齢  8.6→70.2h（**61.6時間** 平ら・ 66回）→ 戻らない  … `ages[j]`=70.2 で**捨てられていた**

    ＝ **いちばん強い 2件**（61.6時間 平らのまま伸びなかった本）が、両方 落ちていました。
    通れるのは「齢 24〜48h のあいだに居る本」だけで、**1本/日 では その窓に居る本は常に 1本**
    ＝ **覆る条件の「3件」は、構造として来ませんでした**（06:3x・08:4x の族の 3度目）。
    **検査が拾えなかった理由**: 08:4x の検査データには「48h の手前で始まり 48h を越えて続く平ら」が
    1つも無く（`test_48hを越えた平らは数えない` は **始まりも** 50h）、**実物の形だけが抜けていた**。

    **直し**: 門は**平らの始まり**（`ages[i] < 48.0`）に置く。「戻らないまま」は**長さ**で決める。
    **その長さの門は定数ではなく、実測でいちばん長い「戻った平ら」**（いま `EkNqtkK49Bw` の **20.9時間**）
    ——`FLAT_STOP_H`（24時間）はその床です。覆る条件 (2) を、手ではなく道具が引きます。
    **直した後の数**: 戻った **5件** / 戻らないまま **2件** / まだ見ている途中 **1件**。

    **決めに使う数は件数ではなく、境目です。** 落ち着いた本は必ず終わりの平らを 1つ 出すので、
    件数は「落ち着いた本の数」とほぼ同じに増えます（3件 は 3本目が落ち着けば来る ＝ 安い）。
    **効くのはこちら**: **戻った平らのいちばん長いもの 20.9時間** と
    **戻らなかった平らのいちばん短いもの 59.6時間** のあいだが、**まだ測れていない**。
    ＝ **20.9時間 より短い平らを「止まった」と読まないこと**（5/5 が戻っている）。
    その 2つ を `trend` が毎周 印字します（`longest_resumed_h` / `shortest_stayed_h`）。

    **（08:4x の記録）「戻らないまま」の門は `FLAT_STOP_H`（24時間）です。** ここは一度 書き損じて、撃って直しました:

      **最初に書いた形**「区間が終わってから 6時間 以上 見て、伸びが戻らなかったら数える」は、
      **一度も数えられません** —— 伸びが戻らない平らは**並びの最後まで続く**ので、
      区間の終わりはいつも最後の点で、「そのあと 6時間」は永久に来ない
      （＝ **この関数が直しに来た当のもの**を、直す側で作っていた。検査が落ちて分かった）。
      **開いている平らは、長さそのもので見るしかありません。**

      **その長さを 20.9時間 より短く取ると、`EkNqtkK49Bw` を取り逃します** ——
      この本は **20.9時間 平らだったあとに伸びました**（上の実測の1件目 ＝ いちばん強い証拠）。
      だから門は**戻った中でいちばん長い平ら（20.9時間）より上**に置く。24時間 はその margin つき。

    **覆る条件**（2026-09-10 08:2x に、件数から境目へ移した）:
    (1) **`longest_resumed_h`（いま 20.9時間）が上がったら**、そのぶん「止まったと読んでよい長さ」も上がる
    ——道具が自分で門を上げるので、書き直すのは §7 の本文だけ。
    (2) **`shortest_stayed_h`（いま 59.6時間）が下がったら**、境目は狭まる。
    **2つ が出会ったら（差が `FLAT_MIN_H` 2時間 を切ったら）、そこが「平らは止まり」の長さ** ＝ そのときに
    冒頭の註と §7 の「齢の浅い1点で本を比べないこと」を書き直すこと。いまの差は **38.7時間**。
    (3) 件数（`stayed`）は**落ち着いた本の数とほぼ同じに増える**ので、**3件 を判定に使わないこと**
    （08:4x の「3件」は、そう読むと安すぎ、`ages[j]` の門を付けると来なさすぎでした）。

    """
    mine = ours(rows)
    runs: list[dict] = []
    for vid, pts in series(rows).items():
        if vid not in mine or len(pts) < 3:
            continue
        env = envelope(pts)
        ages = [float(p["age_h"]) for p in pts]
        i = 0
        while i < len(env) - 1:
            j = i
            while j + 1 < len(env) and env[j + 1] == env[i]:
                j += 1
            # **門は平らの「始まり」に置く**（終わりではない ——下の 08:2x の実測）。
            if j > i and ages[j] - ages[i] >= FLAT_MIN_H and ages[i] < 48.0:
                runs.append({"id": vid, "from_h": ages[i], "to_h": ages[j],
                             "len_h": ages[j] - ages[i], "views": env[i],
                             "resumed": env[-1] > env[i]})
            i = max(j, i + 1)

    resumed = [r for r in runs if r["resumed"]]
    # **門は定数ではなく、実測でいちばん長い「戻った平ら」**（`FLAT_STOP_H` はその床）。
    # 覆る条件 (2)「より長い平らのあとに伸びた本が出たら門を上げる」を、手ではなく道具が引く。
    longest_back = max((r["len_h"] for r in resumed), default=0.0)
    thresh = max(FLAT_STOP_H, longest_back)
    stayed = [r for r in runs if not r["resumed"] and r["len_h"] > thresh]
    open_runs = [r for r in runs if not r["resumed"] and r["len_h"] <= thresh]
    shortest_stay = min((r["len_h"] for r in stayed), default=0.0)
    return {"resumed": len(resumed), "stayed": stayed, "open": len(open_runs),
            "thresh_h": thresh, "longest_resumed_h": longest_back,
            "shortest_stayed_h": shortest_stay, "runs": runs}


def last_rise_gap_h(pts: list[dict], env: list[int]) -> float:
    """**最後に包絡が上がってから、いまの点までの時間**（`hold` の「確定」の材料・API 0単位）。

    上がった点が 1つも無ければ、**並びの全長**（最初の点からいまの点まで）を返します
    ——「一度も伸びていない」は「平らがずっと続いている」ことなので、
    **0時間 として返すと、その本だけが門を素通りします**（`hold` の 05:4x の註）。
    """
    last_age = float(pts[-1]["age_h"])
    for i in range(len(env) - 1, 0, -1):
        if env[i] is not None and env[i - 1] is not None and env[i] > env[i - 1]:
            return last_age - float(pts[i]["age_h"])
    return last_age - float(pts[0]["age_h"])


HOLD_AGES = (6.0, 12.0, 24.0, 48.0)
#: §1 の表が「公開 6時間で最終の 70〜90%」と書いている帯。**この帯に入るかを、毎回 数で見る。**
HOLD_BAND = (70.0, 90.0)
#: §1 の表の**後半**（「48時間でほぼ止まる」）を数える齢。**2026-09-12 04:3x に `HOLD_AGES` へ足した**
#: —— それまで 6h・12h・24h しか印字しておらず、**後半の覆る条件 (2) を数える口が 1つも無かった**
#: （`late_gain` の註）。
HOLD_LATE_H = 48.0
#: §1 の 覆る条件 (2) の門: 「48h の後の伸びが **3本 続けて 5% 未満**なら、後半を戻す」。
HOLD_LATE_GATE_PCT = 5.0
HOLD_LATE_RUN = 3
#: 「その齢ちょうどの点」と見なす幅（時間）。台帳の `age_h` は 0.1 刻みなので 3分 で足りる。
#: **表示の `＊` の 0.5h とは別物** —— あちらは「読む人への注意」、こちらは**判定**に使う。
HOLD_EXACT_H = 0.05


def hold(rows: list[dict], ages: tuple[float, ...] = HOLD_AGES,
         zero: list[dict] | None = None) -> list[dict]:
    """こちらの作りの本の「齢 Nh までに、**いまの再生の何%**が付いていたか」（包絡・API 0単位）。

    **なぜ（2026-09-09 23:2x JST・optimizer・Opus が足した）**: §7 の「90秒の上限」の行は
    **「機械で測れる代わりの数は `measured` の 6時間再生／48時間再生の比」**と 09/05 から書いていますが、
    **その比を出す道具が 1つも無く**、4日 のあいだ 1度も数えられていませんでした
    （この回に手で数えて初めて出た ＝ 手で数えた数は次の回に残らない。§7 が 7周 踏んだ形）。

    **この回に出た数**（包絡・台帳ぜんぶ）:

        1本目 EkNqtkK49Bw  6h(齢4.3) **61%** / 12h 91% / 24h 91%   最終 140回（85.2h・確定）
        2本目 nQbVxuWpWw8  6h(齢4.4) **41%** / 12h 100%            最終  68回（61.2h・確定）
        3本目 lQHX9LJ80Sg  6h(齢6.0) **40%** / 12h 64% / 24h 79%   いま 510回（37.2h・**まだ伸びている**）
        4本目 gv1u7n_pCAQ  6h(齢5.3) **50%** / 12h 100%            いま 923回（13.2h・**まだ伸びている**）

    ＝ **§1 の表の「公開 6時間で最終の 70〜90%」に入った本は 0/4**。
    しかも**まだ伸びている 2本 の割合は上限です**（分母がこれから増えるので、真の割合はもっと低い）。
    §1 のその行は 08/15〜08/24 の 873本 の話で、**いまの絞られたチャンネルでは引けません。**

    **効く先**（ここが本体・数だけ置きます。判定は `hourly`・§5）:
    **齢 6h・12h の点で本の当たり外れを読まないこと。** 大きい本ほど尾が長く出ています ——
    68回 の本は 10.6h で終わり、510回 の本は 23.7h で 79%・**37.2h でもまだ +9回/1.4h**。
    §7 が「48h の点で比べる」と書いている側が、この数で支えられます（**6h ではなく 48h**）。

    **複製の遅れの向き**（`envelope` の註）: 早い齢の点は単発の読みで、真の値を**下に**外します
    （最大 28%）。＝ ここの割合は **その 28% ぶんまで上振れしうる** ——
    それでも 6h の 61/41/40/50% は、÷0.72 しても **85/57/56/69%** で、帯（70〜90%）に届くのは
    **1本目の 4.3h の点だけ**です（4.3h は 6h の点ではない）。**向きは変わりません。**

    **覆る条件**: (1) `settle_stats`（19:1x）の後に公開した本 **3本** の 6h の割合が
    70% を越えたら、上の数は「複製の遅れを見ていた」側 ＝ この註ごと数え直すこと
    （**その 3本 は 6h の点も 3回 読みで取られています** ＝ 遅れの上振れが無い）。
    (2) 48h を越えて確定した本が **5本** そろったら、分母を「いまの再生」から「48h の点」へ移すこと
    （§7 の行の文言どおりの比になる）。いまは確定 2本 だけなので、確定と伸び中を混ぜないために
    分母を「いまの再生」にして、伸び中の本には印を付けています。

    **【2026-09-11 05:4x・optimizer・Opus】「確定」を、直近2点から `flats` の境目へ移しました。**

    **踏んだ形**: この回の `measure` の 1回で、3本目 `lQHX9LJ80Sg`（齢 67.2h）の印が
    **「まだ伸びている」→「確定」**へ落ちました。**その本は 0.5時間 前に +2回 伸びています**
    （690 → 692）——落ちた理由は、**直近2点がたまたま同じ値だった**こと だけでした。
    同じ周の §7「いまの数」は同じ本を「**齢 66h でもまだ動きます**」と書いており、
    **同じ道具の 2つ の行が、同じ周に逆を言っていました**（§7 17:3x の「言っている所と、
    している所が別」の族）。

    **実測（この回・台帳ぜんぶ・API 0単位。`last_rise_gap_h`）**::

        EkNqtkK49Bw  齢 115.2h  145回   最後の伸びから **2.4時間**   ← 直近2点の形では「確定」
        nQbVxuWpWw8  齢  91.2h   66回   最後の伸びから **82.6時間**
        lQHX9LJ80Sg  齢  67.2h  692回   最後の伸びから **0.5時間**   ← この回に「確定」へ落ちた本
        gv1u7n_pCAQ  齢  43.2h  935回   最後の伸びから **1.2時間**

    ＝ **直近2点の形で「確定」だった 3本 のうち 2本 は、2.4時間 と 0.5時間 前に伸びていました。**

    **直し**: `growing` は **`flats(rows)["thresh_h"]`**（いま **60.4時間** ＝ 実測でいちばん長い
    「戻った平ら」・床は `FLAT_STOP_H` 24時間）で決める。**この道具は既に、同じ台帳から
    「20.9時間（いま 60.4時間）より短い平らを『止まった』と読まないこと」を出しています**
    （`flats` の註）—— `hold` だけが、その規則の外で 1組 の平らを「止まった」と読んでいました。
    ＝ **新しい定数は 1つも足していません**（門は `flats` が実測から引き直す）。

    **向きは変わりません**（この回に撃って確かめた）: `hold_verdict` は伸びている本に ``"in"`` を
    返さないので、実物の 4本 の判定は **帯の中 0本・帯の外 3本・分けられない 1本** のまま
    （`EkNqtkK49Bw` は挟みが帯を跨ぐので `growing` のどちらでも ``unknown``・残る 2本 は
    上限が 70% を割るので ``out``）。動いたのは**印字の印**と、上の**覆る条件 (2) の分母**
    （確定 3本 → **1本**）です。

    **覆る条件**: (3) 「確定」と印字した本が、そのあと 1回でも伸びたら、門（`flats` の境目）が
    まだ短い ＝ そのときは `flats` の覆る条件 (1) が自分で門を上げるので、ここは触らないこと。
    (4) 逆に、確定した本が 5本 そろう前に**全部の本が 60時間 以上 平らにならない**回り方に変わったら
    （1日1本 をやめる・測る刻が伸びる）、この門は「いつまでも確定しない」側に倒れます ——
    そのときは齢（例 齢 7日）で切ること。
    (5) `flats` が門を 100時間 を越える所まで上げたら、**確定は事実上 来ません** ＝
    上の覆る条件 (2) の「5本」は、そのときは齢で数え直すこと。
    """
    mine = ours(rows)
    # **「確定」の門は、直近2点ではなく `flats` の境目**（下の 05:4x の註）。
    thresh = float(flats(rows)["thresh_h"])
    out: list[dict] = []
    # **いま 0回 の本を入れる所**（渡されなければ捨てる ＝ 呼ぶ側が要るときだけ受け取る）。
    zero_out: list[dict] = zero if zero is not None else []
    for vid, pts in sorted(series(rows).items(), key=lambda kv: published_at(kv[1])):
        if vid not in mine or not pts:
            continue
        env = envelope(pts)
        last_age = float(pts[-1]["age_h"])
        last = env[-1]
        if not last:
            # **いま 0回 の本は、割合の分母が作れません**（黙って落とさず、下の行で名指しする）。
            zero_out.append({"id": vid, "age_h": last_age,
                             "day": published_at(pts).strftime("%m/%d")})
            continue
        gap = last_rise_gap_h(pts, env)
        row: dict = {
            "id": vid,
            "day": published_at(pts).strftime("%m/%d"),
            "age_h": last_age,
            "views": last,
            "since_rise_h": gap,
            "flat_thresh_h": thresh,
            # **まだ伸びている ＝ 分母がこれから増える**（割合は上限）。
            # **平らの長さで見る**（直近2点では見ない ——`flats` と同じ規則・05:4x の註）。
            "growing": last_age < 48.0 or gap < thresh,
            "at": {},
        }
        for h in ages:
            got = [(float(p["age_h"]), v) for p, v in zip(pts, env) if float(p["age_h"]) <= h]
            if not got or h > last_age:
                row["at"][h] = None
                continue
            age, val = got[-1]
            # **齢 h ちょうどの点は、めったに在りません。** 下は「h 以前の最後の点」で、
            # 真の h の値はそれ以上（再生は減らない ＝ 包絡）。**上は「h を越えた最初の点」**で、
            # 真の h の値はそれ以下。＝ この 2つ が、模型も外挿も通さない**挟み**です。
            # h ちょうどの点が在れば挟みは潰れる（下 ＝ 上 ＝ その点）。
            after = [(float(p["age_h"]), v) for p, v in zip(pts, env) if float(p["age_h"]) > h]
            if abs(age - h) <= HOLD_EXACT_H or not after:
                hi_age, hi_val = age, val
            else:
                hi_age, hi_val = after[0]
            row["at"][h] = {
                "age_h": age, "views": val, "pct": 100.0 * val / last,
                "hi_age_h": hi_age, "hi_views": hi_val, "hi_pct": 100.0 * hi_val / last,
            }
        out.append(row)
    return out


def hold_verdict(cell: dict | None, growing: bool,
                 band: tuple[float, float] = HOLD_BAND) -> str | None:
    """**その本が §1 の帯（70〜90%）に入るかを、挟みだけで決める**（2026-09-10 05:0x・optimizer・Opus）。

    返すのは ``"in"`` / ``"out"`` / ``"unknown"``（点が無ければ None）。

    **なぜ足したか（この回に踏んだ）**: `hold_lines` は「帯に入った本は **0/4**」と印字し、
    その 0/4 が §1 の表と §7 の「いまの数」に写されていました。ところが 4本 のうち
    **3本 は 6h ちょうどの点を持っていません**（齢 4.3h・4.4h・5.3h）。
    `hold` は「h 以前の最後の点」を採るので、**1.7時間 手前の点を「6h の値」として数えていた**
    ことになります。**実測（この回・API 0単位）**::

        EkNqtkK49Bw  下 齢4.3h **60.7%** / 上 齢7.0h **90.0%**   → **帯 70〜90% を跨ぐ ＝ 分けられない**
        nQbVxuWpWw8  下 齢4.4h  41.2% / 上 齢6.5h  41.2%       → 帯の外
        lQHX9LJ80Sg  齢6.0h ちょうど 39.1%                      → 帯の外
        gv1u7n_pCAQ  下 齢5.3h  49.4% / 上 齢6.3h  58.6%       → 帯の外

    ＝ **正しい数は 0/4 ではなく「帯の外 3本・分けられない 1本・帯の中 0本」。**
    23:2x の註は 1本目 を「÷0.72 しても 85%」（**帯の中の数**）と自分で書いたうえで
    「4.3h は 6h の点ではない」と外していますが、それは**数えない理由**であって
    **帯の外に数える理由ではありません**。

    **向きは変わりません** —— 帯の中と言い切れる本は **0本** のままなので、
    §1 の「6時間で最終の 70〜90%」は**いまも引けません**。変わったのは
    「4本 とも外だ」から「**3本 は外・1本 は分からない**」へ、**主張の強さ**のほうです。

    **伸びている本の扱い**: `pct` の分母（いまの再生）はこれから増えるので、
    **`pct` も `hi_pct` も上限**です。＝ 上限が帯の下より低ければ「外」と言い切れますが、
    **「中」は言い切れません**（真の値はもっと下）。だから `growing` の本に ``"in"`` は返しません。

    **覆る条件**: (1) 齢 6h ちょうど（±`HOLD_EXACT_H`）の点を持つ本が 3本 そろったら、
    挟みは潰れるので、この関数は 1点 の判定に戻してよい。
    (2) ``unknown`` の本が 3本 を越えたら、足りないのは判定ではなく**測る刻**
    （`measure` を齢 6h の近くで撃つ回り方）。
    """
    if not cell:
        return None
    lo = float(cell["pct"])
    hi = float(cell.get("hi_pct", cell["pct"]))
    b_lo, b_hi = band
    if hi < b_lo:                      # 上限が帯の下より低い ＝ 伸びていても「外」と言い切れる
        return "out"
    if growing:                        # 分母が増える ＝ 下限が下限になっていない
        return "unknown"
    if lo > b_hi:
        return "out"
    if lo >= b_lo and hi <= b_hi:
        return "in"
    return "unknown"


def late_gain(got: list[dict]) -> list[dict]:
    """**齢 48h より後に付いた割合**（§1 の表の**後半**「48時間でほぼ止まる」の分子）。API 0単位。

    **なぜ足したか（2026-09-12 04:3x JST・optimizer・Opus が、この回に踏んだ）**:
    §1 の表のこの行は **覆る条件 (2)「48h の後の伸びが 3本 続けて 5% 未満なら、後半を戻す」**を
    持ちながら、**その割合を印字する口が 1つも在りませんでした** —— `HOLD_AGES` は 6h・12h・24h で
    止まっており、`hold_lines` も `flats` も「48h の後」を数えません。
    ＝ **サブが毎周 やる仕事 (b)（覆る条件を数字で見る）が、この 1つ だけ構造的にできない。**

    **実際に何が起きていたか**: その行は自分で「**数は `trend` が毎周 印字する** —— ここにも §7 にも
    写さない」と書いたうえで、**手で数えた 2つ の割合を本文へ写して**いました
    （`lQHX9LJ80Sg` **22.5%**・`gv1u7n_pCAQ` **+1.5%**・2026-09-11 14:2x）。
    この回に数え直すと **13.4〜24.3%** と **2.1%** ＝ **どちらも古くなっています**
    （分母の「いまの再生」が伸びたため）。**口が無い数は、写されるか、消えるかのどちらかです。**

    **挟みで読む**（`hold_verdict` と同じ規則）: 齢 48h ちょうどの点はめったに無いので、
    48h の値は「48h 以前の最後の点（`pct`）」と「48h を越えた最初の点（`hi_pct`）」に挟まれます。
    ＝ **後の伸び ＝ 100 - (48h の値)** は ``[100-hi_pct, 100-pct]``。

    **伸びている本に「5% 未満」は返しません** —— 分母（いまの再生）がこれから増えるので、
    **後の伸びの割合は これから上がるだけ**（下端しか決まっていない）。
    ＝ ``over``（5% 以上）は伸びていても言い切れますが、``under`` は**確定した本にだけ**。

    **判定は `hourly`**（§5・optimizer は数を並べるまで）。

    **覆る条件**: (1) ``unknown`` の本が **3本** を越えたら、足りないのは判定ではなく
    **`flats` の境目**（確定が来ない ＝ `hold` の覆る条件 (5) と同じ側）。
    (2) 齢 48h ちょうど（±`HOLD_EXACT_H`）の点を持つ本が **3本** そろったら、挟みは潰れるので
    1点 の判定に戻してよい（`hold_verdict` の覆る条件 (1) と同じ形）。
    """
    out: list[dict] = []
    for r in got:
        c = r["at"].get(HOLD_LATE_H)
        if not c:
            continue
        lo = 100.0 - float(c["hi_pct"])   # 48h の値の**上端** ＝ 後の伸びの**下端**
        hi = 100.0 - float(c["pct"])
        growing = bool(r["growing"])
        if lo >= HOLD_LATE_GATE_PCT:
            v = "over"                    # 下端が門の上 ＝ 伸びていても言い切れる
        elif hi < HOLD_LATE_GATE_PCT and not growing:
            v = "under"
        else:
            v = "unknown"
        out.append({"id": r["id"], "day": r["day"], "lo": lo, "hi": hi,
                    "growing": growing, "verdict": v, "age_h": float(r["age_h"])})
    return out


def late_run(got: list[dict]) -> int:
    """**新しいほうから数えて、``under`` が何本 続いているか**（§1 の 覆る条件 (2) の「3本 続けて」）。

    `late_gain()` の並びは公開の順なので、**末から**数える。``unknown`` は鎖を切る
    （「5% 未満だった」と言えていないので、続いた本には数えられない）。
    """
    n = 0
    for r in reversed(got):
        if r["verdict"] != "under":
            break
        n += 1
    return n


def late_gain_line(got: list[dict]) -> str:
    """`late_gain()` を 1行 で印字する。**数は写さない ＝ 毎周 ここから読むこと**（§1 の行）。"""
    rows = late_gain(got)
    if not rows:
        return ""
    mark = {"over": "**5% 以上**", "under": "5% 未満", "unknown": "**まだ言えない**"}
    body = "・".join(
        "%s %s %s（%s%s）" % (
            r["day"], r["id"],
            ("%.1f%%" % r["lo"]) if abs(r["hi"] - r["lo"]) < 0.05
            else "%.1f〜%.1f%%" % (r["lo"], r["hi"]),
            mark[r["verdict"]],
            "・**まだ伸びている ＝ 下端**" if r["growing"] else "・確定")
        for r in rows)
    run = late_run(rows)
    return (
        f"**齢 {HOLD_LATE_H:.0f}h より後に付いた割合**（§1 の表の後半「48時間でほぼ止まる」の"
        f" 覆る条件 (2) の分子・`trend.late_gain`・API 0単位）: {body}。"
        f"**{HOLD_LATE_GATE_PCT:.0f}% 未満が新しいほうから続いているのは {run}本**"
        f"（門 {HOLD_LATE_RUN}本 ＝ **{'引かれました' if run >= HOLD_LATE_RUN else '引かれません'}**）。"
        f"**伸びている本に「{HOLD_LATE_GATE_PCT:.0f}% 未満」は返しません** ——"
        f"分母（いまの再生）がこれから増えるので、この割合は**下端しか決まっていません**"
        f"（`late_gain` の註）。**判定は `hourly`**（§5）。"
        f"**この行を §1 にも §7 にも写さないこと** —— 写した 2つ は 1日 で古くなりました（同じ註）。")


def hold_lines(rows: list[dict]) -> list[str]:
    """`hold()` を印字する。**帯に入った本の数は、写しではなく数から作る**（`hold` の註）。

    **いま 0回 の本は、割合の分母が作れないので `hold` から落ちます**
    （2026-09-11 06:0x・optimizer・Opus）——**黙って落とすと「数えた N本」が
    本の数と食い違い**、その本が この行から消えたことが どの印字にも出ません
    （§4 (0-b) の族・`first_view` の「初点が 6h より遅い本 N本 は外してあります」と同じ形）。
    **落とした本は末尾で名指しします**（見るのは §7 の (l)/(j) と `first_view` の行）。
    """
    zero: list[dict] = []
    got = hold(rows, zero=zero)
    if not got:
        return []
    out = [f"齢の割合（**いまの再生を 100% としたときに、齢 Nh までに付いていた割合**。"
           f"包絡・API 0単位・`trend.hold` の註）:"]
    lo, hi = HOLD_BAND
    tally = {"in": 0, "out": 0, "unknown": 0}
    have = 0
    for r in got:
        cells = []
        for h in HOLD_AGES:
            c = r["at"].get(h)
            cells.append("%2dh %s" % (int(h), ("%3.0f%%" % c["pct"]) if c else "  -"))
        six = r["at"].get(HOLD_AGES[0])
        v = hold_verdict(six, bool(r["growing"]))
        if v:
            have += 1
            tally[v] += 1
        # **6h ちょうどの点が無い本は、挟みで書く**（下の点だけを「6h の値」として読ませない）。
        note = ""
        if six and abs(six["hi_age_h"] - six["age_h"]) > 1e-9:
            note = "  ＊%dh の点が無い ＝ 挟み 齢%.1fh %.0f%% 〜 齢%.1fh %.0f%%（%s）" % (
                int(HOLD_AGES[0]), six["age_h"], six["pct"],
                six["hi_age_h"], six["hi_pct"],
                {"in": "帯の中", "out": "帯の外", "unknown": "**分けられない**"}.get(v, "-"))
        mark = ("・**まだ伸びている ＝ この割合は上限**" if r["growing"] else "・確定")
        if r.get("since_rise_h") is not None:
            mark += "・最後の伸びから %.1fh" % r["since_rise_h"]
        out.append("  %s %-12s %s   いま %d回（%.1fh%s）%s" % (
            r["day"], r["id"], " / ".join(cells), r["views"], r["age_h"], mark, note))
    out.append(
        f"§1 の表の「公開 6時間で最終の {lo:.0f}〜{hi:.0f}%」は、**帯の中 {tally['in']}本・"
        f"帯の外 {tally['out']}本・分けられない {tally['unknown']}本**（数えた {have}本）です。"
        f"**「分けられない」は 6h ちょうどの点が無く、挟みが帯を跨いだ本** ——"
        f"「帯の外」に数えないこと（`trend.hold_verdict` の註・2026-09-10 05:0x に 0/4 から直した）。"
        f"**齢 6h・12h の点で本の当たり外れを読まないこと** ——大きい本ほど尾が長く出ています。"
        + ("**いま 0回 の本 %d本（%s）は分母が作れないので外してあります** ——"
           "**「数えた %d本」を本の数と読まないこと**（`first_view`・§7 (l)(j) で見ること）。"
           % (len(zero), "・".join("%s 齢%.1fh" % (z["id"], z["age_h"]) for z in zero), have)
           if zero else "")
        + (f"**「確定」＝ 最後の伸びから {got[0]['flat_thresh_h']:.1f}時間 超**"
           "（`flats` の境目・05:4x）——**直近2点の平らで「止まった」と読まないこと**。"
           if got else ""))
    # **§1 の表の後半（「48時間でほぼ止まる」）の分子**（`late_gain` の註・2026-09-12 04:3x）。
    late = late_gain_line(got)
    if late:
        out.append(late)
    return out


FIRST_VIEW_EARLY_H = 6.0
"""この問いに答えられる本の門 —— 台帳の**初点**がこの齢より浅い本だけ。"""

SHORT_MAX_S = 180.0
"""**Shorts フィードに乗る尺の上限**（`scripts/zero_start.py` の同名と同じ数・門は 1か所のはずなので
`tests/test_trend_first_view_length.py` が **2つ が食い違ったら鳴らします**）。
`scripts/` は `studio` を import しない造りなので（`scripts/*.py` 全部で 0件・
2026-09-12 06:5x に数えた）、**借りずに写し、検査で縛る**形にしてあります
（09/11 21:1x の「借りた物を借りた形で返していない」を踏まないため）。"""

UPLOADED_JSONL = ROOT / "data" / "uploaded.jsonl"


def durations(rows: list[dict], uploaded: list[dict] | None = None) -> dict[str, tuple[float, str]]:
    """id → （尺の秒, 出どころ）。**分かる本だけ**（分からない本は入れない）。**API 0単位**。

    2026-09-12 06:5x JST・optimizer・Opus。**口は 2つ**（どちらも repo の中・
    `scripts/zero_start.durations` と同じ 2つ）:
      * `data/uploaded.jsonl` の `duration_s`（旧道具が上げたときに書いた秒。873本 中 **353本**）
      * 台帳 `scheduled`（video_id ↔ 台本の id）→ 台帳 `built` の `seconds`（studio の本）

    **なぜ `trend` の側にも要るか**: `zero_start` は 09/11 08:0x に尺で列を割りましたが、
    **毎周 印字される `first_view` は割っていません**。§7 の「いまの数」が毎周 写している
    「**0回 のまま門を越えたのは N本**」の N に、**1580秒（26分20秒）の長尺 `fMlY_uzHOMw` が
    90秒 の Short `2YZ_4FXC-XI` と同じ列で数えられて**いました（この回に `videos.list` 1単位 で
    当て直して確かめた: `PT26M20S` 対 `PT1M30S`・privacy は両方 public）。
    ＝ METHOD §5 の「**絞りを 1つ 書いた道具は、書いた絞りの側だけ守ります**」の 3例目。
    """
    if uploaded is None:
        uploaded = []
        if UPLOADED_JSONL.exists():
            for line in UPLOADED_JSONL.read_text(encoding="utf-8").splitlines():
                line = line.strip()
                if not line:
                    continue
                try:
                    uploaded.append(json.loads(line))
                except ValueError:
                    continue
    out: dict[str, tuple[float, str]] = {}
    for r in uploaded:
        vid, d = r.get("video_id"), r.get("duration_s")
        if vid and isinstance(d, (int, float)) and not isinstance(d, bool):
            out[vid] = (float(d), "uploaded.jsonl")
    built: dict[str, float] = {}
    sched: dict[str, str] = {}
    for r in rows:
        if r.get("event") == "built" and r.get("id") and isinstance(r.get("seconds"), (int, float)):
            built[r["id"]] = float(r["seconds"])
        elif r.get("event") == "scheduled" and r.get("id") and r.get("video_id"):
            sched[r["video_id"]] = r["id"]
    for vid, script_id in sched.items():
        if script_id in built:
            out[vid] = (built[script_id], "台帳 built")
    return out


def first_view(rows: list[dict]) -> dict:
    """**1回目の再生が付いた齢**を、早い点を持つ本だけで挟む。API 0単位。

    **なぜ（2026-09-10 14:0x JST・optimizer・Opus）**: この回の 5本目 `2YZ_4FXC-XI` が
    **齢 3.9h で 0回**でした。§7 (c) はそれを「4本目（2.5h で 112〜115回）と違う形」とだけ
    書いていますが、**比べる相手は 4本目 1本 ではありません** —— 台帳には
    **早い点を持つ本が 7本** 在り、その全部を並べれば「0回 のまま 3.9h」がどれだけ外れかが数で出ます。
    前の回の「Shorts の配りは 齢 1.5〜2.5h に来ます」が **n=1** で書かれ、次の回に
    「n を書かずに引かないこと」と直された所そのものです。**ここが n を持ちます。**

    **挟みで読む理由**: 測りは 42分 間隔（`quota` の床）なので、「1回目が付いた齢」は
    **点では出ません** —— 出るのは「最後に 0 を読んだ齢」と「初めて >0 を読んだ齢」のあいだ、
    という**幅**だけです。初点が既に >0 の本は下端が無いので `lo=None`（「初点より前」）。

    **`returned_private` の本は落とします**（`Yy7GmcGoQ6I` ＝ 0.1h で private へ戻した本。
    その 0回 は「配りが来なかった」ではない ——`returned_private` の註の当のもの）。

    **返り値の `books` は判定した実物そのもの**（§5 の教訓の形 4つ目 —— 次の回が列挙で確かめられる）。

    **「いま N回」は `ceiling()`（数え直しを落とした水準）で読みます**
    （2026-09-10 20:5x JST・optimizer・Opus が直した）: もとは点の生の `max` で、
    **同じ `trend` の出力の中で、齢の割合の行と 1本だけ食い違っていました** ——
    `nQbVxuWpWw8` を この行が **68回**・`hold` の行と `lines()` の並びが **66回**
    と印字しており、その 2 の差は `recounts()` が既に落とした峰（68 → 66）そのものです。
    **`recounts()` が挙げた本は、ここでも落ちていなければなりません** ——
    この行の `views` は §7 (c) の覆る条件 (1)（0回 のまま門を越えた本がそのあと伸びたか）を
    読む数なので、生の `max` のままだと**数え直しを「伸び」と読む口**が残ります。

    **この行は「当たり外れ」を言いません**（判定は `hourly`・§5）。言うのは
    「1回目が付いた齢は、これまで何時間の側だったか」だけです。

    **決め（2026-09-12 11:1x JST・optimizer・Opus）: 「0回 のまま門を越えた」に数えるのは、
    いちばん深い齢が `FIRST_VIEW_EARLY_H` を越えた本だけ**（`through_gate`）。
    **まだ門の手前の本は `zero_early` に置き、`zero` にも `zero_short` にも入れません。**
    **踏んだ形**: 09/12 11:0x に `zero_short` が **2本**（`2YZ_4FXC-XI` 49.0h と
    **その朝 10:00 に公開した `4l3DDCLIRxg` 1.0h**）と出ました。§7「形」の 決め (5-2) は
    「**0回 の Shorts が 2本目 出たら** 配りの側へ移る」で、その分子は §7 (l-2) のとおり
    **この `zero_short` の数**です ＝ **公開 1時間 の本が、形の判定を 1つ 引き倒す所**でした
    （1回目が付いた 5本 は**どれも 齢 5.0h まで**・門は 6.0h ＝ 1.0h は「来なかった」ではない）。
    **これは毎日 10:00〜16:00 JST に出ます**（きょうの本が門の手前に居るあいだ）。
    **門は 1か所**（`FIRST_VIEW_EARLY_H` ＝ 入口の門と同じ数）。
    **数は落としません** —— 門の手前の本も列に 1行 出し、印字が「まだ門の手前」と言います
    （§5 教訓の形 7つ目: 註だけに書くと、読まれるのは印字のほう）。
    **覆る条件**: (5) 門の手前で 0回 の本が、門を越える前に伸びた回が **3本** 続いたら、
    門の手前の行そのものが要らない（印字から外す）。(6) 逆に、門の手前で 0回 だった本が
    門を越えても 0回 のままだった回が **3本** 続いたら、門を待つ値打ちが無い ＝ 門を
    `latest_first`（実測の上端・いま 5.0h）まで下げてよい。(7) `FIRST_VIEW_EARLY_H` を
    動かす回は、`zero` の数がその回に変わるので、**§7「形」の (5-2) を一緒に読み直すこと**。

    **覆る条件**: (1) **`zero` の本（0回 のまま門を越えた本）が、そのあと伸びた回が
    1度でも出たら**、この行は「まだ来ていない」以上のことを言えない ＝ 印字だけ残して
    §7 の判定から外すこと。(2) 早い点を持つ本が **8本** を越えたら、挟みではなく
    「初めて >0 の齢」の**中央値**で読む（いまは n が小さく、挟みが 2時間 幅で開いている）。
    (3) 挟みの幅の中央値が **1時間** を切ったら（＝ 測りが密になったら）、幅ではなく上端で読んでよい。
    (4) `FIRST_VIEW_EARLY_H` を越えた所で初めて測った本ばかりになったら（`late` が
    `early` より多い周が 3周 続いたら）、この門は測り方の側を測っています ＝ 門ではなく
    `measure` を撃つ齢のほうを直すこと。
    """
    gone = set(returned_private(rows))
    mine = ours(rows)
    durs = durations(rows)
    early: list[dict] = []
    late = 0
    for vid, pts in series(rows).items():
        if vid in gone:
            continue
        good = [r for r in pts if isinstance(r.get("views"), int)]
        vals = [(float(r["age_h"]), r["views"]) for r in good]
        if not vals:
            continue
        vals.sort()
        if vals[0][0] > FIRST_VIEW_EARLY_H:
            late += 1
            continue
        pos = [a for a, v in vals if v > 0]
        zeros = [a for a, v in vals if v == 0]
        hi = min(pos) if pos else None
        lo = max([a for a in zeros if hi is None or a < hi], default=None)
        sec, src = durs.get(vid, (None, None))
        early.append({
            "id": vid, "new": vid in mine,
            "first_age_h": vals[0][0], "first_views": vals[0][1],
            "lo": lo, "hi": hi,
            "zero_through_h": max(zeros) if (zeros and hi is None) else None,
            # **門を越えたか**（いちばん深い齢が門より深いか）——「0回 のまま門を越えた」と
            # 「まだ門の手前」を分ける唯一の欄（2026-09-12 11:1x・下の註）。
            "through_gate": vals[-1][0] > FIRST_VIEW_EARLY_H,
            "views": ceiling(good),
            "day": published_at(pts).strftime("%m/%d"),
            # 尺（**分からない本は None** ＝ 「短い」と決めつけない・`durations` の註）。
            "seconds": sec, "dur_src": src,
            "long": None if sec is None else sec > SHORT_MAX_S,
        })
    early.sort(key=lambda b: (b["day"], b["id"]))
    got = [b for b in early if b["hi"] is not None]
    zero = [b for b in early if b["hi"] is None and b["through_gate"]]
    early_zero = [b for b in early if b["hi"] is None and not b["through_gate"]]
    spans = [b["hi"] - b["lo"] for b in got if b["lo"] is not None]
    return {"books": early, "got": got, "zero": zero, "late": late,
            # **まだ門の手前で 0回 の本**（きょう出た本がここに居ます）——
            # **`zero` にも `zero_short` にも入れません**（下の註）。
            "zero_early": early_zero,
            # **0回 の列は尺で割って返す**（混ぜたまま数えると「配りが止まった」に見える・`durations` の註）。
            "zero_short": [b for b in zero if b["long"] is False],
            "zero_long": [b for b in zero if b["long"] is True],
            "zero_unknown": [b for b in zero if b["long"] is None],
            "gate_h": FIRST_VIEW_EARLY_H,
            "latest_first": max([b["hi"] for b in got], default=None),
            "span_median": (sorted(spans)[len(spans) // 2] if spans else None)}


def _dur_mark(b: dict) -> str:
    """0回 の本に添える尺の印（`first_view_lines`・**1本 1行 のまま**）。

    **尺が分からない本には「不明」と書きます**（`durations` の註 ＝ 「短い」と決めつけない）。
    """
    if b["seconds"] is None:
        return "（**尺 不明** ＝ 短いとは決めつけない）"
    mark = f'（尺 {b["seconds"]:.0f}秒'
    if b["long"]:
        mark += f' ＝ **{SHORT_MAX_S:g}秒 超・下敷きの外**（Shorts フィードに乗らない ＝ §1「長尺は 1〜25回」）'
    mark += f'・{b["dur_src"]}）'
    return mark


def first_view_lines(rows: list[dict]) -> list[str]:
    """`first_view` を印字する（**次の回は覚えていなくてよい**・`first_view` の註）。"""
    f = first_view(rows)
    if not f["books"]:
        return []
    out = [f'**1回目の再生が付いた齢**（台帳の**初点が齢 {f["gate_h"]:.0f}h 以内**の本だけ・'
           f'挟みで読む ＝ 測りは 42分 間隔・`trend.first_view` の註）:']
    for b in f["books"]:
        mark = "新" if b["new"] else "旧"
        if b["hi"] is None and not b["through_gate"]:
            got = (f'**0回 のまま {b["zero_through_h"]:.1f}h**'
                   f'（**まだ門の手前** ＝ 門 {f["gate_h"]:.0f}h。'
                   f'**「配りが来なかった」に数えないこと**）{_dur_mark(b)}')
        elif b["hi"] is None:
            got = f'**0回 のまま {b["zero_through_h"]:.1f}h**{_dur_mark(b)}'
        elif b["lo"] is None:
            got = (f'初点 {b["first_age_h"]:.1f}h で既に {b["first_views"]}回'
                   f'（**1回目はそれより前** ＝ 下端が無い）')
        else:
            got = f'1回目は **{b["lo"]:.1f}h〜{b["hi"]:.1f}h** のあいだ'
        out.append(f'  {b["day"]} {mark} {b["id"]:14} {got}   いま {b["views"]}回')
    tail = ""
    if f["latest_first"] is not None:
        tail = (f'**1回目が付いた {len(f["got"])}本 は、どれも 齢 {f["latest_first"]:.1f}h までに'
                f'付いていました**（挟みの上端）。')
    split = (f'（**Shorts の尺 {len(f["zero_short"])}本**・'
             f'**下敷きの外（{SHORT_MAX_S:g}秒 超）{len(f["zero_long"])}本**・'
             f'尺の分からない {len(f["zero_unknown"])}本）') if f["zero"] else ""
    warn = ('**この列を尺を混ぜたまま数えないこと** —— 長尺の 0回 は §1 の「長尺は 1〜25回」で'
            '説明が付きます（`trend.durations` の註・`scripts/zero_start` が 09/11 08:0x に'
            '同じ混ざりを直した側）。') if f["zero_long"] else ""
    early_note = ''
    if f["zero_early"]:
        upper = (f'1回目が付いた本は どれも 齢 {f["latest_first"]:.1f}h までに付いており'
                 f'（門 {f["gate_h"]:.0f}h）、' if f["latest_first"] is not None else '')
        early_note = (f'**まだ門の手前で 0回 の本 {len(f["zero_early"])}本**'
                      f'（{"・".join(b["id"] for b in f["zero_early"])}）は、'
                      f'**この数にも `zero_short` にも入れていません** —— {upper}'
                      f'**門の手前の 0回 は「来なかった」ではありません**'
                      f'（§7「形」の 決め (5-2) の分子はこの `zero_short` ＝ '
                      f'`first_view` の註 2026-09-12 11:1x）。')
    out.append(
        f'{tail}**0回 のまま門を越えたのは {len(f["zero"])}本**{split}。{early_note}{warn}'
        f'**この行は当たり外れを言いません** —— 判定は `hourly`（§5）。'
        f'n が小さいので**点で読まないこと**（覆る条件は `trend.first_view` の註）。'
        f'初点が {f["gate_h"]:.0f}h より遅い本 {f["late"]}本 は、この問いに答えられないので外してあります。')
    return out


def _growth(pts: list[dict], vals: list[int] | None = None) -> str:
    """直近の2点の伸び。平らな区間の中で「止まった」と読まないための目印。"""
    if len(pts) < 2:
        return ""
    vals = vals or [int(p["views"]) for p in pts]
    a, b = pts[-2], pts[-1]
    dh = float(b["age_h"]) - float(a["age_h"])
    dv = vals[-1] - vals[-2]
    if dh <= 0:
        return ""
    return f"   [直近 {dv:+d}回 / {dh:.1f}h]"


#: **再生が1度も増えていない時間帯**（2026-09-08 04:4x JST・optimizer・Opus に台帳から数えた）。
#:
#: §7 は 10:2x・14:2x・16:3x・00:5x と、平らな点から「止まった／絞られている」を繰り返し引いてきた。
#: `_growth()` は「直近の2点」を出すだけなので、**その2点がどの時間帯に落ちたか**は見えていない。
#: 台帳の `measured` の連続する2点 549組 を刻で分けた実測:
#:
#:     02:00〜10:00 JST に落ちた2点目   伸びた **0組** ／ 平ら 178組（**178/178**）
#:     それ以外                          伸びた 15組 ／ 平ら 356組
#:
#: **＝ この帯で測った回は、何を見ても平らです。** 04:4x のこの回も 15本 全部 +0 だった。
#:
#: **交絡を先に書く（これを書かずに引くのが §7 の踏んだ形そのもの）**: このチャンネルは
#: **10:00 JST に公開する**ので、「2点目が 02〜10時」は「その本の齢が 16〜19h か 40〜43h か 64〜67h」と
#: **完全に重なっています**。齢 10h 未満の本がこの帯で測られたことは1度も無い ＝
#: **刻のせいなのか齢のせいなのかは、この台帳からは分けられません。**
#: 分けるには公開の刻を変えた本が要る（§7 の「時刻 10:00」の行）。
#:
#: > **【2026-09-09 00:2x・optimizer・Opus】この「分けられません」は、半分だけ本当でした。**
#: > **新しい作りは 10:00 JST 固定ですが、旧作りは 06:59〜18:59 のいろいろな刻に公開されています。**
#: > 実測: 帯に落ちる2点組は **42本 ぶん・齢は 9h〜191h に散っている**（`band_vs_age`）。
#: > ＝ **齢を揃えたうえで帯と外を比べられます。** 齢の束ごとに「帯の外の伸び率 × 帯の組数」を足すと、
#: > **齢だけで説明できるなら帯の中に 7.33組 の伸びが在るはず**で、実際は **0組**。
#: > 伸びの札を本の中で並べ替える検定（相関を殺さない形）で **p = 0.012**、
#: > 本ごと×齢の束ごとの、いちばん厳しい並べ替えでも **p = 0.031**。
#: > ＝ **帯の 0 は、齢だけでは説明できません。刻の側に何かが残ります。**
#: > **ただし「視聴者が寝ている」と「YouTube の数え直しが夜は回らない」は、まだ分けられません**
#: > （どちらも同じ形に出る）。**手は変わりません** —— この帯の回は伸びを読まないこと。
#:
#: > **【2026-09-09 02:5x・optimizer・Opus】その覆る条件が引かれ、00:2x の p も一緒に覆りました。**
#: > **この回の `measure`（02:59 JST ＝ 帯の中）で、帯は初めて破れました** ——
#: > `lQHX9LJ80Sg` **372 → 389（+17・齢 17.0h）**と `1huadpEk6HY` **3 → 4（+1・齢 114h）**で **2/228**。
#: > 同じ台帳で `band_vs_age` を撃ち直すと **p_video 0.011 → 0.0655・p_va 0.034 → 0.261** ＝
#: > **00:2x の覆る条件 (1)「p_va が 0.05 を越えたら、帯の 0 は齢で説明できる範囲に戻る」も、同じ回に引かれています。**
#: > **上の p = 0.012／0.031 は 00:2x の写しです。引かないこと**（`band_vs_age` を撃って読む）。
#: >
#: > **なぜ 2件 で p が 8倍 動いたか —— 分母が試行の数ではなかったからです**（`informative` の註）。
#: > 帯の **228組 のうち 221組（97%）は、その本が同じ齢で帯の外でも平ら**な組 ＝ **検出する物が無い**。
#: > さらに `measured` は1回の `measure` で全部の本を書くので、228組 は **9回の測り**から出ています。
#: > ＝ 「0/203」は「0 が 203回」ではなく、**「伸びている本が帯に居た回が、8回とも無かった」**。
#: > **9回目に初めて伸びている本が帯へ入り（`lQHX9LJ80Sg`・直前まで +30回/時）、その回に破れました。**
#: > 揃えて数えると 帯 **1/7** 対 外 **16/61**（Fisher 片側 **p = 0.40**。生の 2/228 対 22/566 なら 0.015）。
#: > **＝ 生の分母で出ていた差は、97% が「何も測っていない組」から来ていました。**
#:
#: **それでも手は決まります**: **この帯の回は伸びを読めない** ——
#: 帯が本物だからではなく、**帯に伸びる本が入る回がめったに無く、n が 7組 しか無いから**です。
#: だから数を並べるだけにして、「止まった」と書かないこと（**「帯は無い」とも書かないこと**。n=7 では、在っても見えません）。
#: **覆る条件**: (1) 帯の「検出できた組」（`informative`）が **20組** を越えても帯の伸び率が外の半分以下なら、
#: そのときは n が足りたので帯は本物として扱ってよい（いま 7組）。
#: (2) 公開の刻を変えた本が出たら、交絡が解けるので分けて数え直すこと。
#: **数は写しを持ちません** —— 上の 2/228・1/7・9回 は、この回に撃って出た数です。**引く前に撃つこと。**
DEAD_START, DEAD_END = 2, 10

#: **長さの違う2点組を、同じ分母に入れないための閾**
#: （2026-09-09 00:2x JST・optimizer・Opus が数えて足した）。
#:
#: 同じ回に `measure` を2回 撃つと、数分しか離れていない2点組が台帳に入ります。実測:
#: 台帳の 818組 のうち **74組 が 10分 未満**（23:03/23:08/23:10 のように、道具を直した回が
#: 確かめのために撃ち直したぶん）。**74組 は全部 帯の外**に落ちており、`dead_window` の
#: 「それ以外」の分母だけを 541 → 615 に膨らませていました（伸びの率 4.1% → 3.7%）
#: ＝ 帯との差を**小さく見せる**向き。帯の側（203組）は中央値 151分・最小 119.6分 で 1組も混ざっていません。
#:
#: **足すときに「構造的に平ら（数え直しは分では動かない）」と書きかけて、撃ったら外れました。**
#: 74組 のうち **2組 は動いています**:
#:
#:     EkNqtkK49Bw  09/07 16:30 **122** → 16:35 **129**   5.2分 で **+7**
#:     nQbVxuWpWw8  09/08 23:08  **68** → 23:10  **66**   1.6分 で **-2**
#:
#: ＝ **YouTube の数え直しは分の粒度でも動きます。** 落とす理由は「情報が無いから」ではなく、
#: **`dead_window` が「組あたりの率」を数えているから**です —— 2分の組と 2時間の組を同じ分母に
#: 入れると、短い組は「伸びなかった」側にばかり積まれます（短い組の伸びは 1/74 ＝ 1.4%、
#: 10分 以上の組は 22/541 ＝ 4.1%。**時間が短いぶんだけ低い**、それだけのこと）。
#: **23:0x の回が「数え直しの揺れ」と呼んだ -2 は、この 1.6分 の組です**（本が減ったのではない）。
#:
#: **覆る条件**: (1) `dead_window` を「組あたり」から「組×時間あたり」に変えたら、
#: 長さを揃える必要が無くなるので、この閾ごと要らなくなる（`band_vs_age` の `per_hour` が既にその形）。
#: (2) 数え直しの間隔が 10分 より短い回り方に変えたら、閾はその間隔まで下げること。
MIN_PAIR_MIN = 10.0

#: 齢の帯（`band_vs_age` が「同じ齢どうし」で突き合わせるときの束）。
AGE_BUCKETS = ((0, 12), (12, 24), (24, 36), (36, 48), (48, 72), (72, 10_000))

#: 2点組の**長さ**の束（`_matched` が齢の次にそろえる物。単位は分）。
#: **なぜ要るか**: 短い組は「伸びた」と出にくく、**短い組は帯の側にしか無い**
#: （2026-09-10 03:4x 実測: 帯の最短 **10.7分**／外の最短 **41.0分**・10〜30分 の組は **6組 とも帯**で **0/6**）。
#: ＝ そろえないと、帯の率だけが下へ引かれます（**門 0.5 へ向かう向き** ＝ 帯を「在る」と言わせる側）。
GAP_BUCKETS = ((0, 30), (30, 60), (60, 120), (120, 1_000_000))

#: 齢だけの比と 齢＋長さ の比が これだけ割れたら、**門 (2) は齢＋長さ の側で読む**
#: （`_matched` の覆る条件 (0)。2026-09-10 09:0x に **0.103倍 で初めて越えました**）。
GAP_SPLIT = 0.1


def _pairs(rows: list[dict]) -> list[dict]:
    """`measured` の連続する2点を、判定に要る形だけにして並べる。

    **`MIN_PAIR_MIN` より短い組は落とします**（上の註）。
    """
    out: list[dict] = []
    for vid, pts in series(rows).items():
        for a, b in zip(pts, pts[1:]):
            va, vb = a.get("views"), b.get("views")
            if va is None or vb is None:
                continue
            ta, tb = _at(a), _at(b)
            if (tb - ta).total_seconds() / 60.0 < MIN_PAIR_MIN:
                continue
            age = b.get("age_h")
            bucket = next(((lo, hi) for lo, hi in AGE_BUCKETS
                           if age is not None and lo <= age < hi), None)
            out.append({"vid": vid, "age": age, "bucket": bucket,
                        "gap_min": (tb - ta).total_seconds() / 60.0,
                        "band": DEAD_START <= tb.hour < DEAD_END,
                        "delta": int(vb) - int(va),
                        "a": int(va), "b": int(vb), "at": tb,
                        "grew": int(vb) - int(va) > 0})
    return out


def dead_window(rows: list[dict]) -> tuple[int, int, int, int]:
    """`measured` の連続する2点を、2点目の刻で「02〜10時 JST」と「それ以外」に分け、
    それぞれ（伸びた組, 全体の組）を数える。**写しを持たず、毎回 台帳から数える。**"""
    nm = nt = om = ot = 0
    for p in _pairs(rows):
        if p["band"]:
            nt += 1
            nm += p["grew"]
        else:
            ot += 1
            om += p["grew"]
    return nm, nt, om, ot


def drops(rows: list[dict]) -> tuple[int, int, int, str]:
    """再生が**減った**2点組を数える（組数, 減った組, いちばん大きい減り, その組の説明）。

    **`dead_window` とまったく同じ `_pairs` から数えます。ここが要点です** ——
    §7 は 17:0x（2026-09-08）から毎周この数を手で数え直しており、
    **同じ段落の中で分母が2つ**になっていました:

        帯の率      `dead_window` ＝ **`MIN_PAIR_MIN` で短い組を落としたあと**の組
        減りの数    手で書いた script ＝ **落とす前**の組（00:2x の「818組」）

    実測 2026-09-09 01:5x: 落とす前 **854組・減り 7組**／落としたあと **769組・減り 6組**。
    差の1組は `nQbVxuWpWw8` の **1.6分** の組（68 → 66）で、
    **00:2x の回が「これは数え直しの揺れで、本が減ったのではない」と名指しした当のもの**です。
    ＝ 落とす理由を書いた回自身が、**減りのほうは落とさずに数えていました。**
    手で数えるかぎり、次の回もどちらの分母を使ったか分かりません。→ 道具の側に置く。

    **何に使うか**: §7 17:0x は「床（旧作りの中央値）を越えたか」を、
    **「ここから床まで落ちるには、この台帳に1度も無い大きさの減りが要る」**という形で読んでいます。
    その「1度も無い大きさ」がこの関数の3つ目の返り値で、**覆る条件はそこに掛かっています**
    （減りが -5回 を越えた組が出たら、余裕の倍率を数え直すこと）。

    **覆る条件**: `MIN_PAIR_MIN` を変えたら、ここの数も一緒に動きます（同じ `_pairs` なので自動）。
    減りが「数え直しの揺れ」ではなく本当の取り下げ（本が消える・非公開に戻る）で出るようになったら、
    その組は別に数えること —— いまは `unscheduled` の本が measured から落ちるだけなので、組にならない。
    """
    ps = _pairs(rows)
    dec = [p for p in ps if p["delta"] < 0]
    if not dec:
        return len(ps), 0, 0, ""
    worst = min(dec, key=lambda p: p["delta"])
    where = (f"{worst['vid']} {worst['at']:%m/%d %H:%M} {worst['a']}→{worst['b']}")
    return len(ps), len(dec), worst["delta"], where


#: **「伸びを検出できた組」だけを数えるときの、齢の窓**
#: （2026-09-09 02:5x JST・optimizer・Opus が足した。下の `informative` の註）。
INFORMATIVE_AGE_H = 6.0


def informative(rows: list[dict], window_h: float = INFORMATIVE_AGE_H) -> dict:
    """**帯の分母のうち、「伸びを検出できた組」がいくつか**を数える
    （2026-09-09 02:5x JST・optimizer・Opus が足した）。

    **なぜ要るか —— §7 は 7周、この分母を「独立な試行の数」として読んできました。**
    04:4x が「帯 0/178」と書いてから、16:0x 0/203・19:1x 0/203・20:4x 0/203・
    21:4x 0/203・23:0x 0/203・00:2x 0/203 と、**毎周この 203 を分母に置いています。**
    00:2x はそこへ並べ替え検定まで足し、`p_va = 0.034` を出しました。

    **203 は、試行の数ではありませんでした。** 実測（2026-09-09 02:5x・API 0単位）:

        帯に落ちる 228組 のうち、**同じ本が 齢±6h の帯の外でも伸びていた**組   **7組**
        残り                                                                   **221組**
          ＝ その本はその齢で**どこで測っても平ら**（帯の外でも +0）
            ＝ **帯が伸びを止めたのかどうかを、この組は何も言っていません**

    **221/228（97%）は、検出する物が無い組です。** さらに `measured` は1回の `measure` で
    **全部の本を一度に**書くので、228組 は**9回の測り**から出ています（1回 25組）。
    ＝ 「0/203」は「0 が 203回」ではなく、**実質「伸びる本がその帯に居た回が、8回とも無かった」**。

    **9回目（2026-09-09 02:59 JST）に、初めて伸びている本が帯に入りました** ——
    `lQHX9LJ80Sg`（17.0h・直前まで +30回/時 で伸びていた）が **372 → 389（+17）**。
    **その回に帯は破れました**（`dead_window` が 2/228 を印字）。
    ＝ **帯が破れるのに要ったのは 203組 ではなく、「伸びている本が1本 入ること」でした。**

    出すもの: `band`/`out` は (伸びた, 伸びを検出できた組) の対、`band_all`/`out_all` は元の分母。

    **数え方**: ある組が「検出できた」＝ **同じ本の、齢が ±`window_h` の別の組が、1つでも伸びている**。
    帯と外で**同じ定義**を使い（自分自身は数えない）、片側だけ甘い分母にならないようにしてあります。
    窓を動かしても向きは変わりません（実測 ±4h: 帯 1/2・外 11/41／±6h: 1/7・16/61／±8h: 1/15・16/70）。

    **これで何が言えるか**: 帯 **1/7 (14%)** 対 外 **16/61 (26%)** ——
    Fisher の片側 **p = 0.40**（生の 2/228 対 22/566 なら p = 0.015）。
    ＝ **生の分母で出ていた差は、97% が「何も測っていない組」から来ていました。**
    `band_vs_age` の `p_va` が 0.034 → 0.261 に動いたのと**同じことを、別の道で**言っています
    （あちらは齢の束で揃え、こちらは「伸びる余地が在ったか」で揃える）。

    **これは「帯は無い」の証明ではありません。** n=7 では、在っても見えません。
    言えるのは **「まだ測れていない」**ことだけで、`dead_window` の印字はそう読むこと。

    **覆る条件**: (1) 帯の「検出できた組」が **20組** を越えても帯の伸び率が外の半分以下なら、
    そのときは n が足りたので、帯は本物として扱ってよい（いまは 7組）。
    (2) 公開の刻を変えた本が出たら、帯と齢の交絡そのものが解ける（`band_vs_age` の覆る条件 (2) と同じ）。
    (3) `MIN_PAIR_MIN` を変えたら、ここの分母も一緒に動く（同じ `_pairs` なので自動）。
    """
    pairs = [p for p in _pairs(rows) if p["age"] is not None]
    by_vid: dict[str, list[dict]] = {}
    for p in pairs:
        by_vid.setdefault(p["vid"], []).append(p)
    # 同じ本・齢が近い「別の」組が伸びていれば、この組は伸びを検出できた
    inf = [p for p in pairs
           if any(q["grew"] for q in by_vid[p["vid"]]
                  if q is not p and abs(q["age"] - p["age"]) <= window_h)]
    out: dict[str, object] = {"window_h": window_h}
    for key, want_band in (("band", True), ("out", False)):
        side = [p for p in inf if p["band"] is want_band]
        out[key] = (sum(p["grew"] for p in side), len(side))
    out["band_all"] = sum(1 for p in pairs if p["band"])
    out["out_all"] = sum(1 for p in pairs if not p["band"])
    out["occasions"] = len({p["at"] for p in pairs if p["band"]})
    out.update(_matched(inf))
    return out


def _matched(inf: list[dict]) -> dict:
    """**齢の束を、帯と外でそろえてから数え直す**
    （2026-09-10 03:0x JST・optimizer・Opus が足した。**この回に、門がこれで割れた**）。

    上の `informative` は分母を「伸びを検出できた組」に絞りましたが、
    **齢はそろえていません**。そして **本の公開は全部 10:00 JST に固定**なので、
    帯（02:00〜10:00）に落ちる齢は **16〜24h・40〜48h・64〜72h…** だけです ——
    **齢 0〜12h・24〜36h・48〜72h の組は、帯には構造的に 1つも入りません。**
    そこは伸びのいちばん濃い所（実測 2026-09-10 03:0x: 齢 0〜12h の外は **19/27 が伸びた**）なので、
    **「帯 4/24 対 外 37/108」の外の側の分子 37 のうち 29 は、帯が持ちえない齢から来ています。**

    実測（2026-09-10 03:0x・API 0単位・台帳から）:

        生のまま        帯 **4/24 (16.7%)** 対 外 **37/108 (34.3%)** ＝ **0.486倍** → **門 0.5 を通る**
        齢の束をそろえる 帯 **4/24 (16.7%)** 対 外 **8/54 (14.8%)** ＝ **1.125倍** → **門を通らない**
        両側がいちばん厚い束（齢 12〜24h）  帯 **4/11** 対 外 **4/11** ＝ **同じ**

    ＝ **門 (2) は、この回に「引かれた」ように見えますが、引いたのは帯ではなく齢の交絡です。**
    §7 の 02:2x が見つけた穴（分子が止まったまま分母だけ増える）と**同じ族の 2つ目**で、
    あちらは「測った回数」、こちらは「測った齢」がひとりでに門を通します。

    **数え方**: `AGE_BUCKETS` のうち **帯と外の両方に組が在る束**だけを残し、両側をその束に絞る。
    帯に 1組 も無い束（＝比べる相手が居ない）は `unmatched` に名前で出す。

    **長さ（`gap_min`）もそろえた —— 足した回は動きませんでしたが、いまは動いています**
    （2026-09-10 03:4x に足し、**07:2x に見出しを直した**・optimizer・Opus）。
    **差は 4周 で 0.010 → 0.050 → 0.069 → 0.086倍 と、毎周 開いています**（覆る条件 (0) の門は 0.1倍）。
    **開く向きには理由が在り、止まりません** —— 10〜30分 の短い組は**帯の側にしか無く**（下の実測）、
    その出どころは**床**です（`quota.pace()` の床 41.6分・親の穴埋めの周は もっと短い）。
    **床に乗って回るほど帯の組は短くなり、`0/6` の短い組が帯の分母だけを膨らませる** ＝
    そろえたときの補正が毎周 大きくなります。**「動かない」と読んで放置しないこと。**
    いまの数は `trend` の印字と §7 の「いまの数」(2) を見ること（**ここに写さない**）。
    以下は**足した回の derivation**（03:4x の数）:

    齢の次に疑うのは組の長さです（長い組ほど「伸びた」と出るはず・**外の側が 1.44倍 長い**:
    帯 中央 66.9分／平均 70.4 対 外 中央 78.9分／平均 101.2・最長 151 対 495分）。
    ところが撃つと **齢だけ 1.558倍 → 齢＋長さ 1.568倍**（帯 6/22 対 外 8/46）＝ **+0.6%**:

        長さの束ごとの伸び率（帯と外を混ぜて・検出できた組だけ）
          10〜30分   **0/6**     30〜60分  21/48 (43.8%)
          60〜120分  13/44 (29.5%)   120分〜  9/36 (25.0%)

    ＝ **30分 を越えると、長いほうが伸び率は低い**（＝ 長さは「伸びた」を予言しない。
    長い組は測りが疎な時期＝伸びる本が居なかった時期から来ています）。
    ~~**§5 の「必ず一致する2つ目の意見に、確かめる力は無い」に当たるので、判定は齢の側のままにします。**~~
    **【2026-09-10 09:0x に、この行は取り消しました（optimizer・Opus）】** 差は
    0.010 → 0.050 → 0.069 → 0.086 → 0.094 → 0.099 → **0.103倍** と **7周 続けて開き、門 0.1 を越えました**。
    ＝ **2つの意見は一致していません**（03:4x に「必ず一致する」と読んだのは、**差が小さかった1周ぶん**の話でした）。
    **これからの門 (2) は `gate_side`（＝ 齢＋長さ）の側で読むこと。** どちらで読むかは
    **道具が毎周 印字し、`informative()` の `gate_side`/`gate_ratio`/`gate_n` に残します**
    ——読み替えを人の記憶に置くと、次の回が古い側を読みます（この repo が §5 で 2度 踏んだ形）。
    それでも `GAP_BUCKETS` を残して毎周 印字するのは、**偏りが片側にしか無いから**です ——
    10〜30分 の組は **6組 とも帯**（帯の最短 10.7分 対 外の最短 41.0分。出どころは親の穴埋めの周・§5）で、
    **0/6 が帯の分母だけを膨らませ、率を下げます**（実測: 帯 6/26 23.1% → 長さもそろえると 6/22 **27.3%** ＝ **+4.2 ポイント**）。
    **その向きは門 0.5 へ向かう向き ＝ 帯を「在る」と言わせる側**なので、放っておけません。

    **覆る条件**: ~~(0) 齢だけの比と 齢＋長さ の比が 0.1倍 以上 割れた回が出たら、門は齢＋長さ の側で読むこと~~
    **＝ 2026-09-10 09:0x に引かれました（0.103倍）。門は `gate_side` の側で読みます。**
    **(0-新) 差が `GAP_SPLIT` を下回ったまま 3周 続いたら、長さはもう効いていない ＝ 読む側は齢だけへ戻ります**
    （`gate_side` が勝手に戻るので、そのときは §7 (2) の見出しを直すだけ。**戻りは「直った」ではなく
    「帯の短い組が減った」印**なので、床（`quota.pace()`）が伸びていないかを一緒に見ること ——
    開いた向きの理由が床だったので、閉じる向きの理由も床のはずです）。
    (1) 公開の刻を変えた本が出たら、帯が持てる齢が増えるので数え直すこと
    （`band_vs_age` の覆る条件 (2) と同じ刻 —— そのとき `unmatched` が短くなって教える）。
    (2) そろえた側でも 20組 を越えて 0.5倍 を切ったら、**そのときは齢では説明が付かない**
    ＝ 門 (2) は本当に引かれた（判定は `hourly`・§5）。
    (3) `AGE_BUCKETS` を細かくしたら、そろう束が減って n が落ちる ——
    束を変えるなら、変える前と後の両方を1度 並べてから決めること。
    """
    buckets = [b for b in AGE_BUCKETS
               if any(p["band"] and p["bucket"] == b for p in inf)
               and any(not p["band"] and p["bucket"] == b for p in inf)]
    res: dict[str, object] = {"matched_buckets": buckets}
    for key, want_band in (("band_matched", True), ("out_matched", False)):
        side = [p for p in inf if p["band"] is want_band and p["bucket"] in buckets]
        res[key] = (sum(p["grew"] for p in side), len(side))
    res["unmatched"] = [b for b in AGE_BUCKETS
                        if b not in buckets
                        and any(not p["band"] and p["bucket"] == b for p in inf)]

    # **齢の次に、組の長さもそろえる**（2026-09-10 03:4x・`GAP_BUCKETS` の註）。
    def _gb(p: dict) -> tuple[int, int] | None:
        return next((b for b in GAP_BUCKETS if b[0] <= p["gap_min"] < b[1]), None)

    keys = [(a, g) for a in buckets for g in GAP_BUCKETS
            if any(p["band"] and p["bucket"] == a and _gb(p) == g for p in inf)
            and any(not p["band"] and p["bucket"] == a and _gb(p) == g for p in inf)]
    for key, want_band in (("band_gapmatched", True), ("out_gapmatched", False)):
        side = [p for p in inf
                if p["band"] is want_band and (p["bucket"], _gb(p)) in keys]
        res[key] = (sum(p["grew"] for p in side), len(side))
    for key, want_band in (("band_gap_med", True), ("out_gap_med", False)):
        gaps = sorted(p["gap_min"] for p in inf
                      if p["band"] is want_band and p["bucket"] in buckets)
        res[key] = statistics.median(gaps) if gaps else None

    # **どちら側で門 (2) を読むかを、返り値に残す**（2026-09-10 09:0x・覆る条件 (0) が引かれた回）。
    # 読み替えを人の記憶に置くと、次の回が古い側を読みます。
    def _rt(a: tuple[int, int], b: tuple[int, int]) -> float | None:
        return (a[0] / a[1]) / (b[0] / b[1]) if a[1] and b[1] and b[0] else None

    r_age = _rt(res["band_matched"], res["out_matched"])          # type: ignore[arg-type]
    r_gap = _rt(res["band_gapmatched"], res["out_gapmatched"])    # type: ignore[arg-type]
    res["ratio_age"] = r_age
    res["ratio_agegap"] = r_gap
    if r_age is None or r_gap is None:
        res["gate_side"], res["gate_ratio"], res["gate_n"] = "齢だけ", r_age, res["band_matched"][1]  # type: ignore[index]
    elif abs(r_gap - r_age) >= GAP_SPLIT:
        res["gate_side"], res["gate_ratio"], res["gate_n"] = "齢＋長さ", r_gap, res["band_gapmatched"][1]  # type: ignore[index]
    else:
        res["gate_side"], res["gate_ratio"], res["gate_n"] = "齢だけ", r_age, res["band_matched"][1]  # type: ignore[index]
    return res


#: `gate_span` が門 (2) の比の振れ幅を見るときに遡る時間。
GATE_SPAN_H = 24.0

#: **側**（齢だけ／齢＋長さ）の差を数えるとき、**両側の帯の分母に要る組の数**（2026-09-10 12:3x）。
#: `informative` の註が「**20組 を越えるまでは まだ測れていない**」と書いているのと同じ数を、
#: 側の側にも当てる —— **届かない点の差は「長さが効いた」ではなく「そろえた側の組が少ない」だけ**です。
#: 実測（この回・24時間 の点を列挙した）: 12:29〜21:50 は 帯 18 対 **11〜13組** で 差 **0.94〜1.44**、
#: 23:56 に **18 対 18** へそろった瞬間 差は **0.03** へ落ちました。
#: ＝ **この門を入れないと、`side_hi` は「そろっていなかった時間帯」を読み続けます。**
SIDE_MIN_PAIRS = 20

def _span_points(rows: list[dict], hours: float) -> list[dict]:
    """`measured` の刻ごとに **門の比・その刻の側・両側の差** を出す
    （2026-09-12 03:1x に切り出した口。**いま呼ぶのは `gate_span` だけ** ——
    04:0x に `side_verdict` を畳んだ・derivation は JOURNAL 09/12 04:0x）。

    **`hours` は「どの刻から評価を始めるか」だけを決めます。** `informative` に渡すのは
    その刻までの**台帳まるごと**（`seen` は窓の外からも積む）なので、
    **同じ刻の値は `hours` を広げても変わりません** ＝ 広げて呼べば
    **過去の刻の 24時間 窓**を丸ごと持てます（畳んだ `side_verdict` はそれで走っていました）。
    """
    occ = sorted({r["at"] for r in rows if r.get("event") == "measured"})
    if not occ:
        return []
    cut = _at({"at": occ[-1]}) - dt.timedelta(hours=hours)
    other = [r for r in rows if r.get("event") != "measured"]
    by_at: dict[str, list[dict]] = {}
    for r in rows:
        if r.get("event") == "measured":
            by_at.setdefault(r["at"], []).append(r)
    seen: list[dict] = []
    out: list[dict] = []
    for at in occ:
        seen.extend(by_at[at])
        if _at({"at": at}) < cut:
            continue
        inf = informative(other + seen)
        # **どちらの側で読むか**も、比とまったく同じ理由で刻に揺れます（`gate_span` の註）。
        # **ただし両側の分母が 20組 に届くまでは数えない** —— 届かない点の差は
        # 「長さが効いた」ではなく「そろえた側の組が少ない」だけで、上限を独り占めします。
        ra, rg = inf.get("ratio_age"), inf.get("ratio_agegap")
        n_age, n_gap = inf["band_matched"][1], inf["band_gapmatched"][1]  # type: ignore[index]
        diff = (abs(float(rg) - float(ra))
                if ra is not None and rg is not None and min(n_age, n_gap) >= SIDE_MIN_PAIRS
                else None)
        r = inf.get("gate_ratio")
        out.append({"at": at, "diff": diff,
                    "side": None if r is None else str(inf.get("gate_side")),
                    "ratio": None if r is None else float(r)})
    return out


def gate_span(rows: list[dict], hours: float = GATE_SPAN_H) -> dict:
    """**門 (2) の比は、本ではなく「いつ測ったか」で上下する。その振れ幅を出す**
    （2026-09-10 09:4x JST・optimizer・Opus が足した）。

    **なぜ要るか —— 比は毎周 動きますが、その動きの大半は本の側の事実ではありません。**
    `_pairs` は 2点目の刻で組を帯（02:00〜10:00 JST）と外に分けるので、
    **いま撃った `measure` は、いる側の分母だけを増やします。** そして本が落ち着いていれば
    その組は伸びないので、**測っている側の率だけが下がります**
    ＝ **比は、いま自分が居る側から逃げる向きに動きます**（帯の中の回は 0.5 へ、外の回は上へ）。

    実測（2026-09-10 09:4x・台帳を測りの刻で切って読み直した・API 0単位）:

        09/09 18:14〜21:50  **外**の 4周   外 3/33 → 3/37（**分子は 3 のまま**）  比 1.692 → **1.897**（上へ）
        09/10 02:06〜09:39  **帯**の 12周  帯 4/20 → **11/48**                     比 1.150 → 2.063 → **1.318**
          うち 06:53〜09:39 の 4周           帯 **11**/32 → **11**/48（**分子は 11 のまま**）  比 2.063 → **1.318**（下へ）

    ＝ **直近 4周 で比が 0.745 落ちたぶんは、分子が 1つも動かないまま分母が 16組 増えたぶん**です。
    24時間 の振れ幅は **1.067 〜 2.063**（門 0.5 の 2〜4倍 の幅）で、
    **1周ぶんの点をそのまま読むのは、鋸の歯のどこに刺さったかを読むことです。**

    **これは §7 が 2度 名指しした族の 3つ目です**: 02:2x は「測った回数」、
    `_matched` は「測った齢」、ここは **「測った刻」**が、本の側が動かなくても門を通します。
    `_matched` が齢と長さをそろえても消えません —— そろえるのは**組の中**の偏りで、
    **どちらの側に組が足されるか**は測る刻が決めるからです。

    **読み方（門 (2) の引き方）**: 点ではなく、**この振れ幅の上限 `hi` が 0.5 を切った回にだけ引く。**
    上限で読めば、鋸の歯のどの位置で撃っても答えが変わりません
    （下限で読むと、帯の中を続けて撃った回に、本の側が何も変わらないまま引けてしまいます）。

    出すもの: `lo`/`hi`（`hours` のあいだの比の最小・最大）・`now`（いまの比）・
    `n`（読み直した測りの回数）・`points`（(刻, 側, 比) の並び。次の回が列挙で確かめられるように残す）。

    ## **側も、点で読まないこと**（2026-09-10 12:3x JST・optimizer・Opus が足した）

    09:4x（上）は**比**を振れ幅で読む形に直しましたが、**「どちらの側の比を読むか」（`gate_side`）は
    1点のまま**でした。**同じ病気です。** `gate_side` は 齢だけ と 齢＋長さ の**差**が
    `GAP_SPLIT` 以上 かどうかで決まり、その差も測る刻で動きます。

    **実測（この回に踏んだ・API 0単位）**: 12:04 に `measure` を **1回** 足しただけで —— 帯の外から ——

        全部（12:04 を含む）      差 **0.020倍** → 側 **齢だけ**
        12:04 の測りを外すと      差 **0.101倍** → 側 **齢＋長さ**
        11:44 と 12:04 を外すと   差 **0.103倍** → 側 **齢＋長さ**

    ＝ **測り 1回 が差を 0.08 動かし、門 `GAP_SPLIT`（0.1）の側を反転させました**
    （本の側は 1冊も動いていません。5本目 は 0回 のまま・3本目 4本目 は +0回）。
    見張り `tests/test_studio_informative_matched.py::test_本物の台帳では門は齢と長さの側で読む` が
    **その場で赤くなりました** —— 見張りは正しく鳴りましたが、鳴った先が**刻**でした。

    **09:0x が「差 0.103倍 で門を越えた」と書いた 1点も、同じ鋸の歯の上の1点です。**
    ＝ **点で越えた門は、点で戻ります**（`_matched` の覆る条件 (0-新) の「3周 続いたら」は
    **周を数える形**ですが、周を数えても、その 3周 がどの刻に立ったかで答えが変わります）。

    ~~**読み方**: 側は `side_hi`（24時間 の差の上限）で読む。~~
    ## **【2026-09-12 04:0x に (5)(6) が引かれ、畳みました】**（optimizer・Opus・API 0単位）

    **決め: 側は `side_now`（その刻の差）＝ 点で読む。**
    (6) の門（幅が `GAP_SPLIT` の下で測り 3回）に届いた ＝ **24時間 の窓のどの点で撃っても
    側が同じ**なので、上限で読む意味が消えています（実測 04:0x: 上限 **0.0758**・
    下限 **0.0005**・いま **0.0746** ＝ 全部 門 0.1 の下・窓が埋まった点 39件）。

    **畳んだ理由は「一致した」ではありません** —— **上限は、もう居ない 1点 を 24時間 運びます。**
    実測（台帳を測りの刻で切って読み直した・API 0単位）: 門を越えた差の**最後の点は
    09/11 02:13 の 0.1614** で、そこから **42回 の測り（25.6時間）が 1度も門へ届いていません**
    （その 42点 の中央 0.024・最大 0.076）。それでも上限の側は **09/12 03:0x まで `齢＋長さ`** と
    言い続け、**2つ の読み方は 20回 の測りで食い違っていました**（09/11 14:57〜09/12 02:07 ＝
    点は全部 `齢だけ`・上限は 0.161〜0.199）。**03:0x に側が戻ったのは、その 1点 が
    24時間 の窓から出た刻**であって、本の側でも組の側でも在りません。

    **(6) は (5) と独立ではありませんでした** —— 差は絶対値（≧0）なので
    `side_hi < GAP_SPLIT` なら必ず `side_hi - side_lo < GAP_SPLIT` ＝
    **(6) は「(5) が測り 3回 続いた」以上のことを言いません**（実測 `run` 3 ＝ `narrow_run` 3）。
    **覆る条件を 2つ 書くときは、片方がもう片方を含んでいないかを先に見ること。**
    derivation は JOURNAL 09/12 04:0x。

    出すもの: `side_lo`/`side_hi`/`side_now`（差の最小・最大・いま）と `side`（**点で読んだ側**）。

    **覆る条件 (5')**: `side_hi`（24時間 の上限）が `GAP_SPLIT` へ戻ったら、鋸の歯も戻っています
    ＝ **点で読む畳みを開き直し、上限で読む形へ戻すこと**（畳む前の形は git の 09/12 03:1x）。
    **上限は畳んでも数え続けます**（`_side_line` が毎周 印字する ＝ この条件には印字が在る側・
    見張りは `tests/test_studio_informative_matched.py`）。
    **戻りを「直った」と読まないこと** —— 帯の短い組が減っただけの回が在るので、
    床（`quota.pace()`）が伸びていないかを一緒に見ること（`_matched` の (0-新) と同じ向き）。

    **覆る条件**: (1) `hi` が `GATE_RATIO`（0.5）を切ったら、門 (2) は**刻では説明が付かない**
    ＝ そのときは本当に引かれた（判定は `hourly`・§5）。
    ## **【2026-09-13 02:5x に (2) が引かれ、そのまま畳みました】**（`hourly`・Opus・API 0単位）

    **決め: 比は `hi`（24時間 の上限）で読むまま。点で読む形へは移しません。幅は数えません。**
    畳んだ口: `SPAN_NARROW_GATE` / `SPAN_NARROW_NEED` / `span_narrow_run` / `_narrow_line`
    （畳む前の形は git の 09/13 02:0x）。**受け皿は `span_split`**（下）。

    **引かれたことは本当です**（幅 0.168倍 が測り 3回・09/13 00:01／00:55／01:49）。
    **畳んだ理由は「引かれなかった」ではなく、引いた先の「点で読んでよい」が
    答えを 1度も変えないからです**（台帳の全履歴 171刻 を切って読み直した・API 0単位）:

        点（`now`）と上限（`hi`）で門 (2) の答えが割れた刻   **0 / 171**
        そのうち 窓が門 0.5 を跨いでいた刻                **27**（09/09 11:3x〜09/10 01:2x・`lo` 0.0）

    ＝ **窓が門を跨がないかぎり、点と上限は同じ側に居るので、読み方は答えを変えません。**
    跨いだ 27刻 でも `now` は 1.07〜1.90 で、**割れるのは「跨いだ、かつ `now` だけが門の下」の刻だけ**
    ＝ そこは 09/10 09:4x が上限で読むと決めた当の場所（帯の中を続けて撃って点が 0.5 へ寄った形）で、
    **そこでこそ上限が正しい側**です。**＝ (2) は、引かれても引かれなくても、門の答えを動かしません。**

    **幅 0.2倍 は「鋸の歯が消えた」ではなく、台帳が厚くなった印でした**（同じ履歴から）:

        1測りの刻み（中央）  09/10 20:2x **0.077** → 09/11 21:4x 0.030 → 09/12 21:1x 0.025 → 09/13 01:4x **0.011**
        24時間 の分母の伸び   帯 **+228%** → +110% → +32% → **+29%** ／ 外 **+263%** → +136% → +21% → **+14%**
        24時間 の折返し      13回 → 15回 → 14回 → **7回**（**0 になっていません ＝ 鋸の歯は残っています**）

    ＝ **1測りが分母を動かす割合が落ちたので、同じ鋸の歯が小さく見えているだけ**です。
    分母は減らないので、**幅は放っておけばどんな固定の門も下回ります ＝ あの門は時計でした。**
    **型**: **絶対値の門を置くときは、それが「時計」でないか**（分母が積もるだけで下回らないか）
    **を先に見ること。** 比の門（0.5）は分母で割った数なので時計ではありません。

    (2-新) **`now` が `GATE_RATIO` を切ったのに `hi` が上に居る刻が出たら**、そこが
    **点と上限が初めて割れる刻**です（履歴 0/171）。そのときは**上限で読むまま**にして、
    その刻を JOURNAL に書くこと（判定は `hourly`・§5）。**数える口は `span_split`・印字は `_span_line`。**
    (3) 測りの間隔（`quota.pace()` の床）が変われば 1日に帯へ入る回数が変わるので、
    振れ幅も一緒に動きます —— **幅が広がった回は、まず床を見ること**（`_matched` の (0-新) と同じ向き）。
    (4) `hours` を変えたら `lo`/`hi` は当然 動きます。**24時間 なのは、帯が 1日に 1度しか回らないから**で、
    それより短くすると片側しか入らない窓が出ます（＝ 幅が嘘に狭くなる）。
    """
    res: dict[str, object] = {"n": 0, "lo": None, "hi": None, "now": None,
                              "points": [], "hours": hours,
                              "side_lo": None, "side_hi": None, "side_now": None, "side": None}
    got = _span_points(rows, hours)
    if not got:
        return res
    points: list[tuple[str, str, float]] = [
        (str(p["at"]), str(p["side"]), float(p["ratio"]))  # type: ignore[arg-type]
        for p in got if p["ratio"] is not None]
    diffs: list[float] = [float(p["diff"]) for p in got if p["diff"] is not None]
    if diffs:
        # **側は点（`side_now`）で読む**（2026-09-12 04:0x に (6) を引いて畳んだ）。
        # 上限（`side_hi`）は畳んでも数え続ける —— 覆る条件 (5') を読む口です。
        res.update({"side_lo": min(diffs), "side_hi": max(diffs), "side_now": diffs[-1],
                    "side": "齢＋長さ" if diffs[-1] >= GAP_SPLIT else "齢だけ"})
    if not points:
        return res
    vals = [p[2] for p in points]
    res.update({"n": len(points), "lo": min(vals), "hi": max(vals),
                "now": vals[-1], "points": points})
    return res


def _span_line(rows: list[dict]) -> str:
    """`gate_span` を 1文にする（`trend` が毎周 印字する。註は `gate_span`）。"""
    g = gate_span(rows)
    if not g["n"] or g["hi"] is None:
        return ""
    lo, hi = float(g["lo"]), float(g["hi"])  # type: ignore[arg-type]
    band = [p for p in g["points"] if p[0] and _at({"at": p[0]}).hour >= DEAD_START  # type: ignore[union-attr]
            and _at({"at": p[0]}).hour < DEAD_END]
    return (f"**ただし、この比は 1周ぶんの点で読まないこと** —— 直近 {GATE_SPAN_H:.0f}時間 の"
            f"振れ幅は **{lo:.3f}〜{hi:.3f}倍**（測り {g['n']}回・うち帯の中 {len(band)}回）。"
            f"**比は、いま自分が測っている側から逃げる向きに動きます**"
            f"（帯の中の回は {GATE_RATIO} へ・外の回は上へ。分子が動かないまま分母だけが増えるため）。"
            f"**門 (2) を引くのは、この振れ幅の上限 {hi:.3f} が {GATE_RATIO} を切った回だけ**"
            f"（`trend.gate_span` の註・覆る条件 (1)）。"
            + _split_line(g)
            + _side_line(g))


#: **門 (2) の比そのものの門（0.5倍）。唯一の置き場** —— 註も印字もここから引くこと
#: （2026-09-13 02:5x に (2) を畳んだときに定数へ出した。それまでは文字列の中に 0.5 が散っていた）。
GATE_RATIO = 0.5


def span_split(g: dict) -> dict:
    """**点（`now`）と上限（`hi`）で門 (2) の答えが割れる刻か**
    （2026-09-13 02:5x JST・`hourly`・Opus。`span_narrow_run` を畳んだ受け皿）。

    `gate_span` の覆る条件 (2-新) の口です。**畳んだ理由と履歴の数は `gate_span` の註**
    （点と上限で答えが割れた刻 **0/171**・derivation は JOURNAL 09/13 02:5x）。

    **これは「幅」を数えません。** 幅は分母が積もるだけで下がるので（同 註）、
    固定の門に当てると時計になります。**読み方が答えを変えるのは、
    窓が門を跨ぎ、かつ `now` だけが門の下に居る刻だけ**なので、それを直に見ます。

    返すもの: ``differ``（割れているか）・``now``・``hi``・``gate``・``n``（窓の点の数）。

    **覆る条件**: (1) `differ` が立った刻が出たら、**上限で読むまま**にして、その刻を
    JOURNAL に書くこと（判定は `hourly`・§5）。点へ移すなら、そこが移る値打ちの在る唯一の刻です。
    (2) `GATE_RATIO` は門 0.5 の**唯一の置き場**です —— 註の中の 0.5 を動かすときはここを動かすこと。
    """
    now, hi = g.get("now"), g.get("hi")
    res: dict[str, object] = {"differ": False, "now": None, "hi": None,
                              "gate": GATE_RATIO, "n": int(g.get("n") or 0)}
    if now is None or hi is None:
        return res
    now, hi = float(now), float(hi)  # type: ignore[arg-type]
    res.update({"now": now, "hi": hi, "differ": (now < GATE_RATIO) != (hi < GATE_RATIO)})
    return res


def _split_line(g: dict) -> str:
    """`span_split` を1文にする（`trend` が毎周 印字 ＝ 覆る条件 (2-新) の印字の側）。"""
    s = span_split(g)
    if s["now"] is None:
        return ""
    if s["differ"]:
        return (f"  !! **点 {float(s['now']):.3f} と上限 {float(s['hi']):.3f} が門 {GATE_RATIO} の"
                f"両側に割れました ＝ `gate_span` の覆る条件 (2-新) の刻**（履歴では 0回）。"
                f"**読むのは上限のまま**・この刻を JOURNAL に書くこと（判定は `hourly`・§5）。")
    return (f"  **点 {float(s['now']):.3f} と上限 {float(s['hi']):.3f} は門 {GATE_RATIO} の同じ側** ＝ "
            f"**読み方（点／上限）は門の答えを変えません**"
            f"（2026-09-13 02:5x に覆る条件 (2) を引いて畳んだ理由・`trend.span_split`）。")


def _side_line(g: dict) -> str:
    """**側は点で読む**（2026-09-12 04:0x に (5)(6) を畳んだ。註と derivation は `gate_span`）。"""
    if g.get("side_hi") is None:
        return ""
    lo, hi, now = float(g["side_lo"]), float(g["side_hi"]), float(g["side_now"])  # type: ignore[arg-type]
    return (f"**側（齢だけ／齢＋長さ）は点で読みます: {g['side']}** —— 差 いま **{now:.3f}倍**"
            f"（門 {GAP_SPLIT}倍・両側 {SIDE_MIN_PAIRS}組 以上 の点だけ）。"
            f"24時間 の振れ幅は **{lo:.3f}〜{hi:.3f}倍** ＝ "
            + ("**鋸の歯が戻りました ＝ `gate_span` の覆る条件 (5') を引くこと**"
               "（点で読む畳みを開き直し、上限で読む形へ戻す。"
               "**戻りは本の側とは限りません** —— 床を一緒に見ること）。"
               if hi >= GAP_SPLIT else
               f"**どの点で撃っても同じ側**（2026-09-12 04:0x に (5)(6) を畳んだ理由。"
               f"上限が {GAP_SPLIT} へ戻った回が、覆る条件 (5') です）。"))


def band_vs_age(rows: list[dict], iters: int = 2000, seed: int = 20260909) -> dict:
    """**帯の 0 は「刻」なのか「齢」なのかを、台帳の中だけで分けにいく**
    （2026-09-09 00:2x JST・optimizer・Opus が足した）。

    上の註は「公開が 10:00 JST なので、帯は齢 16〜19h／40〜43h と重なっており、
    **刻と齢を分けられません**」と書いていた。**それは半分だけ本当でした** ——
    旧作りは 06:59〜18:59 JST のいろいろな刻に公開されているので、
    **帯に落ちる2点組の齢は 9h〜191h に散っています**（42本・実測）。
    ＝ 齢を揃えたうえで帯と外を比べる余地が、台帳の中に在ります。

    出すもの:

      `expected`  齢の束ごとに「帯の外の伸び率 × 帯の組数」を足したもの
                  ＝ **齢だけで説明できるなら、帯の中でこれだけ伸びているはず**の数
      `observed`  帯の中で実際に伸びた組（いまは 0）
      `p_video`   伸びの札を**本ごとに**並べ替えて、帯に落ちる数が observed 以下になる率
      `p_va`      同じ並べ替えを**本ごと×齢の束ごと**にしたもの（いちばん厳しい）

    **並べ替えを使う理由**: 2点組は本ごとに強く相関する（伸びる本は続けて伸びる）ので、
    ポアソンや χ² は「独立な 818組」と読んで p を小さく出しすぎます。
    札を本の中でだけ入れ替えれば、**本ごとの伸びの回数はそのまま**で、
    「その伸びが帯を避けたのは偶然か」だけを訊けます。

    **これは §5 の「教訓の形」（確かめる手を足すときは、それが元の手と違う物を見ているかを先に撃つ）
    を通してあります**: 生の 0/203 は齢で全部 説明できてしまう見込みが在り、
    齢を揃えると `expected` が 7.33 → p_va 0.031 と**別の答え**になりました（足した回の実測）。

    **覆る条件**: (1) `p_va` が 0.05 を越えたら、帯の 0 は齢で説明できる範囲に戻る
    （そのときは §7 の「帯の回は伸びを読めない」を、齢の帯の話に書き直すこと）。
    (2) 公開の刻を変えた本が出たら交絡そのものが解けるので、並べ替えは要らなくなる。
    """
    import random

    pairs = _pairs(rows)
    observed = sum(1 for p in pairs if p["band"] and p["grew"])
    per_bucket: list[tuple[tuple[int, int] | None, int, int, int, int]] = []
    expected = 0.0
    for lo, hi in AGE_BUCKETS:
        bi = [p for p in pairs if p["bucket"] == (lo, hi) and p["band"]]
        ou = [p for p in pairs if p["bucket"] == (lo, hi) and not p["band"]]
        rate = (sum(p["grew"] for p in ou) / len(ou)) if ou else 0.0
        expected += rate * len(bi)
        per_bucket.append(((lo, hi), sum(p["grew"] for p in bi), len(bi),
                           sum(p["grew"] for p in ou), len(ou)))

    rng = random.Random(seed)

    def _perm(by_bucket: bool) -> float:
        groups: dict[tuple, list[dict]] = {}
        for p in pairs:
            groups.setdefault((p["vid"], p["bucket"]) if by_bucket else (p["vid"],), []).append(p)
        live = [(g, sum(x["grew"] for x in g)) for g in groups.values()]
        live = [(g, k) for g, k in live if k]
        if not live:
            return 1.0
        hits = 0
        for _ in range(iters):
            tot = 0
            for g, k in live:
                tot += sum(rng.sample([x["band"] for x in g], k))
            if tot <= observed:
                hits += 1
        return hits / iters

    # **長さで揃える**（齢で揃えるより素直な対照）。
    # 帯の組は**外の組より長い**（中央 151分 対 123分・平均 189分 対 144分）ので、
    # 帯は伸びる機会を**多く**持っていて 0 です ＝ 長さの偏りは、この結論と**逆向き**に効いています。
    band_h = sum(p["gap_min"] for p in pairs if p["band"]) / 60.0
    out_h = sum(p["gap_min"] for p in pairs if not p["band"]) / 60.0
    out_grew = sum(1 for p in pairs if not p["band"] and p["grew"])
    per_hour = (out_grew / out_h) if out_h else 0.0
    matched = [p for p in pairs if 100 <= p["gap_min"] <= 200]
    mb = [p for p in matched if p["band"]]
    mo = [p for p in matched if not p["band"]]

    return {"observed": observed, "expected": expected,
            "p_video": _perm(False), "p_va": _perm(True),
            "buckets": per_bucket, "pairs": len(pairs),
            # 帯が外と同じ「組×時間あたり」で伸びていたら、帯の中に在るはずの伸びの数
            "expected_per_hour": per_hour * band_h,
            "band_hours": band_h, "out_hours": out_h,
            # 100〜200分 の組だけで揃えたもの（伸びた/全体）
            "matched": (sum(p["grew"] for p in mb), len(mb),
                        sum(p["grew"] for p in mo), len(mo))}


def lines(rows: list[dict], within_h: float = 24 * 3, now: dt.datetime | None = None) -> list[str]:
    now = now or now_jst()
    mine = ours(rows)
    ser = series(rows)
    gone = returned_private(rows)
    days: dict[str, list[tuple[dt.datetime, str, list[dict]]]] = {}
    # 公開されたあと private へ戻した本は、行は出すが**日の本数に入れない**（`returned_private` の註）。
    back_days: dict[str, list[tuple[dt.datetime, str, list[dict]]]] = {}
    for vid, pts in ser.items():
        pub = published_at(pts)
        if (now - pub).total_seconds() / 3600 > within_h:
            continue
        bucket = back_days if vid in gone else days
        bucket.setdefault(pub.strftime("%m/%d"), []).append((pub, vid, pts))
    # まだ公開前の本（予約）も日ごとに束ねる —— 見出しの本数から抜けると §7 が「1本 だけの日」と読む（`pending` の註）。
    waiting_days: dict[str, list[tuple[dt.datetime, str, str]]] = {}
    for vid, (pub, title) in pending(rows).items():
        if vid in ser:  # もう公開されて measured が付いた本は「予約」ではない
            continue
        if (now - pub).total_seconds() / 3600 > within_h:
            continue
        waiting_days.setdefault(pub.strftime("%m/%d"), []).append((pub, vid, title))
    # **日の見出しの本数は、窓で切らずに台帳ぜんぶから数える**（2026-09-09 10:4x に直した。下の註）。
    all_day_count: dict[str, int] = {}
    day_newest: dict[str, dt.datetime] = {}
    for vid, pts in ser.items():
        if vid in gone:
            continue
        pub = published_at(pts)
        key = pub.strftime("%m/%d")
        all_day_count[key] = all_day_count.get(key, 0) + 1
        if key not in day_newest or pub > day_newest[key]:
            day_newest[key] = pub
    out: list[str] = []
    for day in sorted(set(days) | set(waiting_days) | set(back_days), reverse=True):
        cohort = sorted(days.get(day, []))
        waiting = sorted(waiting_days.get(day, []))
        back = sorted(back_days.get(day, []))
        whole = all_day_count.get(day, len(cohort))
        head = f"{day}（{len(cohort)}本" + (f"＋予約 {len(waiting)}本" if waiting else "") + "）"
        if whole > len(cohort):
            head = (f"{day}（この日は {whole}本・**この窓に出るのは {len(cohort)}本**"
                    + (f"＋予約 {len(waiting)}本" if waiting else "")
                    + "。窓の縁で切れている ——`--days` を伸ばすこと）")
        out.append(head)
        for pub, vid, pts in cohort:
            mark = "新" if vid in mine else "旧"
            env = envelope(pts)
            trail = " → ".join(
                f"{p['age_h']:.1f}h {v}" + (f"(生 {p['views']})" if v != int(p["views"]) else "")
                for p, v in list(zip(pts, env))[-6:])
            out.append(f"  {pub:%H:%M} {mark} {vid:12s} {trail}{_growth(pts, env)}")
        for pub, vid, title in waiting:
            out.append(f"  {pub:%H:%M} 予 {vid:12s} まだ公開前（この日の本数に入る） {title[:30]}")
        for pub, vid, pts in back:
            last = pts[-1]
            out.append(
                f"  {pub:%H:%M} 戻 {vid:12s} {last['age_h']:.1f}h {last['views']}回 で private へ戻した"
                "（**この日の本数に入れない**・この点は更新されない）")
    if not out:
        out.append("（台帳に、この日数のうちに公開された本の measured がありません）")
    # **窓より前の日は、丸ごと消えるのではなく「切れている」と言う**
    # （2026-09-09 15:2x・optimizer・Opus が踏んだ）。10:4x の直しは
    # **一部だけ**が窓に入る日に「窓の縁で切れている」を付けたが、
    # **その日の本が1本も入らない日は `days` に入らないので、見出しごと出ない**。
    # 実測 09/09 15:2x: `--days 3`（既定）で **09/06 が丸ごと消えた** ——
    # いちばん若い本が 73.3h ＝ 72h の窓の外に出たため。
    # 09/06 は 8本 の日で、**§7 の「天井 437回」も「中央値 196回」もこの日から引いています**。
    # ＝ **§7 が毎周 引く対照が、道具の既定の窓から黙って落ちた。**
    # 読む側は「09/06 は無かった」と「09/06 は切れた」を区別できない。
    # **覆る条件**: `--days` の既定が窓の外の日を持たない長さに変わったら、この行は出なくなる（害は無い）。
    shown = set(days) | set(waiting_days) | set(back_days)
    cut = sorted((d for d in all_day_count if d not in shown),
                 key=lambda d: day_newest[d], reverse=True)
    if cut:
        head = "・".join(f"{d}（{all_day_count[d]}本）" for d in cut[:3])
        more = f" ほか {len(cut) - 3}日" if len(cut) > 3 else ""
        out.append(
            f"窓（`--days {within_h / 24:g}`）より前の日は、この並びに**出ていません**: "
            f"{head}{more}。**「その日は無かった」ではありません** —— 引くなら `--days` を伸ばすこと。")
    # **帯の数は、帯の中に居る回だけでなく毎回 印字する** —— §7 は毎周この数を書き写しており、
    out.extend(hold_lines(rows))
    out.extend(first_view_lines(rows))
    # 手で数え直すたびに数え方が揺れていた（2026-09-09 00:2x）。
    nm, nt, om, ot = dead_window(rows)
    out.append(
        f"帯 {DEAD_START:02d}:00〜{DEAD_END:02d}:00 JST の2点組 **{nm}/{nt}** が伸びた"
        f"（それ以外は {om}/{ot}）。**{MIN_PAIR_MIN:.0f}分 未満の2点組は数えていません**"
        "（長さの違う組を同じ分母に入れないため —— studio/trend.py の `MIN_PAIR_MIN` の註）。")
    # **§7 の覆る条件 (2) の物差し（`informative`）も、帯の外の回に印字する**
    # （2026-09-09 10:4x・optimizer・Opus が足した。この回に踏んだ ——
    #  measure が 10:36 JST ＝ 帯の外に落ち、下の帯の中の段落が出なかったので、
    #  条件 (2) の「検出できた組」を **手で数え直した**。§7 が 7周 踏んだ「分母を手で数える」形そのもの。
    #  生の分母（上の行）は 04:4x に「帯の外でも毎回 印字する」に直っているのに、
    #  **判定に使う分母のほうが帯の中でしか出ていなかった**）。
    _inf = informative(rows)
    _bg, _bn = _inf["band"]
    _og, _on = _inf["out"]
    out.append(
        f"うち**伸びを検出できた組**は 帯 **{_bg}/{_bn}** 対 外 **{_og}/{_on}**"
        f"（同じ本が齢±{_inf['window_h']:.0f}h の逆側でも伸びていた組だけ。`informative` の註）。"
        f"**§7 の覆る条件 (2) はこの分母で読むこと** —— 20組 を越えるまでは「まだ測れていない」。"
        f"**この分母は帯の中で measure を撃った回にしか増えません**（帯の組は "
        f"{_inf['occasions']}回 の測りから）。")
    # **門 (2) は、そろえた側で読むこと**（2026-09-10 03:0x・optimizer・Opus。`_matched` の註）。
    _bmg, _bmn = _inf["band_matched"]
    _omg, _omn = _inf["out_matched"]
    _un = "・".join(f"{lo}〜{hi if hi < 9999 else ''}h" for lo, hi in _inf["unmatched"]) or "無し"
    _raw = f"{(_bg / _bn) / (_og / _on):.3f}倍" if _bn and _on and _og else "—"
    _mat = f"{(_bmg / _bmn) / (_omg / _omn):.3f}倍" if _bmn and _omn and _omg else "—"
    _gbg, _gbn = _inf["band_gapmatched"]
    _gog, _gon = _inf["out_gapmatched"]
    _r1 = (_bmg / _bmn) / (_omg / _omn) if _bmn and _omn and _omg else None
    _r2 = (_gbg / _gbn) / (_gog / _gon) if _gbn and _gon and _gog else None
    _gmat = f"{_r2:.3f}倍" if _r2 is not None else "—"
    _gdiff = f"{abs(_r2 - _r1):.3f}倍" if _r1 is not None and _r2 is not None else "—"
    _bgm = f"{_inf['band_gap_med']:.1f}分" if _inf.get("band_gap_med") else "—"
    _ogm = f"{_inf['out_gap_med']:.1f}分" if _inf.get("out_gap_med") else "—"
    # **門 (2) を読む側は、道具が言う**（2026-09-10 09:0x・optimizer・Opus。
    #  この回に差が 0.103倍 ＝ 門 0.1 を越え、`_matched` の覆る条件 (0) が引かれた。
    #  「読み替えだけ」で足りるが、**読み替えを人の記憶に置くと次の回が古い側を読む**ので、
    #  どちらで読むかを毎周 印字する ——`gate_side` は返り値にも残る）。
    _side, _gate = (("齢＋長さ", _r2) if _r1 is not None and _r2 is not None
                    and abs(_r2 - _r1) >= GAP_SPLIT else ("齢だけ", _r1))
    _gs = f"**{_side} の {_gate:.3f}倍**" if _gate is not None else "—"
    out.append(
        f"**齢の束をそろえると 帯 {_bmg}/{_bmn} 対 外 {_omg}/{_omn}（{_mat}）**"
        f" —— そろえない生の側は {_raw}。**組の長さもそろえると {_gmat}**"
        f"（帯 {_gbg}/{_gbn} 対 外 {_gog}/{_gon}・組の長さの中央値 帯 {_bgm}／外 {_ogm}）"
        f" —— **齢だけの比との差 {_gdiff}**（門 {GAP_SPLIT}倍・`_matched` の覆る条件 (0)）。"
        f"**§7 の門 (2)（0.5倍）を読む側は {_gs}** ——"
        f"差が {GAP_SPLIT}倍 を越えた回から、門は齢＋長さ の側で読みます（`_matched` の覆る条件 (0)）。"
        f"{_span_line(rows)}"
        f"**帯に1組も無い齢の束**: {_un}"
        f" —— 公開が 10:00 JST に固定なので、帯が持てる齢は 16〜24h・40〜48h… だけです。"
        f"**そこは伸びのいちばん濃い齢を含みません** ＝ そろえない比は、帯ではなく齢を測ります。")
    np_, nd, worst, where = drops(rows)
    out.append(
        f"同じ {np_}組 のうち、再生が**減った**組 **{nd}**"
        + (f"・いちばん大きい減り **{worst}回**（{where}）" if nd else "")
        + "。**帯の率と同じ分母です**（手で数え直すと分母が2つになる —— studio/trend.py の `drops` の註）。")
    rc = recounts(rows)
    if rc:
        out.append(
            f"**数え直し（下へ）: {len(rc)}本** —— 生が包絡を **{ENVELOPE_LAG_H:.0f}時間** より長く下回ったまま戻らなかった峰"
            f"（複製の遅れの実測は 最大 2.8時間 ＝ 遅れでは説明できない）。包絡はその水準まで**落としてあります**: "
            + "・".join(f"{r['id']} {r['from']}→{r['to']}（齢 {r['age_h']:.1f}h から {r['hours_below']:.1f}時間・{r['points_below']}点）"
                        for r in rc)
            + "。**`n_values` では見えません** —— 数え直しは周と周のあいだに起き、同じ周の 3回 読みは"
              "秒しか離れていない（§7 (h)・`trend.recounts` の註）。**割れた読みは下の行で別に数えます。**")
    else:
        out.append(
            f"**数え直し（下へ）: 0本**（生が包絡を {ENVELOPE_LAG_H:.0f}時間 より長く下回ったまま戻らなかった峰は無い）。"
            "**この 0 は `n_values` の 0 とは別の道です**（`trend.recounts` の註）。")
    # §7 (h) の覆る条件 (3) を、撃つだけで分母と分子まで読めるように（2026-09-10 10:2x・optimizer・Opus）。
    # **齢では分けません** —— 引いた当の行（齢 96.3h）が遅れの側だった（`trend.shakes` の註）。
    out.append(shakes_line(rows))
    # `cli.over_ledger` の 3つ の覆る条件は周をまたいで数える物で、印を残す口が無かった
    # （2026-09-10 13:2x・optimizer・Opus。`trend.over_lag` の註）。
    out.append(over_lag_line(rows))
    # 公開ずみで 0回 の本の処理の状態（`cli.zero_probe_target` の覆る条件は周をまたいで数える）。
    out.append(zero_probe_line(rows))
    out.append(views_absent_line(rows))
    # チャンネル全体の登録と総再生（`cli.record_channel` の註。**本ごとの 0回 を読む前に見る数**）。
    out.append(channel_line(rows))
    # 公開**前**の本の処理の印（`cli.record_ready` の註 ＝ 印字だけにしない族の 4つ目）。
    out.append(ready_line(rows, now=now))
    # 画像の注文の届き具合と、**届いた絵が いちばん新しい build に載っているか**
    # （`trend.image_orders` の註 ＝ 印字だけにしない族の 5つ目）。
    out.append(image_line(rows))
    # 上がった本の 題・説明欄をあとから直した回（§4 の出口を抜けた欠陥の数・`trend.meta_fixes` の註
    #  ＝ 台帳に在るのに 1行も読まれていなかった族の 6つ目）。
    out.append(meta_fix_line(rows))
    # §4 (0-c) の「外を1回 引く」の連（**本**で数える・`trend.outside_runs` の註
    #  ＝ 「N本 続いたら」と書いて N を数える口が無い族の 4つ目・`hourly` が §16 (8) で渡した）。
    out.append(outside_line())
    # `hear.tail_voice` / `head_voice` の覆る条件（`分けられない` が 3本 続けたら閾ではなく引き方）の連
    #  —— **同じ族の 10例目**。答えは 09/09 から台帳に積んであり、**読む物だけが無かった**
    #  （`trend.voice_runs` の註。**単位は「本」** ＝ 同じ本の聞き直しで数えない）。
    out.append(voice_line(rows))
    # §7 末尾「1日1本」の覆る条件（500回 が 7本 続いたら 2本/日 を試す）の連
    #  —— **同じ族の 5つ目**（`late_run`・`blind_run`・`reporting_empty_run`・`outside_runs`）。
    out.append(views_streak_line(rows))
    # §3 の 7-b（板）／7-c（しくみ）の覆る条件（その型の本 3本 の 48h が、持たない直近 3本 の
    #  中位を下回ったら 絞るか外す）を数える口 —— **同じ族の 7例目・8例目**
    #  （`late_run`・`blind_run`・`reporting_empty_run`・`outside_runs`・`views_streak`・`rev7_run`）。
    out.append(feature_line(rows))
    out.append(analytics_line(rows, now=now))
    # §7 の収益の節の 覆る条件 (4)（直近7日の平均が続けて上がったら、分子はチャンネルの回復の側）の連
    #  —— **同じ族の 6例目**（`late_run`・`blind_run`・`reporting_empty_run`・`outside_runs`・
    #  `views_streak`）。**単位は「引き」＝ 周ではありません**（`trend.rev7_run` の註）。
    out.append(rev7_line(rows))
    #  そのすぐ隣に「上がった分の中身」を出す（`rev7_line` の「引かれました」は連だけを見るので、
    #  この行が無いと分子の中身を見ないまま §1 を開けます・`trend.rev7_source_line` の註）。
    out.append(rev7_source_line(rows))
    # 一括レポート（3つ目の枠・**Data API 0単位**）を、台帳の包絡と並べる
    # （§7 (o-4)(3)・`trend.report_vs_ledger` の註 ＝ **複製から返らない唯一の口**）。
    out.append(report_vs_ledger_line(rows))
    cl = curve_line(rows)
    if cl:
        out.append(cl)
    # **この一文は最後に置くこと**（`tests/test_studio_trend.py` が末尾で止めている）。
    out.append(
        "並びの再生は **それまでの最大（単調な包絡・数え直しの峰は落とす）** です（`trend.envelope` の註・2026-09-09 20:0x／2026-09-10 08:0x）"
        "—— `videos.list` は伸びている本を **遅れの違う 3つ の複製**から返し、"
        "1点は真の値を **最大 28%（-249回）** 下に外します。**上げた点には `(生 N)` が付きます。**"
        "生の減りは下の行（`drops`）で数え続けています。")
    fl = flats(rows)
    where = "・".join(
        f"{r['id']} 齢{r['from_h']:.1f}→{r['to_h']:.1f}h（{r['len_h']:.1f}時間）" for r in fl["stayed"])
    # **門の数は `flats` から引くこと**（`ENVELOPE_LAG_H` は別の道具の定数で、
    # 2026-09-10 08:2x まで**ここだけ 6時間 と印字**していた。実際の門は 24時間 だった）。
    out.append(
        f"**平らは「止まった」ではない**（**始まり**が齢 48h 前の {FLAT_MIN_H:.0f}時間 以上 の平らな区間・`trend.flats`）: "
        f"**伸びが戻った {fl['resumed']}件 / 戻らないまま {fl['thresh_h']:.1f}時間 より長く見た {len(fl['stayed'])}件**"
        + (f"（{where}）" if where else "")
        + f"・まだ言えない平ら {fl['open']}件。"
        + (f"**決めに使うのは件数ではなく境目**: 戻った平らのいちばん長いもの **{fl['longest_resumed_h']:.1f}時間**"
           + (f" 〜 戻らなかった平らのいちばん短いもの **{fl['shortest_stayed_h']:.1f}時間** の"
              f"あいだは、まだ測れていません（差 {fl['shortest_stayed_h'] - fl['longest_resumed_h']:.1f}時間）。"
              if fl["stayed"] else "より短い平らを「止まった」と読まないこと。")
           if fl["resumed"] else "")
        + "齢の浅い1点で本を比べないこと。")
    if DEAD_START <= now.hour < DEAD_END:
        # **この一文は、数に追随させること**（2026-09-09 02:5x に直した）。
        # ここは長らく「**この台帳で再生が伸びたことのない帯です**」と、括弧の中の数と別に
        # **claim を直書き**していた。04:4x は「数は写しを持ちません —— 帯の中で1組でも伸びたら、
        # 印字はその日から変わります」と書いていたが、**変わったのは括弧の中の数だけ**で、
        # 文のほうは 02:59 に 2/228 になっても「伸びたことのない帯です」と言い続けた
        # （＝ 印字が自分の数と矛盾した）。**§7 が繰り返している「写しを持たない」の、この行ぶん。**
        nm, nt, om, ot = dead_window(rows)
        inf = informative(rows)
        bg, bn = inf["band"]
        og, on = inf["out"]
        if nm == 0:
            head = (f"**いまは {DEAD_START:02d}:00〜{DEAD_END:02d}:00 JST ＝ この台帳で"
                    f"再生が伸びたことのない帯です**（この帯の2点組 {nm}/{nt}・"
                    f"それ以外は {om}/{ot}）。")
        else:
            head = (f"**いまは {DEAD_START:02d}:00〜{DEAD_END:02d}:00 JST の帯の中です。"
                    f"この帯でも伸びた2点組が {nm}件 出ています**"
                    f"（{nm}/{nt}・それ以外は {om}/{ot}）。")
        out.append(
            head
            + f"**ただし分母のほとんどは「伸びを検出できない組」です** —— 帯の {inf['band_all']}組 のうち、"
            + f"同じ本が齢±{inf['window_h']:.0f}h の帯の外でも伸びていた組は **{bn}組** だけ"
            + f"（そこでの伸びは 帯 {bg}/{bn} 対 外 {og}/{on}）。"
            + f"帯の組は {inf['occasions']}回 の測りから出ています（1回で全部の本を測るので、"
            + "同じ回の組は独立ではありません）。**この回の「平ら」からは、止まったかどうかを読めません** ——"
            + "数を並べるだけにして、判定は帯の外の回へ渡すこと。"
            + "齢との交絡（この帯は齢 16〜19h／40〜43h と重なる）は `band_vs_age` が齢の束で揃えて見ますが、"
            + "**その p は、この回が いま撃った measure だけで動きます** ——"
            + "帯の中で測るたびに平らな組が分母へ入るので、**新しい伸びが1つも無くても p は小さくなります**"
            + "（実測 2026-09-09 05:5x: この回の measure を台帳から抜くと p_va 0.2015 → 0.3165・p_video 0.0245 → 0.05 に戻り、"
            + "動いたぶんは 25組 の平らだけ・うち 23組 は上の「検出できない組」でした）。"
            + f"**p を引くなら、上の {bg}/{bn} 対 {og}/{on}（検出できた組）と一緒にしか読めません。**")
    return out



#: この窓の再生がこれ未満の本は、維持率の比べから外す（外れ値だけで幅が決まる）。
ANALYTICS_MIN_VIEWS = 30


def analytics_state(rows: list[dict], now: dt.datetime | None = None) -> dict:
    """台帳の `analytics_*` をまとめる（**API 0単位** ＝ 引いたのは `cli analytics` の回）。

    返り: `last_day`（最後に引けた日）・`lag_days`・`age_h`（引いてから何時間）・
    `days`（日ごとの再生の直近3日）・`new`/`old`（新しい作り／旧作りの 平均視聴秒・平均視聴率）・
    `subs`（窓の中の登録の増えの合計）・`shorts_pct`（ショートのフィードの割合）。

    **新／旧 を分ける印は、行に書いてある `studio` です** —— `trend` は台帳しか読まないので、
    `scheduled` を数え直さないこと（`cli` が引いた回の判定をそのまま持つ）。
    """
    now = now or now_jst()
    day_rows = [r for r in rows if r.get("event") == "analytics_day"]
    vid_rows = [r for r in rows if r.get("event") == "analytics_video"]
    tr_rows = [r for r in rows if r.get("event") == "analytics_traffic"]
    if not day_rows:
        return {}
    last_day = max(r["id"] for r in day_rows)
    at = max(dt.datetime.fromisoformat(r["at"]) for r in day_rows)
    days = sorted(({r["id"]: r for r in day_rows}).values(), key=lambda r: r["id"])[-3:]
    last_tr = max(tr_rows, key=lambda r: r["at"]) if tr_rows else None
    latest = {}
    for r in sorted(vid_rows, key=lambda r: r["at"]):
        latest[r["id"]] = r          # 同じ本を2度 引いた回は、新しいほうだけ
    def _side(want: bool) -> dict:
        # **再生の少ない本を混ぜない** —— 1〜6回 の本は平均視聴率が 0% や 107.8% で出て、
        # 「〜」で挟むと幅がその外れ値だけで決まります（この口を足した回に踏んだ）。
        got = [r for r in latest.values()
               if bool(r.get("studio")) is want and (r.get("views") or 0) >= ANALYTICS_MIN_VIEWS]
        if not got:
            return {"n": 0}
        sec = sorted(r["avg_seconds"] for r in got)
        pct = sorted(r["avg_percent"] for r in got)
        return {"n": len(got), "avg_seconds": sec, "avg_percent": pct,
                "sec_med": sec[len(sec) // 2], "pct_med": pct[len(pct) // 2]}
    src = (last_tr or {}).get("sources") or {}
    tot = sum(src.values())
    return {"last_day": last_day, "lag_days": (last_tr or {}).get("lag_days"),
            "age_h": (now - at).total_seconds() / 3600,
            "days": [(r["id"], r["views"]) for r in days],
            "new": _side(True), "old": _side(False),
            "subs": sum(int(r.get("subs_gained") or 0) for r in latest.values()),
            "shorts_pct": (src.get("SHORTS", 0) / tot * 100) if tot else None,
            "sources": src}


def analytics_line(rows: list[dict], now: dt.datetime | None = None) -> str:
    """`analytics_state` を1行にする（`trend` が毎周 印字する ＝ **次の回は覚えていなくてよい**）。

    **維持率は Studio でしか見えない、ではありません**（2026-09-10 16:1x・optimizer・Opus。
    derivation と実測は `studio/analytics.py` の註）。
    """
    a = analytics_state(rows, now=now)
    if not a:
        return ("**維持率と流入は 1度も引いていません** —— `python -m studio.cli analytics`"
                "（**Data API 0単位**・別枠のクエリ 3回・`studio/analytics.py` の註）")
    d = "・".join(f"{day[5:]} {v}回" for day, v in a["days"])
    def _side(x: dict, name: str) -> str:
        if not x["n"]:
            return f"{name} なし"
        return (f"{name} {x['n']}本 **平均視聴 中央 {x['sec_med']}秒**（{x['avg_seconds'][0]}〜{x['avg_seconds'][-1]}）"
                f"・**平均視聴率 中央 {x['pct_med']:.1f}%**（{x['avg_percent'][0]:.1f}〜{x['avg_percent'][-1]:.1f}）")
    sp = f"・**ショートのフィード {a['shorts_pct']:.1f}%**" if a["shorts_pct"] is not None else ""
    return (f"**維持率と流入**（Analytics API・台帳から・**Data API 0単位**）: 最後の日 **{a['last_day']}**"
            f"（引いたのは {a['age_h']:.0f}時間 前・**遅れ {a['lag_days']}日 ＝ きょう公開した本には答えません**）。"
            f"日ごとの再生 {d}。{_side(a['new'], '新しい作り')} 対 {_side(a['old'], '旧作り')}"
            f"——**%と秒で向きが逆になります**（判定は `hourly`・§5）。"
            f"窓の中の**登録の増え 合計 {a['subs']}**{sp}")


#: §7 の収益の節の 覆る条件 (4) の門。**単位は「引き」で、周ではありません**（`rev7_run` の註）。
REV7_RUN_GATE = 3
#: 直近7日（収益の節の分子）と、その横に並べる 12日。
REV7_DAYS = 7
REV7_LONG_DAYS = 12
#: **上がった分の出どころ**の門（`rev7_source`）。**単位は「引き」**（`rev7_run` と同じ）。
REV7_SOURCE_GATE = 3
#: 基準2（ショート 直近90日 1,000万回）。**公表ページの写し**（§7 の収益の節・覆る条件 (10)）。
REV_GOAL_VIEWS = 10_000_000
REV_GOAL_DAYS = 90


def rev7_draws(rows: list[dict]) -> list[dict]:
    """**引きごとに、そのとき読めた「直近7日の平均」**を並べる（台帳の `analytics_day` だけ・API 0単位）。

    **1引き ＝ `analytics_day` の同じ `at` の塊**。`cli analytics` は**動いた日だけ**を台帳へ足す
    （`cli.analytics_days_to_log`）ので、塊の大きさは 1〜12行 と揃いません —— **行の数では分けないこと。**

    **同じ日までを引き直した回は落とします**（`last_day` が進まなかった引き ＝ 実測 09/10 の 3回）。
    平均は**そのとき台帳に在った値**で組み直します（古い日は後から書き直されるので、
    いまの値で過去の点を作ると、**そのとき読めなかった数**が並びます）。

    返り: 引きごとに `{"at", "last_day", "n", "avg", "n_long", "avg_long"}`。
    """
    day_rows = sorted((r for r in rows if r.get("event") == "analytics_day" and r.get("id")),
                      key=lambda r: (r["at"], r["id"]))
    known: dict[str, int] = {}
    out: list[dict] = []
    last_seen: str | None = None
    for at in dict.fromkeys(r["at"] for r in day_rows):
        for r in day_rows:
            if r["at"] == at:
                known[r["id"]] = int(r.get("views") or 0)
        days = sorted(known)
        if days[-1] == last_seen:
            continue
        last_seen = days[-1]
        win, lon = days[-REV7_DAYS:], days[-REV7_LONG_DAYS:]
        out.append({"at": dt.datetime.fromisoformat(at).astimezone(JST),
                    "last_day": days[-1],
                    "n": len(win), "avg": sum(known[d] for d in win) / len(win),
                    "n_long": len(lon),
                    "avg_long": sum(known[d] for d in lon) / len(lon)})
    return out


def rev7_run(rows: list[dict]) -> dict:
    """**直近7日の平均が、いま何回 続けて上がっているか**（`rev7_draws` の並び・API 0単位）。

    **なぜ要るか**（2026-09-12 21:2x・optimizer・Opus）: §7 の収益の節の 覆る条件 (4) は
    「直近7日の平均が **3周 続けて上がったら**、分子は『新しい本』ではなくチャンネル全体の回復の側
    ＝ そのとき §1 の『量は毒』を数字で開け直すこと」と書いてありますが、
    **その回数を数える口が在りませんでした**（`late_run`・`blind_run`・`reporting_empty_run`・
    `outside_runs`・`views_streak` と同じ族の 6例目）。

    **同じ回に、単位のほうが外れていることも分かりました。**
    この平均が動くのは `cli analytics` を撃った回だけで、その口は **20時間 の門**（`cli.ANALYTICS_MIN_H`）
    ＝ **1日1回**です。周は 1時間 弱 なので、**周で数えると引いた次の周に必ず「上がらなかった」が入り、
    連は永久に 1 で切れます** —— つまり (4) は、書かれたままの単位では**引けない条件**でした
    （2026-09-12 20:3x の「時刻 10:00」＝ 自分では引けない条件 の 2例目。**あちらは分母が割れない側**、
    **こちらは分母が速すぎる側**）。**数える単位は「引き」**（＝ 新しい日が入った回）。

    返り: `{"run", "gate", "drawn", "since", "draws", "split"}`。
    `split` は **7日 が上がって 12日 が下がった**引き（窓から落ちた日のほうで上がった疑い）。

    **覆る条件**: (1) `split` が立った引きで連が門に届いたら、**上がりは「回復」ではなく
        窓が落とした日の側**かもしれない ＝ その回は 12日 の並びも一緒に置くこと
        （**判定は `hourly` とオーナー**・§5）。
    (2) `cli analytics` の門（20時間）が外れて 1周に 1回 引けるようになったら、単位は「引き」のまま
        でよい（引き ＝ 周 になるだけ）。**周へ戻さないこと。**
    (3) Analytics の遅れ（いま 2〜3日）が変わって、同じ引きで日が 2日 以上 進む回が出たら、
        1引き ＝ 1日 ではなくなります ＝ そのときは日で数え直すこと。
    """
    draws = rev7_draws(rows)
    run: int = 0
    since: dt.datetime | None = None
    split = False
    for prev, cur in zip(draws, draws[1:]):
        if cur["avg"] > prev["avg"]:
            run += 1
            since = since or cur["at"]
            split = cur["avg_long"] < prev["avg_long"]
        else:
            run, since, split = 0, None, False
    return {"run": run, "gate": REV7_RUN_GATE, "drawn": run >= REV7_RUN_GATE,
            "since": since, "draws": draws, "split": split}


def rev7_line(rows: list[dict]) -> str:
    """`rev7_run` を1行にする（`trend` が毎周 印字する ＝ **§7 へ写さないこと**）。

    **距離も一緒に出します** —— §7 の収益の節の「距離 101〜205倍」は**写した数**で、
    書いた刻（2026-09-10）から動きます（写すと二重に古くなる ＝ §7「次に見る所」の形）。
    """
    r = rev7_run(rows)
    draws = r["draws"]
    if not draws:
        return ("**収益の門までの距離（(4) の分子）: まだ 1度も引いていません** —— "
                "`python -m studio.cli analytics`（**Data API 0単位**）")
    d = draws[-1]

    def _far(avg: float) -> str:
        got = avg * REV_GOAL_DAYS
        return f"{got:,.0f}回 ＝ {got / REV_GOAL_VIEWS * 100:.2f}%（**{REV_GOAL_VIEWS / got:.0f}倍**）"

    head = (f"**収益の門までの距離**（基準2 ＝ ショート 直近90日 {REV_GOAL_VIEWS:,}回・"
            f"台帳の `analytics_day` だけ・**Data API 0単位**・`trend.rev7_run`）: "
            f"最後の引き **{d['at']:%m/%d %H:%M}**（日は {d['last_day']} まで）の"
            f"**直近{d['n']}日 平均 {d['avg']:.1f}回/日** → 90日 {_far(d['avg'])}／"
            f"**{d['n_long']}日 平均 {d['avg_long']:.1f}回/日** → 90日 {_far(d['avg_long'])}。")
    if len(draws) < 2:
        return head + "**上がり下がりは、引きが 2回 そろってから**（`rev7_run` の註）"
    series = " → ".join(f"{x['avg']:.1f}" for x in draws[-4:])
    tail = (f"**直近7日の平均の並び（引きごと・新しい 4つ まで）: {series}** ＝ "
            f"**上がりが {r['run']}/{r['gate']}回 続いています**"
            "（**単位は「引き」＝ 周ではありません** —— `analytics` は 20時間 の門で 1日1回 しか動かず、"
            "周で数えると連は永久に 1 で切れます・`rev7_run` の註）。")
    if r["split"]:
        tail += (f"**ただし この引きは {REV7_DAYS}日 が上がって {REV7_LONG_DAYS}日 が下がっています** ＝ "
                 "上がりは**窓から落ちた日**の側かもしれません（`rev7_run` の覆る条件 (1)）。")
    if r["drawn"]:
        tail += ("**＝ 引かれました。§7 の収益の節の 覆る条件 (4) の刻です** —— "
                 "分子は「新しい本」ではなく**チャンネル全体の回復**の側 ＝ "
                 "**§1 の「量は毒」を数字で開け直すこと**（**判定は `hourly` とオーナー**・§5。"
                 "同じ回に (5)（長尺を開け直す理由）も読むこと）。")
    else:
        tail += "**判定は `hourly` とオーナー**（§5 ＝ optimizer は数を並べるまで）。"
    return head + tail


def rev7_source(rows: list[dict]) -> dict:
    """**上がった分は「新しい本」か「チャンネル全体の回復」か**（台帳の `analytics_video` だけ・API 0単位）。

    **なぜ要るか**（2026-09-13 09:1x・`hourly`・Opus が足した）: §7 の収益の節の 覆る条件 (4) は
    「直近7日の平均が 3回 続けて上がったら、**分子は『新しい本』ではなくチャンネル全体の回復の側**」
    と書いてあり、`rev7_run` は **その連だけ**を数えます —— **分子が何でできているかを、
    どの口も見ていませんでした。** 答えはもう台帳に在ります: `analytics_video` の `studio` の札
    （`cli` が引きごとに本ごとで書く）。

    **12日 では代われません**（この回の実測）: 12日 は **1097.6 → 933.3 → 864.9 → 664.9** で
    3回 とも下がり、7日 は 3回 とも上がりました ＝ **どちらも同じ日を別の重みで足し直しただけ**で、
    分子の中身は分けていません。**分けるのは `studio` の札だけです。**

    返り: `{"draws", "old_run", "gate", "drawn"}`。`draws` は引き（`analytics_video` の同じ `at` の塊）
    ごとに `{"at", "day", "start", "total", "studio", "old", "share"}`（古い順）。
    **単位は「引き」**（`rev7_run` と同じ ＝ 周ではありません）。

    **覆る条件**: (1) 古い側（`old`）が **3引き 続けて上がったら**、そのとき初めて
        「チャンネル全体の回復」＝ (4) の刻（**判定は `hourly` とオーナー**・§5）。
    (2) `studio` の札が付かない本が出たら（`cli` の側の欄落ち）、この分けは黙って狂います。
        **`total` を `analytics_day` の合計と引き比べないこと** —— 窓の頭が 1日 ずれます
        （実測 5,374 対 5,691）。見るのは **札の付いた本が 0本 になっていないか**のほう。
    (3) 古い本を private に戻した回が出たら、`old` は「回復しなかった」ではなく「盤から降りた」側
        ＝ 台帳の `unscheduled` と一緒に読むこと。
    """
    draws: dict[str, list[dict]] = {}
    for r in rows:
        if r.get("event") == "analytics_video" and r.get("at"):
            draws.setdefault(r["at"], []).append(r)
    out: list[dict] = []
    for at in sorted(draws):
        g = draws[at]
        tot = sum(int(r.get("views") or 0) for r in g)
        new = sum(int(r.get("views") or 0) for r in g if r.get("studio"))
        out.append({"at": dt.datetime.fromisoformat(at).astimezone(JST),
                    "day": g[0].get("day"), "start": g[0].get("start"),
                    "total": tot, "studio": new, "old": tot - new,
                    "share": (new / tot) if tot else 0.0})
    kept: list[dict] = []          # 同じ日までを引き直した回は落とす（`rev7_draws` と同じ規則）
    for d in out:
        if kept and kept[-1]["day"] == d["day"]:
            kept[-1] = d
        else:
            kept.append(d)
    old_run = 0
    for prev, cur in zip(kept, kept[1:]):
        old_run = old_run + 1 if cur["old"] > prev["old"] else 0
    return {"draws": kept, "old_run": old_run, "gate": REV7_SOURCE_GATE,
            "drawn": old_run >= REV7_SOURCE_GATE}


def rev7_source_line(rows: list[dict]) -> str:
    """`rev7_source` を1行にする（`trend` が毎周 印字する ＝ **§7 へ写さないこと**）。

    **§5 教訓の形 7つ目**（覆る条件を註に書いたら、それを読む**印字**も一緒に作ること）——
    `rev7_line` の「引かれました」は連だけを見て「チャンネル全体の回復の側」と言い切るので、
    **その隣にこの行が無いと、読む側は分子の中身を見ないまま §1 を開けます。**
    """
    s = rev7_source(rows)
    draws = s["draws"]
    if len(draws) < 2:
        return ("**上がった分の出どころ（(4) の分子の中身）: まだ引きが 2回 そろっていません**"
                "（`trend.rev7_source`）")
    d = draws[-1]
    new_ser = " → ".join(f"{x['studio']:,}" for x in draws[-4:])
    old_ser = " → ".join(f"{x['old']:,}" for x in draws[-4:])
    line = (f"**上がった分の出どころ**（`analytics_video` の `studio` の札・**Data API 0単位**・"
            f"`trend.rev7_source`）: 最後の引き **{d['at']:%m/%d %H:%M}**（窓 {d['start']}〜{d['day']}）は "
            f"**新しい本 {d['studio']:,}回 / 古い本 {d['old']:,}回**（新しい本の取り分 **{d['share']*100:.1f}%**）。"
            f"**引きごとの並び（新しい 4つ まで）: 新しい本 {new_ser} ／ 古い本 {old_ser}**。")
    if s["drawn"]:
        line += (f"**古い側が {s['old_run']}/{s['gate']}引き 続けて上がっています ＝ "
                 "ここで初めて『チャンネル全体の回復』です**（`rev7_source` の覆る条件 (1)・"
                 "**判定は `hourly` とオーナー**・§5）。")
    else:
        line += (f"**古い側の連は {s['old_run']}/{s['gate']}引き** ＝ "
                 "**上がった分は新しい本の側です** —— **`rev7_line` の「引かれました」だけで "
                 "§1 の「量は毒」を開けないこと**（2026-09-13 09:1x の判定・§7 の収益の節 (4)）。")
    return line


def curve_state(rows: list[dict]) -> dict:
    """台帳の `analytics_curve` を新／旧に分けてまとめる（**API 0単位**）。

    **刻（`p10`…）は割合であって秒ではありません** —— 新旧で尺が 3倍 違うので、
    同じ刻は同じ秒ではありません（2026-09-11 11:4x・hourly・Opus。下の `curve_seconds` の註）。
    """
    latest: dict[str, dict] = {}
    for r in sorted((r for r in rows if r.get("event") == "analytics_curve"),
                    key=lambda r: r["at"]):
        latest[r["id"]] = r
    def _side(want: bool) -> list[tuple[str, dict]]:
        return [(r["id"], r["marks"]) for r in latest.values()
                if bool(r.get("studio")) is want and r.get("marks")]
    empty = [r["id"] for r in latest.values() if not r.get("marks")]
    return {"new": _side(True), "old": _side(False), "empty": empty}


def curve_seconds(rows: list[dict]) -> dict[str, float]:
    """本ごとの**尺（秒）**を台帳から出す（**API 0単位**）: `analytics_video` の
    `avg_seconds / avg_percent × 100`。`avg_percent` が 0 の本は出しません（割れないので）。

    **なぜ要るか**（2026-09-11 11:4x・hourly・Opus が足した）: `analytics_curve` の刻は
    **割合**（`elapsedVideoTimeRatio`）なので、**尺の違う本を同じ刻で比べると、違う秒を比べます**。
    実測: 旧作り 5本 は **25.1〜32.5秒**・新しい作り 2本 は **90.3〜92.7秒**（**3倍**）＝
    `p10` は 旧 **2.5〜3.2秒**・新 **9.0〜9.3秒**。
    """
    out: dict[str, float] = {}
    for r in sorted((r for r in rows if r.get("event") == "analytics_video"),
                    key=lambda r: r["at"]):
        pct = r.get("avg_percent") or 0
        if pct > 0:
            out[r["id"]] = round((r.get("avg_seconds") or 0) / pct * 100, 1)
    return out


def curve_at(marks: dict, dur: float, sec: float) -> float | None:
    """刻を秒に直して、その秒を**挟む2点の直線**で読む（挟めなければ `None`）。

    **直線は上に外します** —— 維持率カーブは下に凸（はじめが急で、あとは平ら）なので、
    2点を結ぶ弦は**カーブの上**を通ります。＝ ここで出る値は**上限**です。
    刻が 5つ しか台帳に無いあいだは、この向きを憶えて読むこと（`analytics.CURVE_MARKS`）。
    """
    if not marks or not dur:
        return None
    pts = sorted((float(k[1:]) / 100 * dur, v) for k, v in marks.items())
    if sec < pts[0][0] or sec > pts[-1][0]:
        return None
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x0 <= sec <= x1:
            return y0 + (sec - x0) / (x1 - x0) * (y1 - y0) if x1 > x0 else y0
    return None


def curve_secs(rows: list[dict], n: int = 2) -> tuple[float, ...]:
    """同じ秒で読む**秒の選び方**: 新しい作りの刻そのもの（いちばん後ろの本に合わせる）。

    **なぜ新の刻に寄せるか**: そこでは新の側が**実測の刻**で、挟むのは旧の側だけになります
    （`curve_at` の弦は上に外すので、**旧が上限・新が実測** ＝ 差は控えめに出ます）。
    """
    c = curve_state(rows)
    dur = curve_seconds(rows)
    per = []
    for i, m in c["new"]:
        if i in dur:
            per.append(sorted(float(k[1:]) / 100 * dur[i] for k in m))
    if not per:
        return ()
    return tuple(round(max(p[j] for p in per), 1) for j in range(min(n, min(len(p) for p in per))))


def curve_aligned(rows: list[dict], secs: tuple[float, ...] | None = None) -> list[dict]:
    """**同じ秒**で新旧を読む（**API 0単位**・`curve_at` と `curve_seconds` だけ）。

    **2026-09-11 11:4x・hourly・Opus の判定**（§5 の「判定は `hourly`」の当のもの）:
    **`10%` の比べは、新 9秒 と 旧 3秒 を比べていました。** 同じ秒に直すと向きが逆です ——

        9.3秒   新 **0.71・0.81**   旧 **0.50〜0.75**（上限）   ＝ **束は重なる**
        15秒    新 0.68・0.70       旧 0.36〜0.51（上限）      ＝ 新が上
        23.2秒  新 **0.53・0.64**   旧 **0.15〜0.35**（上限）   ＝ **新が上・重ならない**

    **旧の側だけが上限**（`curve_at` の註 ＝ 弦はカーブの上）なので、**差は実際にはもっと大きい**。
    旧が 3秒 で `1.00` を越えるのは**ループ**です（25〜30秒 のショートは1周して頭へ戻る・
    90秒 の本は戻らない）＝ **`p10` の「旧が上」はループと尺で、作りではありません。**

    **＝ 維持率カーブは「新しい作りの出だしが人を落としている」の根拠になりません。**
    §3 の (1)（1文目で誰に向けた何の話か）を、この数で書き換えないこと。

    **覆る条件**: (1) `analytics.CURVE_MARKS` に刻を足して**挟まずに**読める回が来たら、
    その値でこの表を撃ち直すこと（いまは 5刻 ＝ 旧の側は挟みの上限）。
    (2) 新しい作りが 3本 以上 になって、同じ秒でも旧の束の**下**に入ったら、この判定は外れ。
    (3) 尺が 30秒 台の本を新しい作りで出したら、その本は同じ刻で比べてよい（尺がそろう）。
    """
    c = curve_state(rows)
    dur = curve_seconds(rows)
    out = []
    for sec in (curve_secs(rows) if secs is None else secs):
        row = {"sec": sec}
        for name, side in (("new", c["new"]), ("old", c["old"])):
            got = [(i, curve_at(m, dur.get(i, 0.0), sec)) for i, m in side]
            row[name] = sorted(v for _, v in got if v is not None)
        out.append(row)
    return out


def curve_line(rows: list[dict]) -> str:
    """`curve_state` を1行にする（`trend` が毎周 印字する ＝ **次の回は覚えていなくてよい**）。"""
    c = curve_state(rows)
    if not c["new"] and not c["old"]:
        return ""
    def _fmt(side, name):
        if not side:
            return f"{name} なし"
        p10 = sorted(m["p10"] for _, m in side)
        p95 = sorted(m["p95"] for _, m in side)
        return (f"{name} {len(side)}本 **10% で {p10[0]:.2f}〜{p10[-1]:.2f}**"
                f"・95% で {p95[0]:.2f}〜{p95[-1]:.2f}")
    tail = (f"・**空 {len(c['empty'])}本**（`analytics.curve` の覆る条件 (1)）" if c["empty"] else "")
    dur = curve_seconds(rows)
    def _dur(side, name):
        got = sorted(dur[i] for i, _ in side if i in dur)
        return f"{name} {got[0]:.0f}〜{got[-1]:.0f}秒" if got else f"{name} 尺 不明"
    al = []
    for r in curve_aligned(rows):
        if r["new"] and r["old"]:
            al.append(f"**{r['sec']:.0f}秒 新 {'・'.join(f'{v:.2f}' for v in r['new'])}"
                      f" 対 旧 {r['old'][0]:.2f}〜{r['old'][-1]:.2f}**")
    aligned = ("。**同じ刻は同じ秒ではありません**（尺 " + _dur(c["new"], "新") + "・"
               + _dur(c["old"], "旧") + " ＝ `10%` は 新 9秒 対 旧 3秒）。"
               "**同じ秒で読むと向きは逆**: " + "／".join(al)
               + "（**旧の側は挟みの上限** ＝ 差はもっと大きい・`curve_at` の註）。"
               "**旧が 3秒 で 1.00 を越えるのはループ**（30秒 の本は1周して頭へ戻る）"
               " ＝ **`10%` の差はループと尺で、作りではありません**。"
               "**§3 の (1) を、この数で書き換えないこと**"
               "（覆る条件は `curve_aligned` の註・2026-09-11 11:4x）"
               if al else
               "。**同じ秒では読めていません**（尺か刻が足りない ＝ `curve_aligned` の註）")
    return ("**維持率カーブ**（どこで落ちるか・台帳から・**Data API 0単位**）: "
            + _fmt(c["new"], "新しい作り") + " 対 " + _fmt(c["old"], "旧作り")
            + "。**1.00 より上は見直しで人が戻った側**" + aligned
            + " —— **判定は `hourly`・§5**（optimizer は数を並べるまで）" + tail)


def report(within_h: float = 24 * 3) -> list[str]:
    return lines(ledger_rows(), within_h=within_h)


#: **「その日に何本 出したか」を軸にして 48時間 の再生を並べ直す**
#: （2026-09-08 17:0x JST・optimizer・Opus が §7 の覆る条件に呼ばれて足した）。
#:
#: §7 15:0x/16:0x の覆る条件は「`lQHX9LJ80Sg` が 48h で 214回（09/06 の旧作りの中央値）を越えたら、
#: **日ごとの本数を軸に入れて数え直すこと**」と書いていた。17:0x に 7.1h 236回 で越えたので数え直した結果、
#: **この軸は、この台帳では日付と同じ物でした**:
#:
#:     4本/日 → 08/16 だけ    5本/日 → 09/05 だけ    13本/日 → 08/23 だけ    25本/日 → 08/22 だけ
#:     ＝ ほとんどの「本数」の値は **1日 にしか出ていない**ので、
#:       「本数ごとの中央値」は「その日の中央値」を書き写したものになる。
#:
#: 2日以上に出ている値で比べると、**同じ本数でも日が違えば桁が変わります**:
#:
#:     8本/日   08/19 中央値 1094  ／  09/06 中央値 196    （5.6倍）
#:     10本/日  08/24 中央値 1146  ／  08/31 中央値 121    （9.5倍）
#:     1本/日   08/14 の 1451 から 09/01 の 3 まで（同じ「1本/日」で 480倍）
#:
#: **＝ 本数を軸にしても、日付のぶんが丸ごと混ざったままです。** 04:4x の「刻 と 齢 が
#: 完全に重なっていて分けられない」と同じ形で、分けるには**同じ日に本数だけ変えた実測**が要る
#: （＝ 本数を変えた日を作らないと出ない。いまは 1本/日 に収束しているので、この軸は当分 埋まらない）。
#:
#: だからこの関数は**中央値を1つ出して終わりにせず**、値ごとに「何日ぶんか」を必ず一緒に印字する。
#: **数は毎回 台帳と `data/views.jsonl` から数え直す（写しを持たない）。**
#: **覆る条件**: 同じ本数の日が 3日 以上そろった値が出たら、そこで初めて日付と本数を分けられる
#: （そのときはこの註を数え直して書き換える）。1本/日 の日が増えるのが最短の道。
VIEWS_JSONL = ROOT / "data" / "views.jsonl"


def _old_series(path=None) -> dict[str, list[tuple[float, int, dt.datetime]]]:
    """旧道具が残した測り `data/views.jsonl` を読む（**過去のデータ** ＝ §8 の「使わない道具」ではない）。
    id → [(齢, 再生, 測った刻)]。無ければ空。"""
    path = VIEWS_JSONL if path is None else path
    out: dict[str, list[tuple[float, int, dt.datetime]]] = {}
    if not path.exists():
        return out
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        r = json.loads(line)
        if r.get("hours") is None or r.get("views") is None:
            continue
        at = dt.datetime.fromisoformat(str(r["at"]).replace("Z", "+00:00")).astimezone(JST)
        out.setdefault(r["id"], []).append((float(r["hours"]), int(r["views"]), at))
    return out


def cohorts(rows: list[dict], old_path=None, lo: float = 40.0, hi: float = 60.0):
    """本ごとに（公開日, 公開の刻, 48時間 に最も近い点）を出す。台帳と旧データの両方から。

    返すのは (48h の点が取れた本, 公開日ごとの「その日に出た本の数」)。
    **本数は「48h の点が取れた本」ではなく、刻が分かる本 全部 で数える** ——
    そうしないと軸そのものが狂う（実測 08/24 は 10本/日 だが 48h の点は 2本 しか無い）。
    48h の点が `lo`〜`hi` の外にしか無い本は、比べられないので中央値からは落とす。
    """
    pts: dict[str, list[tuple[float, int, dt.datetime]]] = {}
    for vid, ps in _old_series(old_path).items():
        pts.setdefault(vid, []).extend(ps)
    for vid, ps in series(rows).items():
        pts.setdefault(vid, []).extend(
            (float(p["age_h"]), int(p["views"]), _at(p)) for p in ps if p.get("views") is not None)
    mine = ours(rows)
    per_day_total: dict[dt.date, int] = {}
    out = []
    for vid, ps in pts.items():
        ps.sort()
        pub = min(at - dt.timedelta(hours=h) for h, _, at in ps)
        per_day_total[pub.date()] = per_day_total.get(pub.date(), 0) + 1
        near = [(abs(h - 48.0), h, v) for h, v, _ in ps if lo <= h <= hi]
        if not near:
            continue
        near.sort()
        out.append((pub.date(), pub, vid, near[0][1], near[0][2], vid in mine))
    out.sort()
    return out, per_day_total


def _median(xs: list[int]) -> float:
    xs = sorted(xs)
    n = len(xs)
    return float(xs[n // 2]) if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2


def by_day_count(rows: list[dict], old_path=None) -> list[str]:
    """「その日に何本 出したか」ごとに 48時間 の再生を並べる。**値ごとに「何日ぶんか」を必ず出す。**"""
    co, total = cohorts(rows, old_path)
    if not co:
        return ["（48時間 の点が取れた本が、台帳にも data/views.jsonl にもありません）"]
    per_day: dict[dt.date, list[tuple[int, str, bool]]] = {}
    for day, pub, vid, _h, v, isnew in co:
        per_day.setdefault(day, []).append((v, vid, isnew))
    out = ["== 公開日ごとの 48時間 再生 =="]
    for day in sorted(per_day):
        vs = [v for v, _, _ in per_day[day]]
        n_new = sum(1 for _, _, isnew in per_day[day] if isnew)
        got = f"（48h の点 {len(vs)}本）" if len(vs) != total[day] else ""
        out.append(f"  {day}  {total[day]:2d}本/日{got}  中央値 {_median(vs):7.1f}  範囲 {min(vs)}〜{max(vs)}"
                   f"{f'  ← 新しい作り {n_new}本' if n_new else ''}")
    by_n: dict[int, list[dt.date]] = {}
    for day in per_day:
        by_n.setdefault(total[day], []).append(day)
    out.append("")
    out.append("== 「その日の本数」ごと ——「何日ぶんか」を必ず見ること ==")
    for n in sorted(by_n):
        days = sorted(by_n[n])
        meds = [_median([v for v, _, _ in per_day[d]]) for d in days]
        spread = (f"  同じ本数の日どうしで {max(meds) / max(min(meds), 1):.1f}倍 ちがう"
                  if len(days) > 1 else "")
        out.append(f"  {n:2d}本/日  {len(days)}日ぶん（{', '.join(d.strftime('%m/%d') for d in days)}）"
                   f"  中央値 {' / '.join(f'{m:.0f}' for m in meds)}{spread}")
    multi = [n for n, d in by_n.items() if len(d) > 1]
    out.append("")
    out.append(f"**「本数」の値 {len(by_n)}個 のうち、2日以上に出ているのは {len(multi)}個** —— "
               "残りは 1日 しか無いので、その中央値は「その日の中央値」の書き写しです。"
               "**本数を軸にしても、日付のぶんは分けられません**（studio/trend.py の註。"
               "分けるには、同じ日に本数だけ変えた実測が要る）。")
    return out


def pair_gap(rows: list[dict], at: dt.datetime | None = None) -> dict:
    """**いま撃つ `measure` の点が、2点組に入るか**（2026-09-10 02:2x JST・optimizer・Opus が踏んで足した）。

    返すもの: `last`（前の measured の刻）・`gap_min`・`pairs`（入るか）・`band`（帯の中か）。

    **なぜ要るか —— この回に踏んだ。** 前の周の optimizer が帯（02:00〜10:00 JST）に入るのを
    待って **02:06:25** に測り、その周が終わった **1分後** に親が穴埋めで次の optimizer を立て
    （`data/parent_wakes.jsonl` 17:10:05Z の `patch: true`）、この回は **02:13:29** に測りました。
    **差 7.1分 ＝ `MIN_PAIR_MIN`（10分）より短いので、この組は `_pairs` が丸ごと落とします。**
    ＝ **§7 の「次の帯の回が (i)（20組 を越える）を越えます」は、この測りでは起こりませんでした。**
    `measure` の印字は「記した: 19本」だけなので、**分母が動かなかったことが、どの印字にも出ません**
    （`trend` の「帯の組は 16回 の測りから」を前の回の数と見比べて初めて分かる）。

    **これは §6 `cli.comments_to_show` の 01:4x と同じ形です** —— 数は出るのに、
    その数を動かせたかどうかが出ない。**測る側が「この測りは分母に入りません」と言うこと。**

    **落とし穴**: 組は**本ごと**の連続する2点なので、前の回に測られなかった本（7日 の窓から
    落ちた本・新しく公開した本）の gap はこれより長くなります。ここが見るのは
    **全部の本の最後の measured 行**で、`measure` が毎回 全部を一度に書く形の近似です
    （合わない本が出たら、そのときは本ごとに数えること）。

    **覆る条件**: (1) `MIN_PAIR_MIN` を変えたら、この印字も一緒に動きます（同じ定数を読む）。
    (2) `measure` を本ごとに撃ち分ける形に変えたら、この近似は捨てて `series()` から本ごとに数えること。
    (3) 「入りません」と出た回が 3回 続けてそのまま撃たれていたら、印字では足りない
        ＝ そのときは `measure` の側に門を置く（`--force` を付けない限り撃たない）。
        **1回目は、この印字を足した回自身です**（02:18:42 ＝ 前の測りから 5.1分。
        「10分 経ったはず」と時計を読み違えて撃ち、印字のとおり落ちました）。
        ＝ **印字は正しく出て、それでも撃たれています。** 2回目・3回目を数えること。
    """
    at = at or now_jst()
    pts = [_at(r) for r in rows if r.get("event") == "measured" and r.get("at")]
    last = max(pts) if pts else None
    gap = (at - last).total_seconds() / 60.0 if last else None
    return {"last": last, "gap_min": gap,
            "pairs": gap is None or gap >= MIN_PAIR_MIN,
            "band": DEAD_START <= at.hour < DEAD_END}


#: `over_ledger` の印が出てから、台帳がその数に追いつくまでに要った `measure` の回数の門。
#: **3周**（`over_ledger` の覆る条件 (1)「次の measure が 3周 続けてその数に届かなければ、
#: 高い側は複製ではなく別の口」）。定数はそちらの註が正本で、ここは写しではなく同じ数を持つ口。
OVER_CATCH_ROUNDS = 3


def over_lag(rows: list[dict]) -> dict:
    """`status` が印字した「台帳より高い読み」を、**次の `measure` が拾ったか**を数える。API 0単位。

    **なぜ（2026-09-10 13:2x JST・optimizer・Opus）**: `cli.over_ledger` は 12:4x に
    印字だけを足しました（追加 0単位）。その註には覆る条件が **3つ** 在り、
    **3つ とも「周をまたいで数える」もの**です:

        (1) 印の次の `measure` が **3周 続けて**その数に届かない → 高い側は複製ではなく別の口
        (2) 印が **1度も出ないまま 7本** 過ぎた           → 12:25 の 658 は一度きりの揺れ ＝ 口を外す
        (3) 印が **毎周 出る**                            → 拾う側（`settle_stats` の `reads`）を上げる

    **ところが、印が出たことを残す口が どこにもありませんでした** ——
    `status` は印字して捨て、台帳には 1行 も入らない。
    ＝ 次の回は**前の回の端末の出力を覚えている**しかなく、3つ とも構造として引けません。
    **`flats` の「その 3本 を数える所が、どこにもなかった」（08:4x）と同じ族**で、
    §5 の言う repo でいちばん多い壊れ方（**言っている所と、している所が別**）です。

    → `cmd_status` が印字と同時に `views_over` を1行 書き、ここが数えます（どちらも **追加 0単位**）。

    **数え方**: 印 1件 ＝ 「その刻に、その本の生の読みが `views_live` だった」。
    そのあとの `measured`（同じ本）を順に見て、**`views_live` 以上**を書いた最初の行が「追いついた」。
    追いつくまでの **分** と **measure の回数** を返す。まだなら `catch=None`。

    **返り値の `marks` は判定した実物そのもの**（§5 の教訓の形 4つ目 —— 次の回が列挙で確かめられる）。

    **この数は envelope を動かしません。** 高い読みを `measured` として台帳に入れると、
    **帯の2点組の分母が変わります**（`informative`/`gate_span` は `measured` の刻を数えており、
    その註は「この分母は帯の中で measure を撃った回にしか増えません」と書いている）＝
    **測っている物差しを、測っている最中に取り替えることになります。**
    だから別の event 名で残し、**読むだけ**にしてあります。

    **覆る条件**: (1) `late`（追いつかないまま measure が `OVER_CATCH_ROUNDS` 回 過ぎた印）が
    1件でも出たら、`over_ledger` の (1) が引かれた ＝ そのときは高い読みが**どの順番の読みか**を数えること。
    (2) 印 1件あたりの追いつきが 1回（＝ 次の measure）で 5件 続いたら、遅れは 1周 以内 ＝
    §7 (a) の「平らが読みの側か」は 1周 前の行を見るだけで足り、この口は数えるのをやめてよい。
    (3) 印が 1周 に 1件 以上 出る周が 3周 続いたら `over_ledger` の (3) ＝ `settle_stats` の `reads` を上げる側へ。
    (4) `views_over` に `views_ledger` が入っているのは、印の時点の台帳の最大を**後から数え直さない**ため
    （`recounts` が峰を落とすと、後から数え直した最大は印の時点と違う値になります）。
    """
    marks = [r for r in rows if r.get("event") == "views_over" and r.get("at")]
    ms: list[dict] = []
    for m in marks:
        t = _at(m)
        vid = m.get("id")
        target = m.get("views_live")
        later = [r for r in rows
                 if r.get("event") == "measured" and r.get("id") == vid
                 and r.get("at") and _at(r) > t and isinstance(r.get("views"), int)]
        later.sort(key=_at)
        hit = next((i for i, r in enumerate(later)
                    if isinstance(target, int) and r["views"] >= target), None)
        ms.append({
            "at": m["at"], "id": vid, "views_live": target,
            "views_ledger": m.get("views_ledger"), "over": m.get("over"),
            "age_h": m.get("age_h"),
            "catch_rounds": None if hit is None else hit + 1,
            "catch_min": None if hit is None else
            (_at(later[hit]) - t).total_seconds() / 60.0,
            "measures_since": len(later),
        })
    caught = [m for m in ms if m["catch_rounds"] is not None]
    late = [m for m in ms
            if m["catch_rounds"] is None and m["measures_since"] >= OVER_CATCH_ROUNDS]
    return {"marks": ms, "n": len(ms), "caught": caught, "late": late,
            "gate_rounds": OVER_CATCH_ROUNDS}


def over_lag_line(rows: list[dict]) -> str:
    """`over_lag` を1行にする（`trend` が毎周 印字する ＝ **次の回は覚えていなくてよい**）。"""
    o = over_lag(rows)
    if o["n"] == 0:
        return ("**台帳より高い読みの印（`status` の `views_over`）: 0件** —— "
                "`cli.over_ledger` の覆る条件 (2)（1度も出ないまま 7本 過ぎたら口を外す）の分子は "
                "**まだ 0** です。**この 0 は「起きていない」ではなく「印字だけで捨てていた回は数えていない」** ——"
                "口を足したのは 2026-09-10 13:2x で、それより前の印（12:25 の 658回）は台帳に在りません。")
    cs = [m["catch_rounds"] for m in o["caught"]]
    mins = [m["catch_min"] for m in o["caught"]]
    body = (f"**台帳より高い読みの印: {o['n']}件**（`views_over`）—— "
            f"次の `measure` が拾えた **{len(o['caught'])}件**")
    if cs:
        body += (f"（measure **{min(cs):.0f}〜{max(cs):.0f}回**・"
                 f"**{min(mins):.0f}〜{max(mins):.0f}分**）")
    body += (f"・**{o['gate_rounds']}回 過ぎても届かない {len(o['late'])}件**"
             f"（1件でも出たら `cli.over_ledger` の覆る条件 (1) ＝ 高い側は複製ではなく別の口）。")
    if o["late"]:
        body += "  届かない印: " + "・".join(
            f"{m['id']} 齢{m['age_h']}h 生{m['views_live']} 対 台帳{m['views_ledger']}"
            for m in o["late"])
    return body


#: **`cli.zero_probe_target` の齢の門は、ここに 1つ だけ置く**（`cli` が読む）。
#: 下: 台帳の中で「0回 のまま」を越えた本が 1本 も無い齢（§7「1回目が付いた齢」）。
#: 上: `scripts/zero_start.py` の下敷きの上端（B の初点の最も遅い1本 **77.6h**）を丸めた数。
#: **2026-09-12 19:3x に 48.0 → 78.0**（derivation と覆る条件は `cli.zero_probe_target` の (4)）。
ZERO_PROBE_MIN_H = 3.0
ZERO_PROBE_MAX_H = 78.0


def zero_books_now(rows: list[dict]) -> dict[str, float]:
    """**いま 0回 のままの、こちらの本**（id → いまの齢）。台帳だけ・API 0単位。

    `first_view` の `zero` と同じ本を返しますが、**`flats` を通しません**
    （この行は「門が開いているか」しか要らないので、境目の計算を持ち込まない）。
    """
    mine = ours(rows)
    out: dict[str, float] = {}
    for vid, pts in series(rows).items():
        if vid not in mine or not pts:
            continue
        if max(int(p["views"]) for p in pts) == 0:
            out[vid] = float(pts[-1]["age_h"])
    return out


def zero_probes(rows: list[dict]) -> dict:
    """**公開ずみで 0回 の本の処理の状態**（台帳 `zero_probe`）を数える。API 0単位。

    2026-09-10 15:2x JST・optimizer・Opus。`cli.zero_probe_target` を足した同じ回に、
    その数を**次の回が覚えていなくてよい所**へ回した（`over_lag` と同じ形 ——
    `status` が印字して捨てるだけでは、覆る条件が周をまたいで引けない）。

    **`ok` は「0回 が本物」の意味**（処理は通っている ＝ 出ていない側ではない）。
    **`ok` でない行は、その本の 0回 を「配りが来ていない」と読んではいけない**という印です。

    **`closed` は「門（齢 `ZERO_PROBE_MAX_H`）を越えた 0回 の本」**
    （2026-09-12 19:3x・optimizer・Opus。**この口は齢で黙ります** ——
    黙ったことを言わないと、`ok` の件数が**いまの齢の話**として読まれます。
    実測: 5本目 `2YZ_4FXC-XI` の最後の印は 齢 47.1h で、そのあと 10時間 1件も増えていないのに、
    §7「いまの数」は毎周 この件数を「0回 は本物」の根拠として写していました）。

    **覆る条件**: (1) `bad` が 1件でも出たら `cli.zero_probe_target` の (1) ＝
    `first_view`・`hold` の側にも印を回すこと（0回 を読む前に必ず見る数になる）。
    (2) `books`（撃った本の数）が 7本 を越えて `bad` が 0 なら、この口は外してよい ——
    残るのは `hourly` が撃っている公開ページの側（**API 0単位**・§14 14:3x）。
    (3) `closed` に本が入ったまま、その本を §7 の判定（「形」の 決め (5)）に使う回が来たら、
    **その本について引けるのは「門を出るまでに `ok` だけだった」まで**で、
    覆る条件 (5-1) はもう引けません。**門を出た後の齢で `ok` 以外が要るなら、
    `ZERO_PROBE_MAX_H` を上げるのではなく「0回 のあいだ毎周」へ移すこと**
    （`cli.zero_probe_target` の (4-a)）。
    """
    ps = sorted([r for r in rows if r.get("event") == "zero_probe"], key=_at)
    bad = [r for r in ps if not r.get("ok")]
    zero_now = zero_books_now(rows)
    # **門を越えた 0回 の本**（＝ この本の印はもう増えない）。**齢は台帳の最後の点**。
    closed = [{"id": vid, "age_h": age} for vid, age in sorted(zero_now.items())
              if age > ZERO_PROBE_MAX_H]
    last = ps[-1] if ps else None
    return {"n": len(ps), "books": len({r.get("id") for r in ps}),
            "ok": len(ps) - len(bad), "bad": bad,
            "last": last, "closed": closed}


def zero_probe_line(rows: list[dict]) -> str:
    """`zero_probes` を1行にする（`trend` が毎周 印字する ＝ **次の回は覚えていなくてよい**）。"""
    z = zero_probes(rows)
    if z["n"] == 0:
        return ("**公開ずみで 0回 の本の処理: 印 0件**（`zero_probe`）—— "
                "**この 0 は「落ちた本が無い」ではなく「0回 の本がこの窓に無かった」**です"
                "（`cli.zero_probe_target` の門は 齢 3〜48h の studio の本だけ）。")
    body = (f"**公開ずみで 0回 の本の処理: 印 {z['n']}件・{z['books']}本** —— "
            f"**`ok` {z['ok']}件 / `ok` でない {len(z['bad'])}件**（`zero_probe`・1周 1単位）。")
    if z["bad"]:
        body += ("  !! " + "・".join(f"{r.get('id')} upload {r.get('upload')}／"
                                     f"processing {r.get('processing')}／失敗 {r.get('failure')}"
                                     for r in z["bad"])
                 + " ＝ **その 0回 を「配りが来ていない」と読まないこと**"
                   "（`cli.zero_probe_target` の覆る条件 (1)）。")
    else:
        body += ("  **`ok` だけ ＝ 0回 は本物**（出ていない側ではない）。"
                 f"**7本 過ぎて 1度も `ok` 以外が出なければ、この口は外してよい**（いま {z['books']}本）。")
    if z["closed"]:
        body += ("  !! **門（齢 " + f"{ZERO_PROBE_MAX_H:.0f}h）を越えた 0回 の本 {len(z['closed'])}本**: "
                 + "・".join(f"{c['id']} 齢 {c['age_h']:.1f}h" for c in z["closed"])
                 + " ＝ **この本の印はもう増えません**")
        if z["last"]:
            body += f"（最後の印は {_at(z['last']).strftime('%m/%d %H:%M')}）"
        body += ("。**上の件数を「いまの齢でも `ok`」と読まないこと**"
                 "（`zero_probes` の覆る条件 (3)）。")
    return body


VIEWS_ABSENT_SINCE = "2026-09-10T14:20:00+09:00"
# `yt.views_of` が「`viewCount` の欄が無い」と「0回」を分け始めた刻（台帳 `views_absent`）。
# **これより前の `measured` は、欄が無くても 0回 として書かれています** ＝ 門の分母に入れない。


def views_absent(rows: list[dict]) -> dict:
    """**`viewCount` の欄が無い読み**（台帳 `measured` の `views_absent`）を数える。API 0単位。

    **なぜ（2026-09-10 21:0x JST・optimizer・Opus）**: §7 (j) は「**いま 0件**。
    1度でも立ったら、その本の台帳の 0回 を『配りが来ていない』と読まないこと。
    **7本 過ぎて 1度も立たなければ、この口は外してよい**」と書いていますが、
    **その 0件 も 7本 も、どこも数えていませんでした** —— `cli.cmd_status` が
    その回の読みに印を出すだけで、**台帳に積んだ側を周をまたいで読む口が無い**。
    ＝ 次の回は手で `grep` するしかなく、(m) が 09/10 16:4x に踏んだのと同じ形です
    （`channel_video_delta` の註 ＝「覆る条件が、どこも数えていない条件だった」）。

    **`n` は行の数・`books` は本の数**（同じ本が毎周 立ちます ＝ 行で本を数えないこと）。

    **`since_books` は門 7本 の分母**: **この口が在ってから測った、こちらの本**の数。
    `views_absent` は **False のときは書かれません**（`cli` が truthy のときだけ `extra` に足す）ので、
    「欄が在った」と「この口より前の読み」を行だけでは分けられません ＝ **刻で分けます**
    （`VIEWS_ABSENT_SINCE`）。旧作りの本は外します（§7 の「N本目」はこちらの本の数）。

    **覆る条件**: (1) `n` が **1件でも立ったら**、その本の 0回 を `first_view`・`hold`・§7 (c) の
    数から外すこと（`yt.views_of` の覆る条件 (1) と同じ ＝ ここはその**数える口**）。
    (2) `since_books` が **7本** を越えて `n` が 0 なら、この口は外してよい。
    (3) `views_absent` が False でも書かれるように `cli` を変えたら、`since_books` は
    刻ではなく**欄の有無**で数えること（そのほうが正確 ＝ この定数は消える）。
    """
    since = dt.datetime.fromisoformat(VIEWS_ABSENT_SINCE)
    marks = [r for r in rows
             if r.get("event") == "measured" and r.get("views_absent")]
    mine = ours(rows)
    seen = {r["id"] for r in rows
            if r.get("event") == "measured" and r.get("id") in mine
            and _at(r) >= since}
    return {"n": len(marks), "books": sorted({r["id"] for r in marks}),
            "since_books": len(seen), "marks": marks}


def views_absent_line(rows: list[dict]) -> str:
    """`views_absent` を1行にする（`trend` が毎周 印字 ＝ **次の回は覚えていなくてよい**）。"""
    a = views_absent(rows)
    if a["n"] == 0:
        return ("**`viewCount` の欄が無い読み: 0件**（台帳 `views_absent`・`yt.views_of`）—— "
                "**1度でも立ったら、その本の台帳の 0回 を「配りが来ていない」と読まないこと**"
                f"（覆る条件 (1)）。**この口が在ってから測った、こちらの本 {a['since_books']}本**"
                "（門 **7本** ＝ 7本 過ぎて 1度も立たなければ、この口は外してよい）。")
    return (f"**`viewCount` の欄が無い読み: {a['n']}件・{len(a['books'])}本** —— "
            + "・".join(a["books"])
            + " ＝ **その本の台帳の 0回 を「配りが来ていない」と読まないこと**"
              "（`yt.views_of` の覆る条件 (1)）。"
              "**`first_view`・`hold`・§7 (c) は、この本の 0 を数から外すこと。**")


#: §7 末尾「1日1本」の覆る条件の門（2026-09-12 20:3x・optimizer・Opus が数える口を足した）。
#: 「**新しい作りで 7本 続けて 500回 を越えたら**、2本/日 を 3日 試して 1本あたりが落ちないか見る」。
DAILY_VIEWS_GATE = 500
DAILY_RUN_NEED = 7


def views_streak(rows: list[dict]) -> dict:
    """**新しいほうから、いまの再生が 500回 を越えている本が何本 続いているか**（包絡・API 0単位）。

    **なぜ（2026-09-12 20:3x JST・optimizer・Opus）**: §7 末尾の「1日1本」は 09/05 から
    「**新しい作りで 7本 続けて 500回 を越えたら** 2本/日 を 3日 試す」と書いていますが、
    **その連を数える物が 1つも在りませんでした** —— `late_run`・`blind_run`・
    `reporting_empty_run`・`outside_runs` と**同じ族の 5例目**（「N本 続いたら」と
    覆る条件に書いて、N を数える口が無い）。しかも この条件が引かれたら動くのは
    **1日の本数そのもの**（§5 の回り方・親の周・枠の配り が全部 掛かる側）です。

    **越えた側は言い切れます・越えていない側は言い切れません。** 並びは包絡（`envelope`）なので
    再生は**下からしか動きません** ＝ 1度 500回 を越えた本は越えたまま。逆に いま 500回 以下の本は、
    **まだ伸びていれば**あとで越え得ます ＝ そこで連を「切れた」と読むと、連は**永久に短く出ます**。
    だから 2つ 返します:

    * ``run``          —— いま 越えている本だけの連（**引く側が読む数**）
    * ``run_if_growing`` —— 越えていない本でも **`growing` なら続きうる**として数えた連
      （＝ **いま在る本だけで門に届く目**があるか。`growing` の規則は `hold` と同じ
      ＝ 齢 48h 未満 か、最後の伸びから `flats` の境目より短い）

    **`run_if_growing` が門に届かないなら、この周に門が引かれる目は在りません** ——
    足りないぶんは**新しい本でしか埋まりません**（``short`` ＝ 門 − `run_if_growing`）。

    **0回 の本も 1本 として数えます**（`hold` は分母が作れず落としますが、ここは
    「500回 を越えたか」しか訊かないので落とす理由が在りません ＝ §7「形」の 決め (5) と同じ側）。

    **覆る条件**: (1) `run` が門に届いたら、**2本/日 を試すかの判定は `hourly` とオーナー**
    （§5 ＝ 1日の本数は台本と枠の両方に掛かる）。optimizer はこの数を並べるまで。
    (2) **「500回」の刻が決まっていません** —— この口は**いまの再生**で読みます
    （`hold` の分母と同じ ＝ 伸び中の本では下端）。「48h の点で」に変えるなら、
    `hold` の 覆る条件 (2)（48h を越えて確定した本が 5本 そろったら分母を移す）と
    **同じ回に一緒に**変えること（**分母を 2か所 に置かないこと**）。
    (3) 1日1本 をやめた回（2本/日 を試した 3日 など）は、**「続けて」の単位が日ではなく本**の
    ままでよいか、ここで決め直すこと —— 同じ日の 2本 は配りを分け合うので、
    連の 1本 として数えると門が甘くなります。
    """
    mine = ours(rows)
    thresh = float(flats(rows)["thresh_h"])
    books: list[dict] = []
    for vid, pts in sorted(series(rows).items(), key=lambda kv: published_at(kv[1])):
        if vid not in mine or not pts:
            continue
        env = envelope(pts)
        last_age = float(pts[-1]["age_h"])
        views = env[-1] or 0
        gap = last_rise_gap_h(pts, env)
        books.append({
            "id": vid,
            "day": published_at(pts).strftime("%m/%d"),
            "age_h": last_age,
            "views": views,
            "over": views > DAILY_VIEWS_GATE,
            # **`hold` と同じ規則**（分母を 2か所 に置かないため）。
            "growing": last_age < 48.0 or gap < thresh,
        })

    def count(allow_growing: bool) -> int:
        n = 0
        for b in reversed(books):
            if b["over"] or (allow_growing and b["growing"]):
                n += 1
                continue
            break
        return n

    run = count(False)
    maybe = count(True)
    broke = books[-(run + 1)] if len(books) > run else None
    return {"books": books, "n": len(books), "run": run, "run_if_growing": maybe,
            "gate": DAILY_VIEWS_GATE, "need": DAILY_RUN_NEED,
            "drawn": run >= DAILY_RUN_NEED,
            "short": max(0, DAILY_RUN_NEED - maybe),
            "broke": broke}


def views_streak_line(rows: list[dict]) -> str:
    """`views_streak` を1行にする（`trend` が毎周 印字 ＝ **次の回は覚えていなくてよい**）。"""
    s = views_streak(rows)
    if not s["n"]:
        return (f"**{DAILY_VIEWS_GATE}回 の連: 本 0本**（`trend.views_streak`）—— "
                "§7 末尾「1日1本」の覆る条件を数える口。")
    body = (f"**{s['gate']}回 を越えた連（新しいほうから）: {s['run']}本**"
            f"（門 **{s['need']}本** ＝ §7 末尾「1日1本」の覆る条件・`trend.views_streak`・"
            f"台帳だけ・API 0単位）—— こちらの本 {s['n']}本 中。")
    if s["broke"]:
        b = s["broke"]
        body += (f"  連を切っているのは {b['id']}（{b['day']}・齢 {b['age_h']:.1f}h・{b['views']}回"
                 + ("・**まだ伸びている ＝ あとで越え得る**" if b["growing"] else "・確定")
                 + "）。")
    body += (f"  **伸びている本が全部 越えたとしても {s['run_if_growing']}本**"
             f"（門まで あと **{s['short']}本** ＝ "
             + ("**この周に門が引かれる目は在りません。足りないぶんは新しい本でしか埋まりません**"
                if s["short"] else "**いま在る本だけで届き得ます**")
             + "）。")
    if s["drawn"]:
        body += ("  !! **門に届きました** ＝ **2本/日 を 3日 試すかの判定は `hourly` とオーナー**"
                 "（§5・1日の本数は台本と枠の両方に掛かる）。")
    body += ("  **越えた側は言い切れ、越えていない側は言い切れません**"
             "（包絡 ＝ 伸び中の本の再生は下端・`views_streak` の註）。")
    return body

#: §4 (0-c) の「その本の 1行」の形（2026-09-12 19:4x・hourly・Opus が決めた）。
#: 例: **`(0-c) 公表ページ: 0 ・改正: 0`**  ——値は「0」か「出た」。
_OUTSIDE_RE = re.compile(r"\(0-c\)\s*公表ページ\s*[:：]\s*(0|出た)\s*[・,]\s*改正\s*[:：]\s*(0|出た)")
#: §9 以降が本の節（§0〜§8 は手順）。
_BOOK_SEC_RE = re.compile(r"^## (\d+)\.\s*(.*)$")
#: §4 (0-c) の覆る条件 (1) の門（**本**で数える。引きの回数ではない）。
OUTSIDE_RUN_GATE = 3


def outside_checks(method: "Path | None" = None) -> list[dict]:
    """**§4 (0-c) の「外を1回 引く」の結果を、本ごとに 1行 で拾う**（`docs/METHOD.md` を読むだけ・API 0単位）。

    **なぜ（2026-09-12 20:0x JST・optimizer・Opus。`hourly` が §16 の申し送り (8) で渡した口）**:
    §4 (0-c) の覆る条件 (1) は「**3本 続けて**外で何も出なければ、公表ページ1つの照合に縮める」ですが、
    **その 3本 を数える物が在りませんでした** —— `blind_run`・`reporting_empty_run`・`late_run` と同じ族
    （「N本 続いたら」と書いて N を数える口が無い）の **4例目**。
    それまで数えられていたのは**引きの回数**で、09/09 の本の 3回 が「2本 ＋ 1本目の 0」と書かれています
    （**全部 同じ 1本**）＝ **単位が違うので、連が復元できません。**

    **材料は本の節の 1行**（`(0-c) 公表ページ: 0 ・改正: 0`）。**行の無い本は数えません**
    —— §14・§15 には行が 1つも無く、**そこは復元せずに §16 から数え始めます**（§4 19:4x の決め）。

    **前半（公表ページ）と後半（改正）は別に数えます**（同 決め）——
    09/13 の本は公表ページを 4回 引きながら、改正の側は 1度も引かれていませんでした
    ＝ **前半が済むと後半も済んだことになる**のが、この抜けの口です。

    返すのは節の番号の順（＝ 本の順）の並び: ``{"sec", "title", "page", "reform"}``
    （`page` / `reform` は ``"0"``（出なかった）か ``"出た"``）。
    """
    path = Path(method) if method is not None else ROOT / "docs" / "METHOD.md"
    if not path.is_file():
        return []
    sec = None
    title = ""
    out: list[dict] = []
    seen: set[int] = set()
    for line in path.read_text(encoding="utf-8").split("\n"):
        m = _BOOK_SEC_RE.match(line)
        if m:
            sec, title = int(m.group(1)), m.group(2)
            continue
        if sec is None or sec < 9 or sec in seen:
            continue
        g = _OUTSIDE_RE.search(line)
        if g:
            seen.add(sec)
            out.append({"sec": sec, "title": title[:40],
                        "page": g.group(1), "reform": g.group(2)})
    return sorted(out, key=lambda r: r["sec"])


def outside_runs(method: "Path | None" = None) -> dict:
    """`outside_checks` から、**新しいほうから「0」が続いている本の数**を側ごとに数える。

    **`page` / `reform` は別の連です**（§4 19:4x）。門は `OUTSIDE_RUN_GATE`（**3本**）。

    **覆る条件**: (1) 連が門に届いたのに縮めた側で誤りが出たら、単位は本ではなく
    **制度の種類**（その本が触れた制度の数）＝ そのときは 1本 1行 では足りません。
    (2) 本の節に 1行 を書かない回が **2本** 続いたら、置き場が悪い ＝
    台帳（`cli` の `outside_checked`）へ移すこと（**材料を 2か所 に置かないこと**）。
    (3) `hourly` がこの口を使わずに手で連を数えた回が出たら、印字が読まれていない ＝
    §4 の行から、この関数名で指し直すこと。
    """
    rows = outside_checks(method)
    def run(key: str) -> int:
        n = 0
        for r in reversed(rows):
            if r[key] != "0":
                break
            n += 1
        return n
    return {"rows": rows, "books": len(rows),
            "page_run": run("page"), "reform_run": run("reform"),
            "gate": OUTSIDE_RUN_GATE}


def outside_line(method: "Path | None" = None) -> str:
    """`outside_runs` を1行にする（`trend` が毎周 印字 ＝ **次の回は覚えていなくてよい**）。"""
    o = outside_runs(method)
    if not o["books"]:
        return ("**(0-c) の外の引き: 本の節に 1行 を持つ本 0本**（`trend.outside_checks`）—— "
                "**この 0 は「引いていない」ではなく「記録の形が無い」**です"
                "（形は §4 (0-c) 19:4x ＝ `(0-c) 公表ページ: 0 ・改正: 0`）。")
    last = o["rows"][-1]
    body = (f"**(0-c) の外の引き: 記録の在る本 {o['books']}本**（`trend.outside_runs`・"
            f"`docs/METHOD.md` を読むだけ・API 0単位）—— "
            f"**公表ページ 0 が {o['page_run']}本 続き**・**改正 0 が {o['reform_run']}本**"
            f"（門 {o['gate']}本 ＝ §4 (0-c) の覆る条件 (1)。**側は別に数えます**）。")
    if o["page_run"] >= o["gate"] or o["reform_run"] >= o["gate"]:
        side = "公表ページ" if o["page_run"] >= o["gate"] else "改正"
        body += (f"  !! **{side} の側は門に届きました** ＝ "
                 "**縮めてよいかの判定は `hourly`**（§5・台本を持つ側）。")
    body += (f"  直近は §{last['sec']}（公表ページ {last['page']}・改正 {last['reform']}）。"
             "**行の無い本は数えません**（連は復元しない ＝ §4 19:4x の決め）。")
    return body


#: `hear.tail_voice` の覆る条件（**`分けられない` が 3本 続けて出るなら、閾（0.2／0.4秒）が
#: 音の実物と合っていない ＝ 秒ではなく「欠けた語のモーラ数」から要る秒を出す側へ移すこと**）の連の門。
#: **`hear.voice_verdict` の閾は頭と末尾で同じ**なので、`voice` と `head_voice` は同じ連に入れます。
VOICE_UNSURE_NEED = 3


def voice_runs(rows: list[dict], need: int = VOICE_UNSURE_NEED) -> dict:
    """**音の側の答え（`hear.tail_voice` / `head_voice`）の `分けられない` が、本で何本 続いているか**
    （2026-09-13 01:5x JST・optimizer・Opus が足した。台帳の `heard` の行だけ・**API 0単位**）。

    **なぜ要るか**: `hear.tail_voice` の覆る条件は「**`分けられない` が 3本 続けて出るなら、
    閾（0.2／0.4秒）が音の実物と合っていない**」と書いてありますが、**その連を数える口が
    在りませんでした** —— `late_run`・`blind_run`・`reporting_empty_run`・`outside_runs`・
    `views_streak`・`rev7_run`・`feature_cohorts`・`report_vs_ledger` の
    `censored` と**同じ族の 10例目**（9例目 の `span_narrow_run` は 09/13 02:5x に畳みました ——
    数えた連が門の答えを動かさなかった側・`gate_span` の註）（「N本 続いたら」と覆る条件に書いて、N を数える口が無い）。
    しかも `cli.cmd_hear` は `voice` / `head_voice` の答えを
    「次の回が数えるため」と註を付けて台帳へ**毎回 積んでいました** ＝
    **数は 09/09 から在り、読む物だけが無かった**側です（`meta_fixes` と同じ形）。

    **単位は「本」で、周でも聞き直しでもありません。** 同じ本を 1周 に 5回 聞き直す回が在り
    （実測 09/12 の本 ＝ `heard` 10行）、行で数えると連は**引かれる側へ甘く**なります。
    **音の側が 1度も答えなかった本は、連を伸ばしも切りもしません**（`tail_voice` は
    末尾に差の出たコマでしか撃たれないので、差の無い本は「在る／無い」を言っていない ＝
    畳んだ `span_narrow_run` が「測っていない周」を数えなかったのと同じ向き）。

    本の並びは **`id` の日付**（`2026-09-14-...`）で読みます —— 台帳の刻ではありません
    （前の本を後から聞き直す周が在るので、刻で並べると本の順が入れ替わります）。

    返すもの: ``run``・``need``・``gate``（= `need`）・``drawn``・``spoke``（音の側が答えた本の数）・
    ``silent``（答えなかった本の数）・``books``（新しい順の本ごとの内訳。**判定した実物を返り値に残す**
    ＝ §5 教訓の形 4つ目）。

    **覆る条件**: (1) `drawn` が立ったら、直すのは閾の数ではなく**引き方**です
    （`hear.tail_voice` の註 ＝ 欠けた語のモーラ数から要る秒を出す側へ）。
    **閾を 2か所 に置かないこと** —— 0.2／0.4 は `hear.VOICE_GAP_ABSENT` / `VOICE_GAP_PRESENT` の 1か所。
    (2) 「当たったか」（`音は在る` と出たコマが耳で本当に在ったか）は、**この口では数えられません**
    —— 台帳に在るのは答えだけで、当たり外れは本の節に在ります。
    `tail_voice` のもう 1つ の覆る条件（**3本 続けて当たったら `tail_probe` の印字をやめて寄せる**）を
    数えるには、**その判定を台帳へ積む口が先に要ります**（積むのは `hourly` の側 ＝ 本を出す回）。
    (3) 1本 の中で `分けられない` が 1つ でも出れば、その本は「出た」に数えます
    （コマの数で重みを付けない）—— 重みを付ける形にするなら、この註と検査を一緒に書き直すこと。
    """
    books: dict[str, dict] = {}
    for r in rows:
        if r.get("event") != "heard":
            continue
        bid = str(r.get("id") or "")
        b = books.setdefault(bid, {"id": bid, "n": 0, "present": 0, "absent": 0, "unsure": 0})
        for field in ("voice", "head_voice"):
            for v in (r.get(field) or {}).values():
                key = {"音は在る": "present", "音が無い": "absent",
                       "分けられない": "unsure"}.get(str(v))
                if key is None:
                    continue
                b["n"] += 1
                b[key] += 1
    order = sorted(books.values(), key=lambda b: str(b["id"]), reverse=True)
    spoke = [b for b in order if b["n"]]
    run = 0
    for b in spoke:                      # **答えた本だけ**を新しいほうから数える（覆る条件 (3)）
        if b["unsure"]:
            run += 1
        else:
            break
    return {"run": run, "need": need, "gate": need, "drawn": run >= need,
            "spoke": len(spoke), "silent": len(order) - len(spoke),
            "books": order, "unit": "本"}


def voice_line(rows: list[dict]) -> str:
    """`voice_runs` を1行にする（`trend` が毎周 印字 ＝ **手で数えないこと**・註は `voice_runs`）。"""
    r = voice_runs(rows)
    if not r["spoke"]:
        return ("**音の側の答え（`hear.tail_voice` / `head_voice`）: 答えた本 0本**"
                "（`trend.voice_runs`・台帳だけ・API 0単位）—— **この 0 は「音が無い」ではなく"
                "「末尾・頭に差の出たコマが 1つ も無かった」**です。")
    shown = [b for b in r["books"] if b["n"]][:int(r["run"]) + 1]
    body = (f"**音の側の答え**（`hear.tail_voice` / `head_voice` の覆る条件・`trend.voice_runs`・"
            f"台帳だけ・**API 0単位**）: **`分けられない` の連 {r['run']}/{r['need']}本**"
            f"（**単位は「本」＝ 周でも聞き直しでもありません** —— 同じ本を 1周 に 5回 聞き直す回が在り、"
            f"行で数えると連が甘くなります・同 註）。"
            f"**音の側が 1度も答えなかった本 {r['silent']}本 は、連を伸ばしも切りもしません**"
            f"（答えた本 {r['spoke']}本）。")
    body += ("  新しいほうから: "
             + "・".join(f"{b['id'][:10]} 在る{b['present']}／無い{b['absent']}／"
                         f"分けられない{b['unsure']}" for b in shown) + "。")
    if r["drawn"]:
        body += ("  !! **門に届きました ＝ 閾（0.2／0.4秒）が音の実物と合っていません** —— "
                 "**直すのは閾の数ではなく引き方**（欠けた語のモーラ数から要る秒を出す側へ・"
                 "`hear.tail_voice` の註の覆る条件）。")
    return body


#: §3 の 7-b（板 `board`）／7-c（札「しくみ」）の覆る条件の門（**本**で数える）。
FEATURE_RUN_GATE = 3
#: 型ごとの 48h を挟むときの齢（§3 の両方の覆る条件が「48h」と書いている）。
FEATURE_AGE = 48.0


def views_at_age(pts: list[dict], env: list[int | None], h: float = FEATURE_AGE) -> dict:
    """齢 `h` の再生を **挟み**（lo／hi）で返す（包絡・API 0単位）。

    **なぜ挟みか**: 測りは 1時間 ごとなので、**齢 48.0h ちょうどの点を持つ本は ほとんどありません**
    （実物 7本 のうち **0本**）。§7「形」の行が `536〜613` と書いているのは この挟みで、
    **点を 1つ 選ぶと、選び方しだいで判定が動きます**（実物 3本目 は 536 と 613 ＝ 1.14倍）。

    返り: ``reached``（h を越えた点が在るか）・``lo``（h 以下の最後の包絡）・
    ``hi``（h を越えた最初の包絡）・``exact``（lo と hi が同じ ＝ 挟みが閉じた）。
    **`reached` が偽の本は、まだ答えを持ちません**（`lo` は下端としてしか読めない）。
    """
    below = [v for p, v in zip(pts, env) if float(p["age_h"]) <= h]
    above = [v for p, v in zip(pts, env) if float(p["age_h"]) > h]
    lo = below[-1] if below else None
    hi = above[0] if above else None
    return {"reached": hi is not None, "lo": lo, "hi": hi,
            "exact": hi is not None and lo == hi}


def _has_board(d: dict) -> bool:
    return any(s.get("board") for s in d.get("segments", []))


def _has_shikumi(d: dict) -> bool:
    return any(s.get("tag") == "しくみ" for s in d.get("segments", []))


#: 台本の「型」—— (名, §3 のどの行に覆る条件が在るか, 台本から引く述語)。
#: **足すのは §3 に覆る条件が在る型だけ** ——決めの無い数を印字しても、次の回が読む所が増えるだけです。
FEATURES: tuple = (
    ("板", "§3 7-b", _has_board),
    ("しくみ", "§3 7-c", _has_shikumi),
)


def script_features(scripts: "Path | None" = None) -> dict[str, dict]:
    """台本ごとの型の印（`data/studio/scripts/*.json` を読むだけ・**API 0単位**）。"""
    from .script import SCRIPTS
    base = Path(scripts) if scripts is not None else SCRIPTS
    out: dict[str, dict] = {}
    for p in sorted(base.glob("*.json")):
        try:
            d = json.loads(p.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            continue
        out[p.stem] = {name: bool(fn(d)) for name, _sec, fn in FEATURES}
    return out


def _script_video_ids(rows: list[dict]) -> dict[str, str]:
    """台本の id → 上げた video_id（**最後の `scheduled` 行**。差し替えた本は新しいほう）。"""
    out: dict[str, str] = {}
    for r in rows:
        if r.get("event") == "scheduled" and r.get("id") and r.get("video_id"):
            out[str(r["id"])] = str(r["video_id"])
    return out


def _median_bracket(bs: list[dict]) -> dict:
    """挟みの束の中央値を、**挟みのまま**返す（lo の中央値／hi の中央値）。"""
    return {"lo": statistics.median(sorted(b["lo"] for b in bs)),
            "hi": statistics.median(sorted(b["hi"] for b in bs)),
            "exact": False, "n": len(bs)}


def feature_cohorts(rows: list[dict], scripts: "Path | None" = None) -> list[dict]:
    """**§3 の 7-b／7-c の「N本 の 48h」を数える口**（台本 ＋ 台帳だけ・**API 0単位**）。

    **なぜ（2026-09-12 22:2x JST・optimizer・Opus）**: §3 の 7-b（板 `board`）と 7-c（札「しくみ」）は
    どちらも「**その型の本 3本 の 48h が、持たない直近 3本 の中位を下回ったら** 絞るか外す」と
    書いていますが、**その 3本 を数える物が 1つも在りませんでした** ——
    `late_run`・`blind_run`・`reporting_empty_run`・`outside_runs`・`views_streak`・`rev7_run` と
    **同じ族の 7例目・8例目**（「N本 続いたら」と覆る条件に書いて、N を数える口が無い）。
    しかも §16 の覆る条件 (1) は「**次の1本で 3本 そろう**」と書いており、
    **そろったかを数える手が、書いた回の頭の中にしかありませんでした。**

    **この口が答えるのは 3つ だけ**:

    * その型を持つ本が **何本** 在り、うち **48h に着いた本が何本** か（＝ 門までの残り）
    * 比べる相手（**その型を持たない、48h に着いた直近 3本**）が誰で、いくつか
    * 門に届いた回に、**中位が下回ったか**（**挟みが重なったら「分けられない」** ＝ 言い切らない）

    **48h は挟みで読みます**（`views_at_age`）—— 実物 7本 に 齢 48.0h ちょうどの点は **0本**で、
    点を 1つ 選ぶ形にすると 3本目 は 536 と 613 の**どちらにもできます**（1.14倍）。
    ＝ **中位も挟みのまま比べ、重なったら「分けられない」を返します。**

    **0回 の本も 1本 として数えます**（§7「形」の 決め (5) と同じ側 ——
    外す口が道具に無いのに外すと、読む側が都合で選べます）。

    **判定は `hourly`**（§5 ＝ 形を変えるかは台本を持つ側・optimizer はこの数を並べるまで）。

    **覆る条件**: (1) 門に届いた回に挟みが重なったら（``verdict == "分けられない"``）、
    **そこで判定を下さないこと** —— 要るのは齢 48h ちょうどの点で、いまの測りの間隔（約 55分）では
    取れません。取りにいくなら `measure` の刻を 48h に合わせる側で、**その値段は 1周ぶん**です。
    (2) **型は台本から引いています**（`board` が 1コマでも在るか・`tag == "しくみ"` が 1コマでも在るか）。
    §3 が「板は 3行 に絞る」「しくみ は 1コマ に絞る」と**量**を決め直したら、**ここの述語も一緒に直すこと**
    （いまは「在るか」だけを見ており、量は見ていません ＝ 絞ったあとの本も「持つ」側に入ります）。
    (3) 比べる相手は「持たない、48h に着いた直近 3本」に固定しています —— その 3本 が同じ週に
    入っているうちは、日の良し悪しと分けられません（§7「形」の 決め (2)）。
    (4) 2つ の型は**同じ本に同時に乗ります**（09/12 の本は 板 と しくみ の両方）＝
    **どちらが効いたかは、この口では分けられません**。分けるには片方だけの本が要ります。
    """
    feats = script_features(scripts)
    vids = _script_video_ids(rows)
    mine = ours(rows)
    ser = series(rows)
    books: list[dict] = []
    for sid in sorted(feats):
        vid = vids.get(sid)
        pts = ser.get(vid or "", [])
        at48: dict = {"reached": False, "lo": None, "hi": None, "exact": False}
        day = sid[:10]
        published = bool(vid and vid in mine and pts)
        if published:
            at48 = views_at_age(pts, envelope(pts))
            day = published_at(pts).strftime("%Y-%m-%d")
        books.append({"sid": sid, "id": vid, "day": day, "published": published,
                      "at48": at48, **{name: feats[sid][name] for name, _s, _f in FEATURES}})
    out: list[dict] = []
    for name, sec, _fn in FEATURES:
        has = [b for b in books if b[name]]
        ready = [b for b in has if b["at48"]["reached"]]
        base = [b for b in books if not b[name] and b["at48"]["reached"]][-FEATURE_RUN_GATE:]
        row: dict = {
            "name": name, "sec": sec, "gate": FEATURE_RUN_GATE,
            "books": has, "n": len(has), "ready": ready, "n_ready": len(ready),
            "short": max(0, FEATURE_RUN_GATE - len(ready)),
            "base": base, "verdict": "まだ", "mid": None, "base_mid": None,
        }
        if len(ready) >= FEATURE_RUN_GATE and len(base) >= FEATURE_RUN_GATE:
            mid = _median_bracket([b["at48"] for b in ready[-FEATURE_RUN_GATE:]])
            bmid = _median_bracket([b["at48"] for b in base])
            row["mid"], row["base_mid"] = mid, bmid
            if mid["hi"] < bmid["lo"]:
                row["verdict"] = "下回りました"
            elif mid["lo"] > bmid["hi"]:
                row["verdict"] = "下回りません"
            else:
                row["verdict"] = "分けられない"
        out.append(row)
    return out


def _bracket_words(b: dict) -> str:
    if b["lo"] is None:
        return "—"
    if b["lo"] == b["hi"]:
        return f"{b['lo']:g}回"
    return f"{b['lo']:g}〜{b['hi']:g}回"


def feature_line(rows: list[dict], scripts: "Path | None" = None) -> str:
    """`feature_cohorts` を1行にする（`trend` が毎周 印字 ＝ **次の回は覚えていなくてよい**）。"""
    parts: list[str] = []
    for c in feature_cohorts(rows, scripts):
        body = (f"**{c['name']}（{c['sec']}）: {c['n']}本"
                f"（48h に着いた {c['n_ready']}本／門 {c['gate']}本）**")
        if c["books"]:
            body += "＝ " + "・".join(
                f"{b['day'][5:]}{'' if b['published'] else '（未公開）'} "
                + (_bracket_words(b["at48"]) if b["at48"]["reached"] else "まだ")
                for b in c["books"])
        if c["base"]:
            bm = _median_bracket([b["at48"] for b in c["base"]])
            body += (f"　対 **持たない直近 {len(c['base'])}本** "
                     + "・".join(f"{b['day'][5:]} {_bracket_words(b['at48'])}" for b in c["base"])
                     + f"（中位 {_bracket_words(bm)}）")
        if c["verdict"] == "まだ":
            body += f"　→ **まだ引けません**（48h に着く本が あと {c['short']}本）"
        elif c["verdict"] == "分けられない":
            body += "　→ !! **門に届きましたが、挟みが重なって分けられません**（覆る条件 (1)）"
        else:
            body += (f"　→ !! **中位（{_bracket_words(c['mid'])}）は"
                     f"{c['verdict']}**（**判定は `hourly`**・§5）")
        parts.append(body)
    return ("**台本の型ごとの 48h**（§3 7-b／7-c の覆る条件を数える口・"
            "`trend.feature_cohorts`・台本と台帳だけ・**API 0単位**）: "
            + "　／　".join(parts)
            + "　**48h は挟みで読みます**（齢 48.0h ちょうどの点を持つ本は 0本 ＝ "
              "点を 1つ 選ぶと判定が動く・`views_at_age` の註）。"
              "**2つ の型は同じ本に乗るので、どちらが効いたかは分けられません**（覆る条件 (4)）。")


def image_orders(rows: list[dict], orders: "Path | None" = None,
                 images: "Path | None" = None) -> dict:
    """**画像の注文が届いたか**と、**届いた絵が本に載ったか**を数える
    （2026-09-11 02:0x・optimizer・Opus。**API 0単位**・ファイルを見るだけ）。

    注文は `data/image_orders/<id>-bg.json`、焼き上がりは `assets/images/<id>-bg.{jpg,png}`
    （約束は `docs/IMAGE_ORDERS.md`）。**届いた数だけでは足りません** ——
    `cmd_order_image` は注文を置くとき「届いたら build し直す」と印字しますが、
    **そのあと誰も見ていませんでした**（この回に踏んだ形）。

    **実測 2026-09-11 01:3x（この口を足した回）**: 7本目 `2026-09-12-taishoku-koujo-70man` は
    **00:32・00:39 の 2回 とも `image=False` で焼かれ**、絵は **01:34 に届いて**います
    （前の回は 00:5x に終わっており、§15 の (3)「12コマ とも目で見た」は
    **単色の背景の sheet.png を見た**ことになる ＝ **出る本と違う絵を目視していた**）。
    台帳の 5本 を並べると、**3本 が同じ形で始まり**（`image=False` の build が先に在る）、
    どれも**あとの周が別の用で焼き直したから**絵が載っています ＝ **偶然に頼っていました。**

    返り値の `restale` は「**絵は在るのに、いちばん新しい build が `image=False`**」の本
    （＝ その本の mp4 と sheet.png は単色のまま）。**`work/` は worktree ごとなので、
    予約する回は必ず焼き直します** —— だから危ないのは mp4 ではなく、
    **その本について「目で見た」と書かれた記録のほう**です。

    **覆る条件**: (1) `restale` に載った本が、そのあと 3本 続けて「焼き直す前に予約された」
    ことが台帳から出なければ、この口は印字だけでよい（門にしない）。
    (2) `slides` が背景を build 時ではなく予約時に貼るようになったら、この数は意味を失う
    （`cli.image_for` の呼ばれ方が変わったら、ここも書き直すこと）。
    (3) 注文の置き場が `docs/IMAGE_ORDERS.md` の約束から動いたら、両方の道を直すこと。
    """
    from pathlib import Path
    orders = Path(orders) if orders is not None else ROOT / "data" / "image_orders"
    images = Path(images) if images is not None else ROOT / "assets" / "images"

    def _has(oid: str) -> bool:
        return any((images / f"{oid}.{ext}").exists() for ext in ("jpg", "png"))

    oids = sorted(p.stem for p in orders.glob("*.json")) if orders.is_dir() else []
    missing = [o for o in oids if not _has(o)]
    last: dict[str, dict] = {}
    for r in rows:
        if r.get("event") == "built" and r.get("id"):
            last[r["id"]] = r
    restale = sorted(vid for vid, r in last.items()
                     if not r.get("image") and _has(f"{vid}-bg"))
    return {"n": len(oids), "delivered": len(oids) - len(missing),
            "missing": missing, "restale": restale,
            "built_books": len(last)}


def image_line(rows: list[dict]) -> str:
    """`image_orders` を1行にする（`trend` が毎周 印字 ＝ **次の回は覚えていなくてよい**）。"""
    q = image_orders(rows)
    body = (f"**画像の注文: {q['n']}件・{q['delivered']}/{q['n']} が届いている**"
            "（`trend.image_orders`・ファイルを見るだけ・追加 0単位）。")
    if q["missing"]:
        body += "  未着: " + "・".join(q["missing"][:3]) + "（外の毎時セッションが焼く）。"
    if q["restale"]:
        body += ("  !! **絵は在るのに、いちばん新しい build が単色: "
                 + "・".join(q["restale"][:3])
                 + "** ＝ その本の mp4 と sheet.png は**出る本と違う絵**です。"
                 "**`build` し直してから (3) 目で見ること**（`image_orders` の註）。")
    else:
        body += "  **焼き直し待ちの本 0本**（届いた絵は、いちばん新しい build に載っています）。"
    return body



#: **公開ページの 題・説明欄をあとから直した回の event 名**（2026-09-12 15:0x・optimizer・Opus）。
#: **2つ在るのは道具ではなく手書きだから**です —— この行を書く `cli` の口がどこにも無く、
#: 4件 とも回ごとに形を決めて書かれています（`meta_updated` 3件 ＝ `id` が台本 id・
#: `meta_update` 1件 ＝ `id` が video id・欄の名前も `what` / `field` / `why` / `reason` と別々）。
#: **片方だけを数えると 1件 落ちます。** 名を 1つ に寄せないのは、過去の行を書き換えないため
#: （`docs/JOURNAL.md` の「追記だけ」と同じ向き）—— **読む側が 2つ とも拾うこと。**
META_FIX_EVENTS = ("meta_updated", "meta_update")


def meta_fixes(rows: list[dict]) -> dict:
    """**上がった本の 題・説明欄を、あとから直した回**を数える（**API 0単位**・台帳を見るだけ）。

    2026-09-12 15:0x・optimizer・Opus。**§4 の出口 (0)〜(3) を抜けた欠陥の数**です。

    **踏んだ形**: 台帳に `meta_updated` 3件・`meta_update` 1件 が在り、
    **どれも 1行も読まれていません**（`grep meta_update studio/ scripts/ tests/` が 0件）。
    4件目 を書いた回は本文に「**4件目**」と手で数えて書いており ＝
    **数えている人は居るのに、数える口が無い**（`trend.flats` の「その 3本 を数える所が、
    どこにもなかった」・`cli.record_over` と同じ族の 6つ目）。

    **分けるのは齢ではなく、予約の刻**（`cmd_schedule` が置く `scheduled` の行）:
    予約の**前**の直しは §4 の出口の中で捕まった側（(0)〜(3) が効いた）で、
    予約の**後**は**出口を抜けた欠陥**です（`cli.meta_drift` の註 ＝ 予約の後に説明欄だけを
    直すと `yt.update_meta` を撃たない限り古いまま 10:00 に出る）。
    さらに公開の**後**は、**視聴者が誤りを読んだあと**の直し ＝ いちばん高く付く側。

    返り: `{"n", "books", "scheduled_books", "before", "after_sched", "after_pub",
             "unresolved", "names", "rows"}`。`rows` の 1件 は
    `{"at", "vid", "when"（"before"/"after_sched"/"after_pub"）, "event"}`。

    **`books` の分母は「予約ずみの本」**（`scheduled` が video_id を持つ本）から、
    **`replaced` で置き換えられた側を引いた数**です（`schedule --replace` は同じ枠に別の
    video_id を上げ、前の本は private へ戻る ＝ **上がった本としては 1本**）。
    **`trend.ours()` は引いていません**（あちらは「こちらの作りの id か」を訊く口で、
    分母を作る口ではない）—— **同じ台帳から 2つの数が出るので、混ぜないこと。**
    旧作りの本は §8 のとおり数えません。

    **判定は `hourly`**（§5 ＝ 出口の形を変えるかは台本を持つ側）—— ここは数を並べるまで。

    **覆る条件**: (1) `after_pub` が **2件目**を数えたら、直すのは §4 の出口ではなく
        **公開の前に説明欄を読み直す所**（(0-b) は声と説明欄の食い違いしか見ない）。
    (2) `after_sched` が **3本 続けて 0件**なら、この口は印字だけにしてよい（門にしない）。
    (3) `unresolved` が 1件 でも立ったら、直すのは数え方ではなく**書き方**です ——
        そのとき初めて `cli` に口を足し、`video_id` を必ず持たせること
        （**いま足さないのは、4件 とも `id` から引けているから** ＝ 口を足す値打ちが
        「名を揃える」だけになる）。
    """
    sched: dict[str, dict] = {}
    by_sid: dict[str, str] = {}
    replaced: set[str] = set()
    for r in rows:
        if r.get("event") != "scheduled" or not r.get("video_id"):
            continue
        vid = r["video_id"]
        sched.setdefault(vid, r)
        if r.get("replaced"):
            replaced.add(str(r["replaced"]))
        # **台本 id → video_id は「いちばん新しい予約」**（`--replace` で 1つの台本が
        # 2つの video_id を持つ ＝ `setdefault` だと置き換えられた側に当たります）。
        if r.get("id"):
            by_sid[str(r["id"])] = vid

    pub: dict[str, dt.datetime] = {}
    for vid, pts in series(rows).items():
        if pts:
            pub[vid] = published_at(pts)

    out: dict = {"n": 0, "books": 0,
                 "scheduled_books": len([v for v in sched if v not in replaced]),
                 "before": 0, "after_sched": 0, "after_pub": 0,
                 "unresolved": 0, "names": {}, "rows": []}
    seen: set[str] = set()
    for r in rows:
        ev = r.get("event")
        if ev not in META_FIX_EVENTS:
            continue
        out["n"] += 1
        out["names"][ev] = out["names"].get(ev, 0) + 1
        # **`id` は回によって台本 id にも video id にもなります**（上の註）——
        # `video_id` → `id`（台本 id の写し）→ `id` そのもの、の順で引く。
        vid = r.get("video_id") or by_sid.get(str(r.get("id"))) or str(r.get("id") or "")
        if vid not in sched:
            out["unresolved"] += 1
            continue
        seen.add(vid)
        at = _at(r)
        s_at = _at(sched[vid])
        p_at = pub.get(vid)
        if at < s_at:
            when = "before"
        elif p_at is not None and at >= p_at:
            when = "after_pub"
        else:
            when = "after_sched"
        out[when] += 1
        out["rows"].append({"at": at, "vid": vid, "when": when, "event": ev})
    out["books"] = len(seen)
    return out


def meta_fix_line(rows: list[dict]) -> str:
    """`meta_fixes` を1行にする（`trend` が毎周 印字 ＝ **次の回は覚えていなくてよい**）。"""
    q = meta_fixes(rows)
    if q["n"] == 0:
        return ("**上がった本の 題・説明欄をあとから直した回: 0件**"
                "（台帳 `meta_updated`／`meta_update`・`trend.meta_fixes`・追加 0単位）。")
    body = (f"**題・説明欄をあとから直した回: {q['n']}件・{q['books']}本**"
            f"（予約ずみ {q['scheduled_books']}本・`trend.meta_fixes`・追加 0単位）—— "
            f"**予約の前 {q['before']}件 ／ 予約の後・公開の前 {q['after_sched']}件 ／ "
            f"公開の後 {q['after_pub']}件**。**後ろの 2つ が §4 の出口 (0)〜(3) を抜けた数**です"
            "（`meta_fixes` の註・**判定は `hourly`**・§5）。")
    late = [r for r in q["rows"] if r["when"] == "after_pub"]
    if late:
        body += ("  公開の後: " + "・".join(f"{r['vid']} {r['at']:%m/%d %H:%M}" for r in late[:3])
                 + "（**視聴者が誤りを読んだあと**の直し）。")
    if q["unresolved"]:
        body += (f"  !! **本を引けなかった行 {q['unresolved']}件** ＝ 数え方ではなく書き方の側"
                 "（`meta_fixes` の覆る条件 (3)）。")
    return body

CHANNEL_MIN_SPAN_H = 0.5   # これより短い窓では、チャンネルの数の更新の刻みが見えるだけ
# **同じ周に 2体（`hourly` と `optimizer`）が `status` を撃つので、`channel` の行は周の 2倍 入ります。**
# 実測 2026-09-10 16:4x: 4行 ＝ 3周（15:24 / 15:58:58・15:59:33 / 16:40）。
# §7 (m) の門は「**3周** 動かないまま」なので、**行を数えると 1.3倍 速く門に着きます**
# （`data/rounds.jsonl` の「1周に 2行」と同じ族 —— METHOD §5「0 を落とさずに中央値を取ると 26分」）。
CHANNEL_SAME_ROUND_MIN = MIN_PAIR_MIN   # これより近い行は同じ周（10分）
CHANNEL_FLAT_LAPS = 3                   # §7 (m) の門: 読みが 3周 続けて同じなら「チャンネルの側」を先に見る
CHANNEL_MISMATCH = 0.10                 # `cli.record_channel` の覆る条件 (1) の 10%

#: **`views_per_h` を「率」として読んでよい門**（2026-09-12 23:2x・optimizer・Opus）。
#: **測るのは窓の中の刻みの*数*ではなく、「読みごとに何回 動いたか」**（`move_rate` ＝
#: 動いた区間 ÷ 区間）。**0.5 の出どころ**: 半分より多くの区間で読みが動かないなら、
#: 窓の平均（`views_per_h`）は**どの区間にも 1度も立っていません** ＝ 次の回に
#: 「1時間で N回 くらい伸びている」と読ませる数ではありません（`channel_steps` の註の
#: 「在りもしない滑らかさ」そのもの）。
#: **この数は測りの間隔とともに動きます。それで正しい** —— 刻みの周期（実測 9.8〜12.7時間）と
#: 同じ粗さで測れば `move_rate` は 1 に近づき、その粗さでは平均は公平な言い方になります。
#: **窓の長さでは動きません**（`n_values` / `one_step` が動いたのがこの欠陥・下の覆る条件 (3)）。
CHANNEL_SMOOTH_RATE = 0.5

#: **複製の遅れの実測（最大 2.8時間・`envelope` の註）そのもの。** `ENVELOPE_LAG_H` はこの 2倍 で、
#: 「遅れでは説明できない」を決める側です。ここで要るのは倍にする前の**生の遅れ**
#: —— 窓の頭の真の値を上から抑えるのに使う（`channel_video_delta` の註）。片方だけ動かさないこと。
REPLICA_LAG_H = 2.8

#: **(m) の「3周 続いたら」を数える塊の長さ**（2026-09-10 21:4x・optimizer・Opus）。
#: 窓ぜんたい（`channel_growth`）は**台帳の両端**なので刻が進むだけ伸び、`sum_confirmed` は
#: **単調に増えるだけ**です（`cut = t0 + REPLICA_LAG_H` の t0 が動かないので、`late` は増える一方 ＝
#: `min(late)` は下がる一方・`b` は上がる一方）。**＝ 1度 引かれた門は、新しい証拠が 1つも無くても
#: 次の周・その次の周と引かれ続け、「3周 続いた」が勝手に埋まります。**
#: `_flat_laps` の註（「行を数えると 1.3倍 速く門に着く」）と同じ族で、こちらは**時刻**の側。
#: → 塊は**重ならないように**切り、1塊ごとに 1回だけ数えます（`channel_over_blocks`）。
#: 長さは **遅れの 2倍** ＝ 塊の中に「遅れの外」の区間が 遅れと同じだけ残ります
#: （ちょうど `REPLICA_LAG_H` にすると `late` が末尾の 1点 だけになり、
#: 数えるのは伸びではなく複製の揺れになります）。
#: **刻みの周期からは、まだ引けません**（2026-09-12 02:2x・optimizer・Opus。
#: `channel_steps` の覆る条件 (1)「刻みが 2つ 以上 載ったら、その間隔の中央値から
#: `CHANNEL_BLOCK_MIN_H` を引き直すこと」は**この回に引かれ、そして引けないと分かりました**）。
#:
#: 実測の周期（`channel_steps(rows)["periods"]`）は **12.73時間・11.16時間**（中央値 11.94）
#: ですが、**その刻みは 2種類 を混ぜています** —— 大きい配り **+1,625回**（1つ・左端は
#: 台帳の先頭 ＝ `censored`）と、細かい刻み **+40 / +44回**（2つ）。
#: 塊の長さを変えて `over` を数え直すと（この回に撃った・API 0単位）:
#:
#:     L= 5.6h  塊 5・連なり 0   (44,11,F) (40,252,T) (0,14,T) (1625,7,F) (0,1,T)
#:     L= 8.0h  塊 3・連なり 2   (44,156,T) (40,408,T) (**1625**,14,**F**)
#:     L=11.9h  塊 2・連なり 1   (84,368,T) (**1625**,24,**F**)
#:     L=12.7h  塊 2・連なり 1   (84,532,T) (**1625**,29,**F**)
#:     L=17.0h  塊 1・連なり 1   (84,940,T)
#:     （かっこの中は `d_views`・確かめられた本の伸び・`over`）
#:
#: **＝ `over` が偽になるのは「大きい配りを含んだ塊」だけ**で、長さを伸ばすほど
#: 分子（本の伸び）だけが積もり、連なりは**速く**埋まります（L=8.0 で既に 2/3）。
#: **細かい刻みの周期（12時間）は、この門が要る周期ではありません** ——
#: 要るのは**大きい配りの間隔**で、それは **1度しか観測しておらず、左端が見えていません**。
#: だから **`2 * REPLICA_LAG_H` のまま据え置きます**（複製の遅れから来た数のまま ＝
#: **刻みの周期からは、いまも 1度も引かれていません**）。
#: **覆る条件**: (1) **2つ目の大きい配り**（`channel_steps` の `bulk`）が載ったら、
#: その間隔から引き直すこと —— そのときは中央値でも上端でもなく、**塊が配りを 1つ 含む**
#: ことが要件です。(2) それまでのあいだ、`channel_over_streak` の連なりを
#: 「(m) が壊れた」と読まないこと（連なりの塊が配りを含んでいるかは `streak_bulk` が言う）。
CHANNEL_BLOCK_MIN_H = 2 * REPLICA_LAG_H


def _channel_rows(rows: list[dict]) -> list[dict]:
    """`channel` の行を**刻の順**に並べて返す。

    **並べ直す理由（2026-09-10 16:4x・optimizer・Opus。実物で踏んだ）**: 台帳は追記なので
    行の順は**書いた順**であって刻の順ではありません —— 同じ周の 2体 が数十秒 差で書くと
    入れ替わります（実測: `15:59:33` の行が `15:58:58` の行より**前**に在る）。
    `channel_growth` は両端しか使わないので、**入れ替わりが端に来た周は窓が負になります**
    （`views_per_h` の符号が反転する）。いまは中ほどで起きただけで、まだ数は狂っていません。
    """
    cs = [r for r in rows if r.get("event") == "channel"
          and isinstance(r.get("views"), int) and isinstance(r.get("subs"), int)]
    return sorted(cs, key=_at)


def _channel_laps(cs: list[dict]) -> list[list[dict]]:
    """刻の近い行（既定 10分 以内）を **1周** に畳む。返すのは周ごとの行の塊。"""
    laps: list[list[dict]] = []
    for r in cs:
        if laps and (_at(r) - _at(laps[-1][-1])).total_seconds() / 60 <= CHANNEL_SAME_ROUND_MIN:
            laps[-1].append(r)
        else:
            laps.append([r])
    return laps


def _channel_env_points(cs: list[dict]) -> list[dict]:
    """周ごとに畳んで **その周の max** を取り、さらに前から単調にした（包絡）1点ずつを返す
    （2026-09-11 04:0x・optimizer・Opus。**API 0単位**）。

    **なぜ包絡か —— この回に実物で撃った（`channel_replicas` の註に derivation）**:
    チャンネルの `viewCount` も **本ごとの `videos.list` と同じく、遅れの違う複製から返ります**。
    実測 02:12:18 **84,781** → 02:12:43 **86,406**（**25秒 差で +1,625**）→ 03:24:53 **84,781**
    → 03:27（5回 続けて）**86,406**。**単調に増える数が 72分 で 1,625回 下がることはありません**
    ＝ 低いほうは**遅れた複製**です（`settle_stats` と同じ規則: **最大がいちばん新しい**）。

    包絡にしないと、次の 2つ が**複製で決まります**:
      * `channel_growth` の両端（`cs[0]` / `cs[-1]`）—— 端が古い複製に当たった周は
        `d_views` が 0 や負になり、**(m) の門（合計 ＞ チャンネル）が偽で引かれます**
        （この回の実測: 端が 84,781 で `d_views` **+0** ・`sum_confirmed` **+11** ＝ `over` True。
         包絡で読むと `d_views` **+1,625** ＝ **引かれません**）。
      * `channel_steps` の刻み —— 同じ 1,625 が **+1,625 と -1,625 の 2つの刻み**に見えます。

    返す 1点: `t0`/`t1`（その周の最初と最後の刻）・`hi`（その周の max）・`env`（包絡）・
    `drop`（前の周の包絡より、その周の max がどれだけ下か ＝ **複製の証拠**）・
    `n_values`（その周に在った別々の値の数）・`subs`（その周の max）。

    **本当の下がり（無効な再生の取り消し）は隠しません** —— 天井は `ceiling()` と同じ規則で決めます:
    峰を最後に見てから **`ENVELOPE_LAG_H`（6時間）より長く**下回ったままなら、その峰は
    遅れ（実測 最大 2.8時間）では説明が付かない ＝ 数え直しなので天井から落ちます。
    ＝ **6時間 以内の低い読みは複製・6時間 を越えて戻らない高い読みは消える**、の 2つを同じ口で分けます。

    **覆る条件**: (1) 下がったまま戻らない回の**長さ**が 6時間 に届かないのに、
    次の日も戻らなかった回が出たら、`ENVELOPE_LAG_H` はチャンネルの側では短すぎる
    （本ごとの複製の遅れから来た数なので、チャンネルの刻みでは引き直すこと）。
    (2) 同じ周（10分）の中で割れない ＝ `n_values` が 1 のまま 7本 過ぎたら、
    割れは周をまたいでしか起きない ＝ 畳む幅（`CHANNEL_SAME_ROUND_MIN`）を広げること。
    """
    laps = _channel_laps(cs)
    his = [max(r["views"] for r in lap) for lap in laps]
    ts = [_at(lap[0]) for lap in laps]
    out: list[dict] = []
    prev: int | None = None
    for i, lap in enumerate(laps):
        # **支えられている いちばん高い水準**（`ceiling()` と同じ規則を、チャンネルの側に当てる）——
        # 峰を最後に見てから `ENVELOPE_LAG_H` より長く下回ったままなら、それは遅れでは説明できない
        # ＝ **数え直し（無効な再生の取り消し）**なので、天井にしない。
        env = his[i]
        for v in sorted({h for h in his[:i + 1]}, reverse=True):
            seen = max(t for t, h in zip(ts[:i + 1], his[:i + 1]) if h >= v)
            if (ts[i] - seen).total_seconds() / 3600.0 <= ENVELOPE_LAG_H:
                env = max(v, his[i])
                break
        out.append({"rows": lap, "t0": _at(lap[0]), "t1": _at(lap[-1]),
                    "hi": his[i], "env": env,
                    "drop": 0 if prev is None else max(0, prev - his[i]),
                    "n_values": len({r["views"] for r in lap}),
                    "subs": max(r["subs"] for r in lap)})
        prev = env
    return out


def _pt_row(p: dict, end: bool = False) -> dict:
    """包絡の1点を、`_channel_gate` が読む台帳の行の形にする（刻はその周の端の実物）。"""
    return {"at": (p["rows"][-1] if end else p["rows"][0])["at"],
            "subs": p["subs"], "views": p["env"]}


def channel_replicas(rows: list[dict]) -> dict:
    """**チャンネルの `viewCount` が複製から返っている証拠**を数える
    （2026-09-11 04:0x・optimizer・Opus。**API 0単位** —— 台帳の `channel` の行を読むだけ）。

    **この回に踏んだ**: 前の周（02:2x）は 02:12 の **+1,625** を「刻み」と読み、
    §7 (m) の連なりを切り、刻みの周期（33〜40時間）まで derivation を書きました。
    **同じ数が 03:24 に -1,625 で戻りました。** 直に撃つと（`channels.list` **5回**・5単位）
    **5回 とも 86,406** ＝ 84,781 のほうが遅れた複製です。
    **本ごとの `videos.list` の複製（`settle_stats`・09/09 19:1x）と同じ族が、チャンネルの側にも在る。**

    返すもの: `split_laps`（同じ周に割れた読みが在った周の数）・`max_split`（その最大の幅）・
    `drops`（周の max が前の周の包絡より下がった回）・`max_drop`・`proved`（どちらか 1度でも出たか）・
    `env`（いまの包絡 ＝ **これが「いまの総再生」**）・`raw_last`（いちばん新しい生の読み）。

    **効く先**: §7 (m) —— **「総再生が動いた／止まった」を 1点 で読まないこと。**
    低い読みは遅れた複製で、**「刻み」と見分けられるのは、下がりが在るかどうかだけ**です。

    **覆る条件**: (1) `proved` が False のまま 7本 過ぎたら、この口は外してよい
    （チャンネルの側には複製が無い ＝ 包絡も要らない）。
    (2) 下がりの幅が毎回 違う（同じ 2値 の往復ではない）なら、複製は 2つ ではないので
    「最大がいちばん新しい」も怪しい ＝ そのときは `settle_stats` と同じ **3回 読み**を
    `cli.record_channel` の側に足すこと（+2単位/周）。
    """
    ps = _channel_env_points(_channel_rows(rows))
    splits = [p for p in ps if p["n_values"] > 1]
    drops = [p for p in ps if p["drop"] > 0]
    return {"laps": len(ps),
            "split_laps": len(splits),
            "max_split": max((max(r["views"] for r in p["rows"]) - min(r["views"] for r in p["rows"])
                              for p in splits), default=0),
            "drops": len(drops), "max_drop": max((p["drop"] for p in drops), default=0),
            "proved": bool(splits or drops),
            "env": ps[-1]["env"] if ps else None,
            "raw_last": ps[-1]["rows"][-1]["views"] if ps else None}


def channel_replica_line(rows: list[dict]) -> str:
    """`channel_replicas` を1行にする（`trend`／`status` が毎周 印字する ＝ 次の回は覚えていなくてよい）。"""
    r = channel_replicas(rows)
    if not r["proved"]:
        return ""
    parts = []
    if r["drops"]:
        parts.append(f"**周の max が下がった回 {r['drops']}回・最大 -{r['max_drop']}回**")
    if r["split_laps"]:
        parts.append(f"**同じ周に割れた読み {r['split_laps']}周・最大 {r['max_split']}回**")
    tail = ""
    if r["raw_last"] is not None and r["env"] is not None and r["raw_last"] < r["env"]:
        tail = (f"**いちばん新しい生の読み {r['raw_last']} は包絡 {r['env']} より下 ＝ "
                "その読みは遅れた複製です**（`status` の 1点 をそのまま「いまの総再生」と読まないこと）。")
    return ("**チャンネルの `viewCount` も複製から返ります**（" + "・".join(parts)
            + "）—— 低い読みは遅れた複製で、**最大がいちばん新しい**"
              "（`trend.channel_replicas` の註・`settle_stats` と同じ規則）。"
            + tail
            + "**「総再生が動いた／止まった」を 1点 で読まないこと。**")


def _flat_span_h(ps: list[dict]) -> float:
    """いまの平ら（包絡が同じ）が、**何時間**ぶんか（2026-09-11 04:0x・optimizer・Opus）。

    **なぜ周ではなく時間も要るか**: `CHANNEL_FLAT_LAPS`（3周 ＝ いまの床 36分 で **約 1.2時間**）は、
    実測の刻みの下端 **10.2時間**（`channel_steps`・02:2x）より**桁で短い**。
    ＝ 3周 の平らは「チャンネルが止まった」の証拠になりません。**周と一緒に時間を印字すること。**
    """
    if not ps:
        return 0.0
    n = _flat_laps(ps)
    if n < 2:
        return 0.0
    return (ps[-1]["t1"] - ps[len(ps) - n]["t0"]).total_seconds() / 3600.0


def _bench_words(g: dict) -> str:
    """時間の門の手本が**何例から**取られたかを、印字の中で1語にする
    （2026-09-12 02:2x・optimizer・Opus）。

    **なぜ道具の側で言うか**: 手本が 1例 だった頃の「**ただし手本は 1例**なので、
    これは『刻みの周期より長い』ではありません」は、**例が増えたら偽になる字**です。
    印字に数を焼くと、次の回はその字を読んで n＝1 のつもりで判断します
    （§5 教訓の形 6つ目 ＝ 検査にも印字にも「きょうの状態」を書かないこと）。
    """
    n = g.get("step_bench_n")
    if not n or n <= 1:
        return "1例"
    return f"{n}例 のうちいちばん長い1つ"


def _flat_window(ps: list[dict]) -> tuple | None:
    """**いまの平ら（包絡が同じ）の、両端の刻。** 無ければ None（2026-09-11 13:2x・optimizer・Opus）。

    `_flat_span_h` が返す「長さ」と**同じ区間**を、刻で返すだけの口です
    （2つの実装を持たないため —— `_channel_gate` の註と同じ族）。
    """
    if not ps:
        return None
    n = _flat_laps(ps)
    if n < 2:
        return None
    return (ps[len(ps) - n]["t0"], ps[-1]["t1"])


def flat_video_gain(rows: list[dict]) -> dict:
    """**いまの平らの「中で」、本が伸びたか**（包絡・遅れで説明が付かない分だけ・**API 0単位**）。

    2026-09-11 13:2x・optimizer・Opus。**§7 (m) の当て所を、時間の門より強い証拠で塞ぐ口**です。

    **踏んだ形（この回の実物）**: 総再生は **20周・10.8時間** 同じ読みで、
    `flat_readable`（平らが手本の挟みの上端 10.793時間 を越えたか）が **初めて True** になり、
    道具は「**引かれました ＝ 本の題や形を疑う前に、チャンネルの側が止まっていないかを外すこと**」と
    印字しました。**ところが、その同じ平らの中で 6本目 `mja40GJ-GHU` が 0 → 176回 に伸びています。**
    ＝ **チャンネルは止まっていません。平らなのは `viewCount` の読みのほうです。**

    **時間の門（`flat_h` 対 `step_flat_h_hi`）は、手本 1例 からの挟みで引く弱い門**ですが、
    この口は**同じ台帳の中の反証**で、n＝1 の手本を要りません
    ＝ **平らの中に確かめられた伸びが 1回でも在れば、その平らは「止まった」と読めない**。
    （向きは片側だけ: 伸びが **0** でも「止まった」の証拠にはなりません —— `measure` が触るのは
    公開 7日 以内の 19本 だけで、残り 250本 は見ていないからです。`channel_video_delta` の註と同じ。）

    返すもの: `t0`/`t1`（平らの両端）・`h`（長さ）・`sum`（見えるようになった分）・
    `confirmed`（**遅れで説明が付かない分** ＝ 門に当てるのはこちら）・`n`（読み直した本）・
    `grew`/`blind`（`channel_video_delta` の註）・
    `proves_alive`（`confirmed` が 0 より大きいか。`None` ＝ まだ言えない）。

    **`proves_alive` が `False` になるのは、伸びた本が 1本 も測れなかった回を外したあとだけ**
    （2026-09-11 19:5x・optimizer・Opus）: `confirmed == 0` には **2つ の意味**が在ります ——
    **(a) 伸びが確かめられなかった**（`blind > 0` ＝ 窓の確かめられる部分に `measure` が
    1回 しか入っていない）と、**(b) 伸びた本が 1本 も無かった**（`blind == 0`）。
    **(a) を `False` と読むと、§7 (m) の「平らの中の伸びが 0 の回（＝ そのとき初めて
    時間の門が独りで立つ）」が、測れなかっただけの回で引かれます。** だから (a) は `None`。
    ＝ `cli.comments_to_show` / `trend.pair_gap` / `reporting.missing_days` と**同じ族**
    （数は出るのに、その数がそろっているかが出ない）。

    **覆る条件（`blind` の側）**: `blind` が **0 のまま** `proves_alive is False` の回が
    3周 続いたら、そのとき初めて §7 (m) の「平らの中の伸びが 0」を数に使ってよい。

    **`blind == 0` を、この判定の門に使わないこと**（2026-09-12 14:1x・optimizer・Opus。**実物で踏んだ**）:
    **`confirmed == 0` の意味は 2つ ではなく 3つ**でした —— (a) `blind > 0`（測れなかった）・
    (b) `blind == 0`（測れて、伸びた本が 0本）に加えて、**(c) 平らが `REPLICA_LAG_H` より短く、
    そもそも訊けていない**回が在ります。(c) では `channel_video_delta` の `measurable` が偽で、
    **`grew` も `blind` も 0 のまま**（数える前に `continue` する）＝ **(b) と見分けが付きません。**
    **実物**: 2026-09-12 13:5x の周は 平ら **2.0時間**・`grew` 0・`blind` 0・`confirmed` `None` で、
    時間の門（3周）は引かれていました。**`blind == 0` で数えると、訊いてもいない回で
    §7 (m) の当て所が引かれます。** ＝ **門に当てる述語は 1つ だけ: `proves_alive is False`**
    （これは (b) のときにしか立ちません）。**`confirmed` と `blind` を手で組み合わせないこと。**
    (c) の回に線が 1字も言っていなかったのも同じ回に閉じました（`channel_line` / `channel_line_short`）。

    **覆る条件**: (1) `confirmed` が正なのに、そのあとチャンネルの総再生が
    **その分を受け取らないまま刻みを 2つ 跨いだ**回が出たら、そのときは伸びの側（`measure`）の
    包絡を疑うこと（いまは「チャンネルの読みが遅い」と読んでいる）。
    (2) 平らの長さが `REPLICA_LAG_H` より短い回では `confirmed` は `None` になります ——
    **その回に「伸びが無い」と読まないこと。**
    """
    ps = _channel_env_points(_channel_rows(rows))
    win = _flat_window(ps)
    if win is None:
        return {"t0": None, "t1": None, "h": None, "sum": None,
                "confirmed": None, "n": None, "grew": None, "blind": None,
                "proves_alive": None}
    t0, t1 = win
    vd = channel_video_delta(rows, t0, t1)
    conf = vd["sum_confirmed"]
    if conf is None:
        alive = None
    elif conf > 0:
        alive = True
    else:
        # **0 の意味は 2つ**（上の註）—— 測れなかった側は `False` に倒さない
        alive = None if vd["blind"] else False
    return {"t0": t0, "t1": t1, "h": (t1 - t0).total_seconds() / 3600.0,
            "sum": vd["sum"], "confirmed": conf, "n": vd["n"],
            "grew": vd["grew"], "blind": vd["blind"],
            "proves_alive": alive}


#: **`blind` の連なりの門**（`channel_video_delta` の覆る条件 (4)・`flat_video_gain` の
#: `blind` の側の覆る条件 —— どちらも「N周 続いたら」と書きながら、**数える口が無い**まま
#: 2026-09-12 16:0x まで残っていました）。
BLIND_EQ_RUN_NEED = 3
BLIND_FALSE_RUN_NEED = 3
#: `channel_video_delta` の覆る条件 (5)（`blind == 0` が 7周 続いたら欄ごと外してよい）。
BLIND_ZERO_RUN_NEED = 7


def blind_run(rows: list[dict], limit: int = 40) -> dict:
    """**`blind` の連なりを数える口**（2026-09-12 16:0x・optimizer・Opus。**API 0単位**）。

    `channel_video_delta` と `flat_video_gain` は `blind` の側に **3つ の覆る条件**を書いています
    —— どれも「**〜の回が N周 続いたら**」という形なのに、**その連なりを数える口が
    どこにも在りませんでした**（`grep blind studio/ scripts/` ＝ 印字はその周の 1点 だけ・
    §7 の「いまの数」も 1点 だけを写していた）。**次の回が手で数えるしかない条件**は、
    この repo でいちばん多い壊れ方です（`channel_video_delta` の註 16:4x・`trend.meta_fixes` 15:1x と同じ族）。

    **数え方**: 台帳の `channel` の周（`_channel_laps`）ごとに、**その周までの行だけ**に切って
    `flat_video_gain` を引き直します（`quota.margin_series` の「その周が見た数」と同じ形）。
    **平らの窓はその周の読みで決まる**ので、いまの窓を過去へ延ばして数えてはいけません。

    返す 3つ の連なり（どれも**新しい周から**数える）:

    * `run` —— **`grew > 0` かつ `blind == grew`**（＝ 伸びた本が 1本 も確かめられなかった周）。
      門は `BLIND_EQ_RUN_NEED`（3）＝ `channel_video_delta` の覆る条件 (4)
      「減らないまま `blind == grew` の回が 3周 続いたら、抑えの取り方（`REPLICA_LAG_H`）の側を疑う」。
    * `false_run` —— **`proves_alive is False`**（＝ 測れて、伸びた本が 0本 だった周）。
      門は `BLIND_FALSE_RUN_NEED`（3）＝ `flat_video_gain` の `blind` の側の覆る条件
      「そのとき初めて §7 (m) の『平らの中の伸びが 0』を数に使ってよい」。
    * `zero_run` —— **`blind == 0`**（`confirmed is None` の周は**外して**数える ＝ 訊けていない周。
      `channel_video_delta` の覆る条件 (5) が名指しで外している側）。門は `BLIND_ZERO_RUN_NEED`（7）。

    **飛ばす周と、切る周を分けてあります**（ここが読み違えやすい所）:
    **何も言えない周は飛ばし**（`confirmed is None` ＝ 平らが遅れより短い／`grew == 0`／
    `proves_alive is None`）、**逆を言った周で切ります**（`blind < grew`・`proves_alive is True`・
    `blind > 0`）。＝ 連なりは「**その向きの証拠が続いた周の数**」で、**時間の長さではありません**。
    飛ばした周が挟まると刻は離れるので、`span_h`（いちばん古い周からいまの周までの時間）も返します
    —— **門は周で引き、読むときは `span_h` を見ること。**

    **覆る条件**: (1) `run` が門に届いた回は、**先に `measure` の回数**を見ること ——
    `blind` は「確かめられる部分（平ら − 遅れ）に `measure` が 1回 しか入っていない」ときに立つので、
    1周 2回 撃つようになれば自然に落ちます（`channel_video_delta` の覆る条件 (4) の本文）。
    それでも落ちないときに初めて `REPLICA_LAG_H` を疑うこと。
    (2) 飛ばした周が連なりの周の数を**越えた**ら、周で数える形が効いていない ＝
    そのときは `span_h`（時間）の側で門を引き直すこと（数は `skipped` の欄）。
    (3) 平らの窓の取り方（`_flat_window`）を変えた回は、**過去の周の値ごと変わります** ——
    その回はこの連なりを 0 から数え直すこと（古い `run` を持ち越さない）。
    """
    cs = _channel_rows(rows)
    laps = _channel_laps(cs)
    empty = {"laps": 0, "run": 0, "need": BLIND_EQ_RUN_NEED, "drawn": False,
             "false_run": 0, "false_need": BLIND_FALSE_RUN_NEED, "false_drawn": False,
             "false_span_h": None, "false_skipped": 0,
             "zero_run": 0, "zero_need": BLIND_ZERO_RUN_NEED, "zero_drawn": False,
             "zero_span_h": None, "zero_skipped": 0,
             "span_h": None, "skipped": 0, "marks": []}
    if not laps:
        return empty

    def _when(row: dict) -> dt.datetime | None:
        try:
            return _at(row)
        except (KeyError, TypeError, ValueError):
            return None

    marks: list[dict] = []
    for lap in laps[-limit:]:
        end = _at(lap[-1])
        upto = [r for r in rows if (_when(r) or end) <= end]
        fv = flat_video_gain(upto)
        marks.append({"at": end, "h": fv["h"], "grew": fv["grew"], "blind": fv["blind"],
                      "confirmed": fv["confirmed"], "proves_alive": fv["proves_alive"]})

    def _count(kind: str) -> tuple[int, float | None, int]:
        n, oldest, skipped = 0, None, 0
        for m in reversed(marks):
            if kind == "eq":
                if m["confirmed"] is None or not m["grew"]:
                    skipped += 1                 # 何も言えない周は飛ばす
                    continue
                hit = m["blind"] == m["grew"]
            elif kind == "false":
                if m["proves_alive"] is None:
                    skipped += 1
                    continue
                hit = m["proves_alive"] is False
            else:
                if m["confirmed"] is None:
                    skipped += 1
                    continue
                hit = not m["blind"]
            if not hit:
                break                            # 逆を言った周で切る
            n += 1
            oldest = m["at"]
        span = (None if oldest is None
                else (marks[-1]["at"] - oldest).total_seconds() / 3600.0)
        return n, span, skipped

    run, span, skipped = _count("eq")
    false_run, false_span, false_skipped = _count("false")
    zero_run, zero_span, zero_skipped = _count("zero")
    return {"laps": len(marks), "run": run, "need": BLIND_EQ_RUN_NEED,
            "drawn": run >= BLIND_EQ_RUN_NEED,
            "false_run": false_run, "false_need": BLIND_FALSE_RUN_NEED,
            "false_drawn": false_run >= BLIND_FALSE_RUN_NEED,
            "false_span_h": false_span, "false_skipped": false_skipped,
            "zero_run": zero_run, "zero_need": BLIND_ZERO_RUN_NEED,
            "zero_drawn": zero_run >= BLIND_ZERO_RUN_NEED,
            "zero_span_h": zero_span, "zero_skipped": zero_skipped,
            "span_h": span, "skipped": skipped, "marks": marks}


def blind_run_words(rows: list[dict], limit: int = 40, short: bool = False,
                    kind: str = "eq") -> str:
    """`blind_run` を 1文にする（**句の出どころは 1か所** ——`channel_line` と
    `channel_line_short` は、どちらもこの文を使うこと。§5 の教訓の形 7つ目
    「覆る条件を註に書いたら、その条件を読む印字も一緒に作ること」）。

    `short=True` は短い行むけの短い形で、**数は同じ口から出ます**（文だけが短い）。

    **`kind` は、どの連なりを言うかです**（2026-09-12 17:3x・optimizer・Opus に足した）:

    * `"eq"`  —— `blind == grew`（伸びた本が 1本 も確かめられない周）。**`blind` の在る枝**が言う。
    * `"false"` —— `proves_alive is False`（**測れて、伸びた本が 0本 だった周**）。
      **`blind == 0` の枝**が言う ＝ §7 (m) の「平らの中の伸びが 0 の回」そのもの。

    **なぜ `kind` が要ったか**（**この回に実物で踏んだ**）: 16:0x は 3つ の連なりを**数え**ながら、
    印字したのは `run`（eq）だけで、しかも `channel_line` の **`blind` が立っている枝**にしか
    置いていませんでした。**§7 (m) が名指ししている連なりは `false_run` のほう**で、
    その枝（`flat_vid_confirmed == 0` かつ `blind == 0`）は**1字も言っていません**。
    16:37 の周で `proves_alive` が **初めて `False`** になり（`false_run` 1/3）、
    **その最初の1周を、印字は誰にも見せませんでした** ——
    ＝ **教訓の形 7つ目の 3例目**（`ceiling_rate` 11:2x・`fable_rolled` 20:5x と同じ形で、
    **今度は「数える口を足した回そのもの」が作った**）。

    **覆る条件**: (1) `zero_run` を読む枝が要る回が来たら、`kind="zero"` を足すこと
    （いまは門 7周 で、当てる枝が無い ＝ 足すと言わない行が増えるだけ）。
    (2) 枝と `kind` の対応が 2度 ずれたら、`kind` を呼ぶ側で選ぶのをやめ、
    `blind_run_words` が `flat_video_gain` を自分で引いて枝ごと決めること。"""
    b = blind_run(rows, limit)
    if not b["laps"]:
        return ""
    if kind == "false":
        n, need, drawn = b["false_run"], b["false_need"], b["false_drawn"]
        span, label = b["false_span_h"], "`proves_alive is False`"
        long_label = "`proves_alive is False`（測れて、伸びた本が 0本 だった周）"
    else:
        n, need, drawn = b["run"], b["need"], b["drawn"]
        span, label = b["span_h"], "`blind == grew`"
        long_label = "`blind == grew`（伸びた本が 1本 も確かめられない周）"
    if short:
        return (f"（**{label} は {n}/{need}周**"
                + ("・**引かれました**" if drawn else "")
                + "・`trend.blind_run`）")
    out = (f" **{long_label}は これで **{n}周** 続いています**"
           f"（門 {need}周・`trend.blind_run`）")
    # **1周 の連なりに「0.0時間」と言わないこと**（span は いちばん古い周から いまの周まで ＝
    # 1周 なら必ず 0。**時間で読むのは 2周 以上 から**・2026-09-12 17:3x）
    if span is not None and n >= 2:
        out += f"・その連なりは **{span:.1f}時間**"
    if drawn and kind == "false":
        out += ("。**引かれました ＝ そのとき初めて §7 (m) の「平らの中の伸びが 0」を"
                "数に使ってよい**（`flat_video_gain` の `blind` の側の覆る条件）——"
                "**それでも手本の挟み（時間の門）は別に見ること**")
    elif drawn:
        out += ("。**引かれました ＝ まず `measure` の回数を見ること**"
                "（1周 2回 撃てば `blind` は自然に落ちる・`blind_run` の覆る条件 (1)）——"
                "**それでも落ちないときに初めて `REPLICA_LAG_H` を疑うこと**")
    out += "。"
    return out


def _flat_laps(ps: list[dict]) -> int:
    """**総再生が動かないまま、いま何周 続いているか**（いちばん新しい周を 1 と数える）。

    **読むのは包絡**（`_channel_env_points`）—— 生の読みで数えると、遅れた複製に当たった周が
    「動いた」に見えます（実測 2026-09-11 03:2x: 86,406 → 84,781 → 86,406）。

    **数え方をここに固定します**（次の回が読み直さなくてよいように）:
    `2` は「読みが 2周 続けて同じ ＝ 動かなかった区間が 1つ」。
    §7 (m) の門 `CHANNEL_FLAT_LAPS = 3` は **読みが 3周 続けて同じ**（区間 2つ）で引かれます。
    """
    if not ps:
        return 0
    last = ps[-1]["env"]
    n = 0
    for p in reversed(ps):
        if p["env"] != last:
            break
        n += 1
    return n


def channel_steps(rows: list[dict]) -> dict:
    """総再生（`viewCount`）が **動いた瞬間** を並べる —— 刻みの大きさと、その手前の平らの長さ
    （2026-09-11 02:2x・optimizer・Opus。**API 0単位** —— 台帳の `channel` の行を読むだけ）。

    **なぜ要るか（この回に実物で踏んだ）**: `channel_line` は窓の両端から
    **`views_per_h`（回/時）**を出しますが、`viewCount` が**刻みで動く**とき、その数は率ではなく
    **「刻み ÷ 窓」**です。実測 2026-09-11 02:12 JST: 総再生は **20点・10.2時間**（下端）
    ずっと **84,781** で、**02:12 の 1点 で +1,625 して 86,406** になりました。
    同じ窓の `channel_line` は **+150.5回/時** と印字しますが、**その 150.5 が実際に立った瞬間は
    1つ もありません**（窓のほとんどは +0回/時・最後の1点だけが +1,625）。
    ＝ 次の回が「1時間で 150回 くらい伸びている」と読むと、**在りもしない滑らかさ**を前提にします。

    **平らは挟みで返します**（動いた刻そのものは台帳に無いので）:
      `flat_h_lo` = 古い値の**最初の読み → 最後の読み**（この長さは確実に平らだった）
      `flat_h_hi` = 古い値の**最初の読み → 新しい値の最初の読み**（これより長くはない）

    * `steps` は古い順。`last` はいちばん新しい 1つ（無ければ `None`）。
    * `n_values` は窓の中に在った**別々の値の数**、`one_step` は `n_values <= 2`。
      **どちらも窓（台帳）が伸びるだけで動く数で、率として読んでよいかを決められません**
      （2026-09-12 23:2x に踏んだ・下の覆る条件 (3)）。**読む側は `stepwise` / `move_rate`**
      （動いた区間 ÷ 区間・門 `CHANNEL_SMOOTH_RATE`）。`n_values` / `one_step` は
      **残してあるだけ**（過去の刻を読み直すときの写し）。

    **効く先**: §7 (m)（本ごとの 0回 を読む前にチャンネルの側を見る）と
    `channel_over_blocks`（「3周 続けて動かない」を塊で数える）。
    **この回の実測は、塊の長さ（`CHANNEL_BLOCK_MIN_H` × 3 ＝ 16.8時間）が
    刻み 10.8時間 より長いことを裏づけました** —— 周（1周 ≈ 0.6時間）で数えていれば
    **3周 ＝ 1.8時間** で埋まり、刻みを「チャンネルが止まった」と読んで
    (m) の当て所を作り直していたはずです（21:4x の直しの、実物での陽性）。

    **返すもの（2026-09-12 02:2x に足した 3つ・上の覆る条件 (1) が引かれた回）**:
      `steps[i]["censored"]`  その平らの**左端が台帳の先頭**か（＝ 見始めた刻。**周期にならない**）
      `periods`               **刻み → 刻み の間隔**（`censored` でない刻みの `flat_h_hi`。
                              挟みは同じ刻みの `flat_h_lo`〜`flat_h_hi`）と、その `med` / `max`
      `bench`                 **時間の門の手本**（`flat_readable` が当てる側）＝
                              `censored` でない刻みのうち**いちばん長い平ら 1つ**の挟み。
                              **直近の 1つ ではありません** —— 直近で読むと、手本は
                              刻みごとに ±1.5時間 揺れ、**すでに実測した 12.73時間 の平ら
                              （その後 刻んだ ＝ 止まっていなかった）より短い平ら**を
                              「チャンネルが止まった」と読みます（`channel_growth` の決め 02:2x）。
                              `censored` でない刻みが 1つも無いあいだは、`last` の挟みで代用し
                              `censored_only` を立てます（**上端は本当の上端ではありません**）。

    **観測した平らは、刻みの周期の「下端」です**（2026-09-11 02:3x に撃った検算）——
    この回の刻み **+1,625回** は、チャンネルの長い窓の平均（09/05 の手写し 80,483 → 02:12 の 86,406 ＝
    **+5,923 / 122〜146時間 ＝ 40.5〜48.5回/時**）で割ると **33.5〜40.1時間ぶん**に当たります。
    **観測した平らは 10.2〜10.8時間 しかありません** ＝ **`viewCount` は、この口を置いた
    09/10 15:24 の時点で既に古かった**（あるいは、その窓に burst が在った）。n＝1 では分けられません。
    **効く先（次の回はここを見ること）**: `CHANNEL_BLOCK_MIN_H × CHANNEL_FLAT_LAPS ＝ 16.8時間` は、
    **刻みの周期が 33〜40時間 なら短すぎます** —— 静かな 1日 が「チャンネルが止まった」と鳴ります。
    **21:4x が周（1.8時間）で踏んだのと同じ形が、桁を1つ上げて残っている恐れ**があります。
    **決めないこと** —— 2つ目の刻みが載れば、**間隔そのもの**が測れます（下の (1)）。

    **覆る条件**:
      (1) ~~刻みが 2つ 以上 台帳に載ったら、その間隔の中央値をここに書き、
          `CHANNEL_BLOCK_MIN_H` をその中央値から引き直すこと~~
          → **2026-09-12 02:2x に引かれました**（optimizer・Opus）。刻みは **3つ** 載り、
          そのうち**周期が測れるのは 2つ**です（1つ目は `t0` が台帳の先頭 09/10 15:24 ＝
          **左端が見えていない** ＝ `censored`。その +1,625 は長い窓の平均で 33〜40時間ぶん ＝
          **見始めた時点で `viewCount` が既に古かった**側・02:3x の検算）。
          **実測の周期（`periods`・刻み → 刻み）: 12.73時間・11.16時間**（挟みの下端 12.11／10.68）
          ＝ **中央値 11.94時間・上端 12.73時間**。
          **`CHANNEL_BLOCK_MIN_H` は上端から引き直しました**（`CHANNEL_STEP_PERIOD_H` の註）——
          **中央値では、塊の半分が平らの中に丸ごと入ります**（塊が刻みを 1つも含まなければ
          `d_views` は 0 になり、`over`（合計 ＞ チャンネル）は**量子化だけ**で引かれる）。
          **読む側は端で決める**のは `gate_span` / `margin_line` と同じ規則です。
          **新しい覆る条件**: ~~(1-a) 刻みが 4つ目 を載せたら `periods` を数え直し、
          上端が伸びていたら `CHANNEL_STEP_PERIOD_H` も一緒に動かすこと~~
          → **2026-09-12 23:2x に引かれました**（optimizer・Opus。刻みは **4つ目** が載った）。
          **動かす所はありませんでした。2つ とも。**
          (i) `periods` を数え直すと **12.73 / 11.15 / 9.79時間**（挟みの下端 12.11 / 10.68 / 8.85）
          ＝ **上端は 12.73 のまま**で、伸びたのではなく**下へ 1つ 増えた**（n＝2 の上端が
          「下からの押さえ」だった、その押さえは動いていません）。`bench` も 12.11〜12.73 のまま。
          (ii) **`CHANNEL_STEP_PERIOD_H` は、そもそも repo に在りません**
          —— 02:2x は「上端から引き直しました」と書きましたが、`CHANNEL_BLOCK_MIN_H` の註の側は
          同じ回に「**刻みの周期からは、まだ引けません・`2 * REPLICA_LAG_H` のまま据え置きます**」で
          終わっており、**検査 `tests/test_studio_channel_step_bench.py` が
          `not hasattr(trend, "CHANNEL_STEP_PERIOD_H")` を押さえています**
          ＝ **(1-a) は、検査が禁じている物を動かせと言っていました**（当て先が無い申し送りの族・
          METHOD §5 03:2x「『〜を置き換える』形で書かない」の、定数の側）。
          **引き直す先は `CHANNEL_BLOCK_MIN_H` で、その門は「2つ目の大きい配り」**
          （`CHANNEL_BLOCK_MIN_H` の註の覆る条件 (1)）—— **細かい刻みが何本 載っても引けません。**
          **新しい覆る条件**: (1-a') `periods` の**上端**が 12.73時間 を越えた回は、`bench`
          （時間の門の手本）が一緒に動くので、§7 (m) の「平らが手本の上端を越えたか」を数え直すこと。
          (1-b') 上端が越えないまま `periods` が **6つ** 載ったら、上端は n の小ささではなく
          本当の上限 ＝ そのとき初めて `bench` を「挟み」から「上端 1つ」に畳んでよい。
          (1-b) `over` の塊に **`stepped` が偽**（刻みが 1つも入っていない）が出たら、
          長さはまだ足りません ＝ そのときは中央値ではなく**その塊の長さ**から引き直すこと。
      (2) 刻みの大きさが同じ窓の `d_views` とほぼ同じ回（＝ `one_step`）が 3回 続いたら、
          `channel_line` の `views_per_h` は**印字ごとやめる**こと（率として読める窓が来ない）。
          **【2026-09-12 23:2x】この (2) は `one_step` では数えられません** —— 下の (3) と同じ理由で
          `one_step` は**台帳が伸びると二度と立たない**ので、連は 1 で永久に切れます。
          数えるなら `stepwise` の側で数えること（いまは印字が `stepwise` で出るので、
          「印字ごとやめる」の前提そのものが変わっています）。
      (3) ~~逆に `n_values` が 4 を越える窓が出たら、`viewCount` は滑らかに動いている ＝
          この関数は「刻み」ではなく「揺れ」を測っているので、そのときは `drops` の側と並べること。~~
          → **2026-09-12 23:2x に引かれ、そして「引かれた」ことに意味が無いと分かりました**
          （optimizer・Opus。**実測 `n_values` ＝ 5 ＞ 4**）。
          **`n_values` は窓の中の刻み ＋1 で、刻みは台帳が伸びれば積もるだけ** ＝
          **この門は滑らかさではなく台帳の長さを測っていました。**
          そのまま従えば、この回に「総再生は滑らかに動いている」と読むことになりますが、
          **実物は 87区間 のうち 4区間 でしか動いていません（4.6%）** ＝ 逆です。
          **直し**: 「読みごとに何回 動いたか」（`move_rate` ＝ 動いた区間 ÷ 区間）を返し、
          門は `CHANNEL_SMOOTH_RATE`（0.5）。**窓の長さでは動かず、測りの間隔でだけ動きます。**
          **同じ穴が `one_step` にも在りました**（＝ `channel_line` の
          「この `views_per_h` は率ではありません」の**印字が出る条件**）——
          09/11 02:2x に 1本目 の刻みで立ってから、**2本目 が載った時点で二度と立たなくなり**、
          次の回は**裸の `+47.7回/時` を読む**ことになっていました（§5 教訓の形 7つ目
          「註と印字が食い違えば、読まれるのは印字のほう」の 3例目・印字は `stepwise` へ移した）。
          **新しい覆る条件**: (3-a) `move_rate` が門 0.5 を**越えた**窓が出たら、そのときは本当に
          滑らかに動いている ＝ `views_per_h` を率として読んでよく、この関数は `drops` の側と並べること。
          (3-b) 測りの間隔（周の床）が刻みの周期（`periods` の下端・いま 8.85時間）へ近づいたら、
          `move_rate` は測りの粗さで上がります ＝ そのときは門ではなく**刻みの大きさ**で読むこと。
    """
    cs = _channel_rows(rows)
    ps = _channel_env_points(cs)
    laps = [p["rows"] for p in ps]
    # **包絡で読みます**（2026-09-11 04:0x）—— 生の周の max で読むと、遅れた複製に当たった周が
    # **同じ 1,625 を「+1,625 と -1,625 の 2つの刻み」**に見せます（`channel_replicas` の註）。
    pts = [(p["t0"], p["env"]) for p in ps]
    steps: list[dict] = []
    if pts:
        cur_v = pts[0][1]
        cur_t0 = pts[0][0]
        cur_last = pts[0][0]
        cur_n = 1
        for t, v in pts[1:]:
            if v == cur_v:
                cur_last, cur_n = t, cur_n + 1
                continue
            steps.append({
                "t0": cur_t0, "t1": t, "d": v - cur_v,
                "flat_h_lo": (cur_last - cur_t0).total_seconds() / 3600,
                "flat_h_hi": (t - cur_t0).total_seconds() / 3600,
                "flat_laps": cur_n,
            })
            cur_v, cur_t0, cur_last, cur_n = v, t, t, 1
    n_values = len({v for _, v in pts})
    # **左端が台帳の先頭の平らは、周期にも手本にもなりません**（覆る条件 (1)・2026-09-12 02:2x）
    # —— 見始めた刻より前がどれだけ平らだったかは、台帳に在りません。
    for i, st in enumerate(steps):
        st["censored"] = bool(pts) and i == 0 and st["t0"] == pts[0][0]
    fresh = [st for st in steps if not st["censored"]]
    per = [st["flat_h_hi"] for st in fresh]
    periods = {"h": per, "lo": [st["flat_h_lo"] for st in fresh], "n": len(per),
               "med": _median(per) if per else None,
               "max": max(per) if per else None}
    src = fresh or steps
    bench = None
    if src:
        b = max(src, key=lambda st: st["flat_h_hi"])
        bench = {"lo": b["flat_h_lo"], "hi": b["flat_h_hi"],
                 "n": len(src), "censored_only": not fresh}
    # **刻みらしさは「窓に刻みが何本 在るか」ではなく「読みごとに何回 動いたか」で測ります**
    # （2026-09-12 23:2x・`CHANNEL_SMOOTH_RATE` の註）—— `n_values` も `one_step` も
    # **台帳が伸びるだけで動く数**で、滑らかさを測っていませんでした（覆る条件 (3)）。
    gaps = max(len(pts) - 1, 0)
    move_rate = (len(steps) / gaps) if gaps else None
    return {"steps": steps, "last": steps[-1] if steps else None,
            "periods": periods, "bench": bench,
            "n_values": n_values, "one_step": n_values <= 2 and len(steps) >= 1,
            "gaps": gaps, "moved": len(steps), "move_rate": move_rate,
            "stepwise": bool(steps) and move_rate is not None
            and move_rate < CHANNEL_SMOOTH_RATE,
            "laps": len(laps)}


def channel_video_delta(rows: list[dict], t0: dt.datetime, t1: dt.datetime) -> dict:
    """同じ窓の**本ごとの増えの合計**（包絡で読む・**API 0単位**）。

    `cli.record_channel` の**覆る条件 (1)**（「総再生の増えが、同じ窓の本ごとの増えの合計と
    10% 以上 食い違ったら、この数でチャンネルが止まったかを読まないこと」）は、
    2026-09-10 16:4x まで**どこも数えていませんでした** ＝ 次の回が手で数えるしかない条件でした
    （METHOD が repo でいちばん多い壊れ方と呼ぶもの ——「言っている所と、している所が別」）。

    **この合計は下限です。** `measure` が触るのは**公開から 7日 以内の本**（実測 19本）で、
    チャンネルは **269本** 持っています。窓の中で古い本が伸びれば、
    その増えは合計に入らずチャンネルの総再生にだけ入る ＝ **チャンネル ＞ 合計**の側の食い違いは、
    いつでも「触っていない 250本」で説明が付きます。
    **説明が付かないのは逆向きだけ** —— **合計 ＞ チャンネル**（触っている本の増えを、
    チャンネルの総再生が受け取っていない）。だから門はその向きにだけ当てます（`over` の欄）。

    窓の頭に点を持たない本（窓の中で公開された本・測り始めた本）は**`sum` からだけ外します**
    （`skipped` / `no_base`）—— 基準が無いので、その本の再生を丸ごと「増え」と数えると
    合計が上へ外れます。

    **`sum_confirmed` からは外しません（2026-09-11 23:0x・optimizer・Opus。実物で踏んだ）。**
    **踏んだ形**: 同じ台帳の同じ刻で、**窓 31.6時間 の `sum_confirmed` が +44**、その**部分集合**である
    平ら 8.05時間 の `sum_confirmed` が **+265** ＝ **短いほうが大きい**。
    伸びは足されるだけなので、**部分集合が本体を越えることは起こり得ません** ＝ どちらかが間違っています。
    出どころは、`sum_confirmed` の輪が `a`（窓の頭の点）を要る側に入っていたこと:
    窓の中で公開された本は `a` が無いので `skipped` で `continue` し、**分子に 1回も入りません**。
    実物は `mja40GJ-GHU`（09/11 10:00 公開・窓の中）で、**確かめられる伸びは 917回**
    （窓 31.6時間 の分子は 44 → **961**。`over` は False のまま ＝ 門は偽で引きません）。
    **抑えは `a` ではなく `min(late)`** で、それは本が窓の頭に在ったかを要りません ——
    `v(s) >= true(s - 遅れ) >= true(t0)` は、`true(t0)` が **0（まだ公開されていない）**でも成り立ち、
    `b - min(late) <= b - true(t0)` ＝ **下からの抑えのまま**です。
    ＝ **(m) の門（合計 ＞ チャンネル。説明の付かない唯一の向き）は、
    いちばん速く伸びる本（出したばかりの本）だけを構造的に見ていませんでした。**
    **覆る条件**: 窓の頭に点を持たない本が `min(late)` を **1点しか持たない**回は `blind` に入ります
    —— `blind` が `grew` と同じ回が 3周 続いたら、抑えの取り方（`REPLICA_LAG_H`）の側を疑うこと（(4) と同じ）。
    **型**: **絞りを 1つ 書いた輪は、その絞りが要らない数まで一緒に絞ります**
    （§5 の教訓の形 5つ目の族・derivation は JOURNAL 23:0x）。

    **`sum` は窓の増えではありません（2026-09-10 19:3x・optimizer・Opus が実測で分けた）。**
    包絡は**読みが上がった刻**に上がるので、`sum` は「**窓の中で見えるようになった再生**」です。
    窓の頭までの読みが全部 遅れた複製だったなら、その差は**窓より前に付いた再生**で、
    チャンネルの総再生は**とっくに受け取っています** ＝ 食い違いの側ではありません。

    **実測（この回に踏んだ）**: 窓 15:24→19:14（3.8時間）の `sum` **+4回** は
    **`lQHX9LJ80Sg` 1本だけ**（683 → 687）。その本の生の読みは同じ 1時間 の中で
    **671 と 687**（差 16）に割れており、窓の頭の真の値が 683 だったのか 687 だったのかは
    **その時点の台帳では分けられません**。＝ **+4 は「窓の中で伸びた」と読めません。**

    **分けられる形**（この回に入れた `sum_confirmed`）: 再生は増えるだけなので、
    時刻 s の読み v は **`true(s - 遅れ) <= v`** を満たします（複製が返せるのは、その本が
    過去に通った値だけ ——`_lag_evidence` と同じ向きの言い方）。
    ＝ **`t0 + REPLICA_LAG_H` 以降の読みは、どれも窓の頭の真の値の上からの抑え**になります。
    いちばん小さいものを取って基準にすれば、残りは**遅れでは説明できない伸び**だけです:

        sum_confirmed = Σ max(0, 包絡(t1) - min{ 生の読み | t0 + 2.8時間 <= s <= t1 })

    **窓が `REPLICA_LAG_H` より短ければ、その読みが 1つも無い ＝ `None`（まだ測れていない）。**
    上の実測では基準が **687**（18:38・19:15 の読み）になり、**`sum_confirmed` は 0** ＝
    (m) の食い違いは**この窓では引けません**（`sum` の +4 では 3周 続けて引かれていた）。

    **覆る条件**: (1) `sum_confirmed` が 0 でない窓で総再生が動かない回が **3周** 続いたら、
    そのときこそ (m) の当て所（チャンネルの `viewCount`）を疑うこと ＝ この註は**当たった**側。
    (2) 数え直し（`recounts`・下へ数え直す機構）が 1本で **-3回 を越えた**ら、
    「再生は増えるだけ」が崩れるので上の抑えは効かない ＝ `sum_confirmed` ごと外すこと
    （いまの実測は 1本 -1〜-2回）。(3) `REPLICA_LAG_H`（2.8時間）は `envelope` の註の実測です
    —— `ENVELOPE_LAG_H` を動かす回は、**同じ回にこちらも**動かすこと（片方だけ動かさない）。

    **`blind`（2026-09-11 19:5x・optimizer・Opus。実物で踏んだ）**: 伸びた本のうち、
    **`[t0 + 遅れ, t1]` の読みが 1つ しか無くて `sum_confirmed` に 0 しか出せなかった本**の数。
    **窓の長さが遅れより長くても、確かめられる部分は `t1 - t0 - 遅れ` しかありません** ——
    実測 2026-09-11 19:1x: 平ら 4.35時間 の窓で、確かめられる部分は **1.55時間**、
    そこに入った `measure` は **1回 だけ**（床 37分 でも、`measure` は 1周 1回）。
    ＝ 抑え `min(late)` は最後の読み（＝ `b`）そのものになり、**伸びた 2本 とも 0**。
    そのとき `sum_confirmed == 0` は「伸びなかった」ではなく **「測れなかった」**です。
    **`grew` は窓の中で伸びた本の数**（`blind` の分母）。
    **覆る条件 (4)**: `measure` が 1周 に 2回 以上 撃たれるようになったら、`blind` は自然に減ります
    —— **減らないまま `blind == grew` の回が 3周 続いたら**、抑えの取り方（`REPLICA_LAG_H` の側）を
    疑うこと。(5) 逆に `blind == 0` の回が 7周 続いたら、この欄は外してよい
    （**この (5) を数えるときは `sum_confirmed is None` の回を外すこと** —— 窓が遅れより短い回は
    `measurable` が偽で、`grew` も `blind` も **0 のまま**返ります ＝ 「測れて 0本」ではなく
    「訊いていない」。2026-09-12 14:1x に実物で踏んだ・`flat_video_gain` の註）。
    """
    out = {"sum": 0, "n": 0, "fresh": 0, "skipped": 0, "no_base": 0,
           "sum_confirmed": None, "unconfirmable": 0, "lag_h": REPLICA_LAG_H,
           "grew": 0, "blind": 0}
    # **窓が遅れより短ければ、確かめられる伸びは 1回 も無い**（抑えに使える読みが窓の中に無い）
    measurable = (t1 - t0).total_seconds() / 3600.0 >= REPLICA_LAG_H
    if measurable:
        out["sum_confirmed"] = 0
    cut = t0 + dt.timedelta(hours=REPLICA_LAG_H)
    for _vid, pts in series(rows).items():
        env = envelope(pts)
        a = b = None
        fresh = False
        late: list[int] = []
        for p, v in zip(pts, env):
            t = _at(p)
            if t <= t0:
                a = v
            if t <= t1:
                b = v
            if t0 < t <= t1:
                fresh = True
            if cut <= t <= t1:
                late.append(int(p["views"]))
        if b is None:
            out["skipped"] += 1
            continue
        if a is None:
            # **窓の頭に点が無い本を外すのは `sum` の側だけ**（2026-09-11 23:0x の直し・下の註）。
            # `sum_confirmed` の抑えは `a` ではなく `min(late)` なので、この本も確かめられます。
            out["skipped"] += 1
            out["no_base"] += 1
        else:
            out["sum"] += b - a
            out["n"] += 1
            # **伸びを出せるのは、窓の中で読み直した本だけ**（`measure` が触るのは公開から 7日 以内 ＝
            # 実測 19本）。基準を持つ 46本 のうち残りは、点が窓より前で止まっているので必ず +0 を返します
            # —— **その 0 を「伸びなかった」と読まないこと。**
            out["fresh"] += 1 if fresh else 0
        if not measurable:
            continue
        if b - (a if a is not None else 0) <= 0:
            continue          # 伸びていない本は、抑えが無くても食い違いを作りません
        out["grew"] += 1
        if not late:
            out["unconfirmable"] += 1   # 遅れの外に読みが無い ＝ この窓では分けられない
            out["blind"] += 1
            continue
        gain = max(0, b - min(late))
        # **読みが 1つ しか無い窓では、この抑えは伸びを 1回 も返せません**
        # （2026-09-11 19:5x・optimizer・Opus。**実物で踏んだ**）: 並びがふつう
        # （遅れた複製に当たっていない）なら、`[cut, t1]` の唯一の読みは **最後の読み ＝ b** なので
        # `b - min(late)` は **恒等的に 0** です。＝ その 0 は「伸びなかった」ではなく
        # **「この窓では測れない」**。`blind` に数え、verdict は `None`（まだ言えない）へ倒します。
        if gain == 0 and len(late) < 2:
            out["blind"] += 1
        out["sum_confirmed"] += gain
    return out


def _channel_gate(rows: list[dict], a: dict, b: dict) -> dict:
    """**1つの区間**（`channel` の行 a → b）で、`record_channel` の覆る条件 (1) が引かれるか。

    窓ぜんたい（`channel_growth`）も 1塊（`channel_over_blocks`）も**同じこの口**を通します
    —— 2つの実装を持つと、片方だけ直した回に「同じ問いに違う答え」が出ます
    （METHOD §5 の教訓の形 1つ目と同じ族）。
    """
    t0, t1 = _at(a), _at(b)
    span_h = (t1 - t0).total_seconds() / 3600
    d_subs, d_views = b["subs"] - a["subs"], b["views"] - a["views"]
    vd = channel_video_delta(rows, t0, t1)
    denom = max(abs(d_views), abs(vd["sum"]))
    mismatch = None if denom == 0 else abs(d_views - vd["sum"]) / denom
    conf = vd["sum_confirmed"]
    return {"t0": t0, "t1": t1, "span_h": span_h,
            "d_subs": d_subs, "d_views": d_views, "vd": vd,
            "mismatch": mismatch, "conf": conf,
            # **門は片側だけ**（`channel_video_delta` の註 —— 逆向きは「触っていない 250本」で説明が付く）
            # **かつ、分子は `sum_confirmed`** —— `None`（区間が遅れより短い）なら引けません
            "over": (mismatch is not None and mismatch >= CHANNEL_MISMATCH
                     and conf is not None and conf > d_views)}


def channel_over_blocks(rows: list[dict]) -> list[dict]:
    """**(m) の「3周 続いたら」を、重ならない塊で数える**
    （2026-09-10 21:4x・optimizer・Opus。**API 0単位**）。

    **なぜ「周」で数えないか（この回に実物で撃った）**: `channel_growth` の窓は
    **台帳の `channel` の行の両端**で、周が進むほど伸びるだけです。その窓の `sum_confirmed` は
    **単調に増えるだけ**（`cut = t0 + REPLICA_LAG_H` の `t0` が動かないので `late` は増える一方 ＝
    `min(late)` は下がる一方・包絡 `b` は上がる一方）。
    ＝ **1度 引かれた門は、新しい証拠が 1つも無くても次の周・その次の周と引かれ続けます。**
    実測（この回・11周 を1周ずつ再生した）: `over` は 10周 とも False で、
    21:20 の周に初めて True。その True の中身は `gv1u7n_pCAQ` の **930 → 932（+2回）** 1本 だけで、
    **同じ +2 が、次の周も その次の周も同じ窓の中に居ます** ＝ 周で数えると
    **2時間 後には「3周 続いた」が埋まり、(m) の当て所ごと作り直す**ことになっていました。

    **数え方**: いちばん新しい行から**後ろへ**、長さ `CHANNEL_BLOCK_MIN_H`（＝ 遅れの 2倍）以上 の
    塊に切り、**塊どうしは重ねません**。返すのは**新しい順**に、塊ごとの `_channel_gate`。
    切り残し（いちばん古い側の、長さの足りない塊）は返しません ＝ **まだ言えない**。

    **覆る条件**: (1) 塊が 3つ そろう前にチャンネルの `viewCount` が動いたら、
    そこで数え直し（`over` でない塊が 1つ 入れば連なりは切れる ＝ `channel_over_streak`）。
    (2) 周の間隔が伸びて 1塊 に 2周 も入らなくなったら（1塊 5.6時間 ＝ いまの床 37分 で 9周）、
    塊の中の点が足りず `sum_confirmed` が `None` になります —— そのときは長さではなく
    **点の数**で切ること。(3) `REPLICA_LAG_H` を動かす回は、この長さも一緒に動きます（定義から）。
    """
    # **端は包絡で読みます**（2026-09-11 04:0x・`channel_replicas` の註）——
    # 端が遅れた複製に当たった塊は `d_views` が 0 や負になり、**門が偽で引かれます**。
    ps = _channel_env_points(_channel_rows(rows))
    out: list[dict] = []
    i = len(ps) - 1
    while i >= 0:
        t1 = ps[i]["t1"]
        j = i
        while j >= 0 and (t1 - ps[j]["t0"]).total_seconds() / 3600 < CHANNEL_BLOCK_MIN_H:
            j -= 1
        if j < 0:
            break                       # 切り残し ＝ まだ言えない
        out.append(_channel_gate(rows, _pt_row(ps[j]), _pt_row(ps[i], end=True)))
        i = j - 1
    return out


def channel_over_streak(rows: list[dict]) -> dict:
    """**いま何塊 続けて (m) の門が引かれているか**（新しい側から数える）。

    `channel_over_blocks` の註のとおり、**周ではなく塊**で数えます。
    §7 (m) の「3周 続いたら (m) の当て所ごと作り直し」は、この `streak` が
    `CHANNEL_FLAT_LAPS`（3）に届いた回のことです ＝ **`3 × 5.6時間 ＝ 16.8時間` ぶんの、
    重ならない証拠**。`blocks` が 3つ に満たないうちは、届きようがありません（`ready` が False）。
    """
    bs = channel_over_blocks(rows)
    n = 0
    for b in bs:
        if not b["over"]:
            break
        n += 1
    # **連なりが「配りの間隔」で埋まっていないか**（2026-09-12 02:2x・`CHANNEL_BLOCK_MIN_H` の註）。
    # 実測: `over` が偽になるのは**大きい配りを含んだ塊だけ**で、塊を伸ばすほど
    # 分子（本の伸び）だけが積もる ＝ **連なりは「止まった」ではなく「配りを跨がなかった」で埋まります。**
    # 物差しは**台帳でいちばん大きい配り**（勝手な閾値を置かないため）。
    steps = channel_steps(rows)["steps"]
    max_step = max((st["d"] for st in steps), default=0)
    streak_dv = [b["d_views"] for b in bs[:n]]
    return {"streak": n, "blocks": len(bs), "need": CHANNEL_FLAT_LAPS,
            "block_h": CHANNEL_BLOCK_MIN_H,
            "ready": len(bs) >= CHANNEL_FLAT_LAPS,
            "drawn": n >= CHANNEL_FLAT_LAPS,
            "max_step": max_step, "streak_dv": streak_dv,
            "streak_bulk": (any(d >= max_step for d in streak_dv)
                            if (max_step and streak_dv) else None)}


def channel_growth(rows: list[dict]) -> dict:
    """台帳の `channel` の行から、**チャンネル全体の登録と総再生の増え**を数える
    （2026-09-10 15:5x・optimizer・Opus。**API 0単位** —— 数は `cli.record_channel` が毎周 残す）。

    返すのは窓の**両端だけ**（最初の行と最後の行）で、途中の点は使いません
    —— チャンネルの `viewCount` は本ごとの `statistics` と別の刻みで動くので、
    区間ごとの %/時 を並べると刻みを測ることになります（`quota.pace()` が 09/06 に踏んだ形）。

    * `subs_per_view` は **登録の増え ÷ 総再生の増え**（§7 の収益の節の覆る条件 (1) の「登録率」）。
      **分母が 0 のときは `None`** ＝「まだ測れていない」。0 を返さないこと。
    * `views_per_h` が **0 のまま**で、同じ窓に 0回 の本が在るなら、その 0回 は
      **その本の側ではなくチャンネルの側**かもしれない ＝ 本ごとの `first_view` で読まないこと。

    **覆る条件は `cli.record_channel` の註**（(1) 本ごとの合計と 10% 食い違ったら、この数で
    「チャンネルが止まったか」を読まない・(2) 登録の分子が 0 のまま 7本）。

    **総再生が動かない窓で、登録だけが動くことが在ります**（2026-09-10 21:1x・optimizer・Opus。
    実測: 15:24〜20:27 の 16点 で `viewCount` は **84,781 のまま**・`subscriberCount` は
    18:38 に **27 → 28**）。**＝ 同じ `channels.list` の応答が丸ごと古いのではありません**
    —— 応答の中の**別の欄が動いている**ので、`viewCount` が動かないのは**その欄の刻み**の話です。
    `channel_line` はこの形を自分で言います（`d_views == 0` かつ `d_subs != 0` の窓）。
    **効く先**: §7 (m) の「本の題や形を疑う前に、チャンネルの側が止まっていないかを外すこと」は、
    **「チャンネル全体に配りが来ていない」の証拠にはなりません** —— 外せるのは
    「総再生の数がこの窓で読めない」までです。**覆る条件 (4)**: 登録も総再生も
    **同じ窓で 3周 続けて動かない**回が出たら、そのときは応答そのものを疑ってよい
    （そのときだけ「チャンネルの側」が本の 0回 の説明に使えます）。

    **決め（2026-09-11 11:3x・optimizer・Opus）: 平らを「止まった」と読める門は、
    実測の刻みの手前の平らの「挟みの上端」（`flat_h_hi`）。下端（`flat_h_lo`）ではない。**
    `channel_steps` は平らを**挟みで返します**（動いた刻そのものは台帳に無いので
    `flat_h_lo` ＝ 確実に平らだった長さ・`flat_h_hi` ＝ これより長くはない）。
    04:0x はその**下端**を門にしていました ＝ 手本の真の長さが挟みのどこに在っても
    「止まった」と鳴る側で、**いちばん早く鳴る選び方**です。
    実測 11:3x: 手本は **1例だけ**で挟みは **10.199〜10.793時間**（差 0.594時間 ＝ いまの床で約 1周）・
    いまの平らは **9.2時間** ＝ **2周 後に下端を越えます**。そこで鳴る「止まった」は、
    手本が 10.8時間 だった場合には**手本より短い平ら**を「前例より長い」と呼びます。
    **門は上限で読むこと** —— §7 (b-2) の `gate_span`（振れ幅の上限で門を引く）と同じ形で、
    `channel_steps` の註も「観測した平らは刻みの周期の**下端**」「n＝1 では分けられない」と
    同じ向きを言っています（**印字と註が食い違っていた ＝ §5 の教訓の形 7つ目**）。
    **覆る条件**: (1) 刻みが 2つ 以上 載ったら、門は挟みではなく**間隔の中央値**から引くこと
    （`channel_steps` の覆る条件 (1) と同じ口・そのときこの挟みは捨ててよい）。
    (2) 上端を越えてもなお「止まった」が本の 0回 を説明しなかった回が 2回 出たら、
    門は時間ではなく別の物（`sum_confirmed` の側）で引くこと。
    (3) 挟みの幅（いま 0.594時間）が 1周 より狭くなったら、上端と下端の差は周で消える ＝
    そのときは印字の文だけ残して、門は下端へ戻してよい。
    """
    cs = _channel_rows(rows)
    ps = _channel_env_points(cs)
    laps = [p["rows"] for p in ps]
    base = {"n": len(cs), "laps": len(laps), "flat_laps": _flat_laps(ps),
            "flat_h": _flat_span_h(ps),
            "vid_sum": None, "vid_n": None, "vid_fresh": None, "vid_skipped": None,
            "vid_no_base": None,
            "vid_confirmed": None, "vid_unconfirmable": None,
            "mismatch": None, "over": False,
            "over_streak": 0, "over_blocks": 0, "over_ready": False, "over_drawn": False,
            "over_max_step": 0, "over_streak_dv": [], "over_streak_bulk": None,
            "step_flat_h": None, "step_flat_h_hi": None, "step_bench_n": None,
            "flat_readable": True,
            "flat_vid_confirmed": None, "flat_alive": None}
    if len(cs) < 2:
        return {**base, "span_h": None, "d_subs": None, "d_views": None,
                "views_per_h": None, "subs_per_view": None,
                "subs": cs[-1]["subs"] if cs else None, "views": cs[-1]["views"] if cs else None}
    # **両端も包絡で読みます**（2026-09-11 04:0x・`channel_replicas` の註。
    # 実測: 端が遅れた複製 84,781 に当たり `d_views` が **+0**、`sum_confirmed` **+11** で
    # (m) の門が**偽で引かれていました** —— 包絡なら **+1,625** ＝ 引かれません）
    a, b = _pt_row(ps[0]), _pt_row(ps[-1], end=True)
    # **門に当てるのは `sum_confirmed`（遅れでは説明が付かない伸びだけ）**
    # —— `sum` は「窓の中で見えるようになった再生」で、窓より前に付いたぶんを含みます
    # （`channel_video_delta` の註・2026-09-10 19:3x の実測）。
    # **窓ぜんたいの `over` は「いま引かれているか」だけ。「3周 続いたか」は
    # `channel_over_streak`（重ならない塊）で数えます** —— この窓は伸びる一方なので、
    # 同じ 1回の証拠が毎周 数え直されます（`channel_over_blocks` の註・21:4x）。
    g = _channel_gate(rows, a, b)
    vd, conf = g["vd"], g["conf"]
    st = channel_over_streak(rows)
    # **平らを「止まった」と読めるのは、実測の刻みの手前の平らより長いときだけ**
    # （2026-09-11 04:0x・`_flat_span_h` の註。**full と短い行が同じ口から読むこと** ——
    #  `channel_line_short` の覆る条件 (2)「2つが違う verdict を言ったら片方を消す」）
    # **手本は「直近の 1つ」ではなく「いちばん長い平ら」**（2026-09-12 02:2x・`channel_steps`
    # の `bench`）—— 直近で読むと手本は刻みごとに ±1.5時間 揺れ、**すでに実測した
    # 12.73時間 の平ら（その後 刻んだ ＝ 止まっていなかった）より短い平ら**を
    # 「チャンネルが止まった」と読みます（同じ台帳が反証を持っている側）。
    st_all = channel_steps(rows)
    st_bench = st_all["bench"] or {}
    step_lo, step_hi = st_bench.get("lo"), st_bench.get("hi")
    bench_n = st_bench.get("n")
    flat_h = _flat_span_h(ps)
    fv = flat_video_gain(rows)
    return {**base, "span_h": g["span_h"], "d_subs": g["d_subs"], "d_views": g["d_views"],
            "views_per_h": (g["d_views"] / g["span_h"]) if g["span_h"] >= CHANNEL_MIN_SPAN_H else None,
            "subs_per_view": (g["d_subs"] / g["d_views"]) if g["d_views"] > 0 else None,
            "subs": b["subs"], "views": b["views"],
            "vid_sum": vd["sum"], "vid_n": vd["n"], "vid_fresh": vd["fresh"],
            "vid_skipped": vd["skipped"], "vid_no_base": vd["no_base"],
            "vid_confirmed": conf, "vid_unconfirmable": vd["unconfirmable"],
            "mismatch": g["mismatch"], "over": g["over"],
            "over_streak": st["streak"], "over_blocks": st["blocks"],
            "over_ready": st["ready"], "over_drawn": st["drawn"],
            "over_max_step": st["max_step"], "over_streak_dv": st["streak_dv"],
            "over_streak_bulk": st["streak_bulk"],
            "step_flat_h": step_lo, "step_flat_h_hi": step_hi, "step_bench_n": bench_n,
            # **時間の門**（手本 1例 の挟みの上端）と、**平らの中の反証**は別の口です
            # （`flat_video_gain` の註・2026-09-11 13:2x）。反証のほうが強い ＝
            # 平らの中に確かめられた伸びが在れば、上端を越えていても「止まった」とは読めません。
            "flat_readable": step_hi is None or flat_h >= step_hi,
            "flat_vid_confirmed": fv["confirmed"], "flat_alive": fv["proves_alive"],
            # **`confirmed == 0` の 2つ の意味を分ける欄**（`flat_video_gain` の註・19:5x）
            "flat_grew": fv["grew"], "flat_blind": fv["blind"]}


def _bulk_words(g: dict) -> str:
    """**連なりが「止まった」ではなく「大きい配りを跨がなかった」で埋まっていないか**
    （2026-09-12 02:2x・optimizer・Opus。`CHANNEL_BLOCK_MIN_H` の註の実測）。

    実測（塊の長さを 5.6〜17時間 で振った）: **`over` が偽になったのは、台帳でいちばん
    大きい配り（+1,625回）を含んだ塊だけ**でした。塊を伸ばすほど分子（本の伸び）だけが
    積もるので、**連なりは長さを伸ばすほど速く埋まります**（L=8.0時間 で 2/3）。
    ＝ **連なりが測っているのは、いまのところ「配りの間隔」です。**

    物差しは**台帳でいちばん大きい配り**（勝手な閾値を置かないため）。
    **覆る条件**: 2つ目の大きい配りが載って間隔が測れたら、この行ではなく
    `CHANNEL_BLOCK_MIN_H` を引き直すこと（同 (1)）。
    """
    big, dv = g.get("over_max_step"), g.get("over_streak_dv") or []
    if not big or not dv or g.get("over_streak_bulk"):
        return ""
    return ("。**ただし、この連なりの塊の総再生の増えは "
            + "／".join(f"{d:+d}回" for d in dv)
            + f" で、実測でいちばん大きい配り **{big:+d}回** を 1つも含んでいません** ＝ "
            "**いま埋まっているのは「配りの間隔」で、「チャンネルが止まった」ではありません**"
            "（`trend._bulk_words`・`CHANNEL_BLOCK_MIN_H` の註 02:2x）")


def channel_line(rows: list[dict]) -> str:
    """`channel_growth` を1行にする（`status` と `trend` が毎周 印字する ＝ **次の回は覚えていなくてよい**）。"""
    g = channel_growth(rows)
    if g["n"] < 2:
        return (f"**チャンネルの数の点: {g['n']}件** —— 増えを数えるには 2点 要ります"
                "（`cli.record_channel` がこの回から毎周 残します・**API 0単位**）。"
                "**METHOD §1 の「登録者 25人」は 09/05 の手写しの 1点**で、"
                "いまとの差が**いつ付いたか**は、まだ台帳に在りません。")
    if g["span_h"] is None or g["span_h"] < CHANNEL_MIN_SPAN_H:
        return (f"**チャンネル 登録 {g['subs']}・総再生 {g['views']}**（点 {g['n']}件・"
                f"窓 {g['span_h']:.2f}時間 ＜ {CHANNEL_MIN_SPAN_H:.1f}時間 ＝ **まだ読まないこと**）。")
    rate = ("測れていません（総再生の増えが 0）" if g["subs_per_view"] is None
            else f"**{g['subs_per_view'] * 100:.3f}%**（門 0.5%・§7 の収益の節の覆る条件 (1)）")
    # **周で言うこと**（§7 (m) の門は「3周」・行ではない。`_flat_laps` の註）
    # **窓ぜんたいの増えではなく、いちばん新しい側の平らを見ること**（検査が捕まえた:
    # 窓の頭で伸びていても、いま 3周 動いていなければ (m) は引かれます）
    # **`over` の回は (m) を読まないこと**（2026-09-10 17:3x・optimizer・Opus。
    # `record_channel` の覆る条件 (1)「食い違ったら、この数でチャンネルが止まったかを読まない」が
    # 引かれているのに、この行は同じ息で「チャンネルの側が止まっていないかを外すこと」と言っていた
    # ＝ **言っている所と、している所が別**。門は引けても、読みは引けません）
    # **刻みで動く読みの「回/時」は率ではない**（`channel_steps` の註・2026-09-11 02:2x）——
    # 窓の中で総再生が **1度しか動いていない**なら、`views_per_h` の分子は刻み 1つ ぶんです。
    st_ = channel_steps(rows)
    rep = channel_replica_line(rows)
    step = ""
    if st_["last"] is not None:
        L = st_["last"]
        step = (f"**総再生は刻みで動きます** —— 直近の動きは "
                f"**{L['d']:+d}回 が 1点 で**（その手前は **{L['flat_laps']}周・"
                f"{L['flat_h_lo']:.1f}〜{L['flat_h_hi']:.1f}時間** 同じ読み）。")
        # **印字の門は `one_step` ではなく `stepwise`**（2026-09-12 23:2x・覆る条件 (3)）——
        # `one_step`（`n_values <= 2`）は**台帳が伸びると二度と立たない**ので、
        # 2本目 の刻みが載った刻から、次の回は裸の「回/時」を読むことになっていました。
        if st_["stepwise"] and g["views_per_h"] is not None:
            step += (f"**この窓で読みが動いたのは {st_['gaps']}区間 のうち {st_['moved']}区間 だけ"
                     f"（{st_['move_rate'] * 100:.1f}%・門 {CHANNEL_SMOOTH_RATE * 100:.0f}%）"
                     f"＝ 上の {g['views_per_h']:+.1f}回/時 は率ではなく「刻み ÷ 窓」です**"
                     "（率として読まないこと ＝ **その速さが立った区間は 1つ もありません**・"
                     "`channel_steps` の覆る条件 (3)）。")
    flat = ""
    if g["flat_laps"] >= 2:
        # **周と一緒に時間を言うこと**（`_flat_span_h` の註）—— 3周 は いまの床で 約1.2時間 で、
        # 実測の刻みの下端（`channel_steps` の `flat_h_lo`）より桁で短い。
        # **周の門だけで verdict を言わないこと**（2026-09-13 03:4x・optimizer・Opus）——
        # 短い行は `flat_readable` で枝を分けているのに、**full はここで無条件に**
        # 「引かれました ＝ …チャンネルの側が止まっていないかを外すこと」と言い、
        # 3行 あとで「とは読めません」と打ち消していました ＝ **同じ 1行 が 2つ の verdict を言う**
        # （`channel_line_short` の覆る条件 (2) の、**full の中**の側。§5 教訓の形 7つ目 ＝
        #  註が正しくても、読まれるのは印字のほう。実物: この回の §7 は「引かれました」と書く所でした）。
        # **実測（台帳の全 93周 を再生した・JOURNAL 09/13 03:4x）**: 周の門は **82/93周** で引かれ、
        # 手本（`bench`）が在る **76周 では readable ⇒ drawn が 76/76** ＝ **答えを 1度も変えていません**。
        # 周の門が答えを変えた 1周 は手本が無い周（`step_hi is None`）だけで、
        # `flat_laps < 3` の周の平らは最大 **0.96時間** 対 手本の上端の最小 **10.79時間**（11倍）。
        if g["flat_laps"] < CHANNEL_FLAT_LAPS:
            _v = f" ＝ **まだ引かれません**（あと {CHANNEL_FLAT_LAPS - g['flat_laps']}周）。"
        elif g["over"]:
            _v = ("。**引かれましたが、この窓では「チャンネルが止まった」と読めません** ——"
                  f"同じ窓で本ごとの合計は {g['vid_sum']:+d}回 動いており（下）、総再生がそれを受け取っていない ＝"
                  "`record_channel` の覆る条件 (1) の側です（§7 (m)）。")
        elif g["flat_readable"]:
            _v = ("。**引かれました ＝ 本の題や形を疑う前に、チャンネルの側が止まっていないかを外すこと**"
                  "（§7 (m)）。")
        else:
            # **周では届いた・時間では読めない** ＝ verdict は次の行（時間の門）だけが言う。
            _v = ("。**この門からは verdict が出ません** —— "
                  "**周の門は、手本が在るあいだ 1度も答えを変えていません**"
                  "（`channel_line` の註の実測 ＝ 読むのは次の行の時間の門）。")
        flat = (f"**総再生は {g['flat_laps']}周（**{g['flat_h']:.1f}時間**）続けて同じ読み**"
                f"（門 {CHANNEL_FLAT_LAPS}周）" + _v)
        # **平らが刻みの手前の平らの「挟みの上端」より短ければ、「止まった」とは読めません**
        # （2026-09-11 04:0x に下端で置き、**11:3x に上端へ移した** ——`channel_growth` の決め）
        step_lo, step_hi = g["step_flat_h"], g["step_flat_h_hi"]
        if not g["flat_readable"]:
            flat += (f"**ただし、この平らは {g['flat_h']:.1f}時間 で、実測した刻みの手前の平らで"
                     f"いちばん長いもの {step_lo:.1f}〜{step_hi:.1f}時間"
                     f"（挟み・手本は {_bench_words(g)}）の**上端**に届いていない ＝ "
                     "「チャンネルが止まった」とは読めません**"
                     "（`trend.channel_steps`・`channel_growth` の決め 11:3x／02:2x）。")
        elif step_hi is not None:
            flat += (f"**この平らは手本の挟みの上端 {step_hi:.1f}時間 を越えました** ——"
                     f"**ただし手本は {_bench_words(g)}**なので、"
                     "これは「刻みの周期より長い」ではありません"
                     "（`channel_steps` の覆る条件 (1-a)）。")
        # **平らの中の反証は、時間の門より強い**（`flat_video_gain` の註・2026-09-11 13:2x）——
        # 手本 1例 の挟みを要らず、同じ台帳の中だけで決まります。**向きは片側だけ。**
        if g["flat_alive"]:
            flat += (f"**そして この平らの中で、本は {g['flat_vid_confirmed']:+d}回 伸びています**"
                     "（遅れでは説明が付かない分・`trend.flat_video_gain`）＝ "
                     "**チャンネルは止まっていません。平らなのは `viewCount` の読みのほうです** ——"
                     "**この平らを『本の 0回』の説明に使わないこと**（§7 (m)）。")
        elif g["flat_vid_confirmed"] == 0 and g["flat_blind"]:
            # **測れなかった回に「伸び 0」と言わないこと**（`flat_video_gain` の註・19:5x）
            flat += (f"**この平らの中で伸びた本は {g['flat_grew']}本 ですが、そのうち "
                     f"{g['flat_blind']}本 は この窓では確かめられません**"
                     f"（窓の確かめられる部分 ＝ 平ら {g['flat_h']:.1f}時間 − 遅れ "
                     f"{REPLICA_LAG_H:.1f}時間 に、`measure` が 1回 しか入っていない・"
                     "`trend.flat_video_gain`）＝ **「伸びが 0 だった」ではなく「測れなかった」** ——"
                     "**§7 (m) の『平らの中の伸びが 0 の回』に、この回を数えないこと。**"
                     # **連なりは、その周の 1点 では読めません**（`blind_run` の註・2026-09-12 16:0x）
                     + blind_run_words(rows))
        elif g["flat_vid_confirmed"] == 0:
            # **ここが §7 (m) の「平らの中の伸びが 0 の回」そのもの**（`proves_alive is False`）＝
            # **連なりを言うのはこの枝**（2026-09-12 17:3x に足した ——16:0x は `blind` の枝にしか
            # 置いておらず、`false_run` が 1 になった最初の周を 1字も言わなかった・`blind_run_words` の註）
            flat += ("**この平らの中で確かめられた本の伸びは 0回 です**（`trend.flat_video_gain`）——"
                     "**「だから止まった」とは読めません**（`measure` が触るのは 19本 だけ・向きは片側）。"
                     + blind_run_words(rows, kind="false"))
        elif g["flat_vid_confirmed"] is None:
            # **3つ目の意味 ＝ そもそも訊けていない**（2026-09-12 14:1x・optimizer・Opus。**実物で踏んだ**）。
            # 平らが `REPLICA_LAG_H` より短い窓では `channel_video_delta` が
            # `sum_confirmed` を `None` のまま返し、**`grew` も `blind` も 0 のまま**です
            # （`measurable` が偽で、数える前に `continue` する）。
            # ＝ **`blind == 0` は「測れて、伸びが 0 だった」を意味しません** ——
            # 19:5x が閉じたのは `blind > 0` の側だけで、こちらは**線が 1字も言わない**まま残っていました。
            flat += (f"**平らの中の伸びは、遅れ {REPLICA_LAG_H:.1f}時間 より短いこの窓では訊けていません**"
                     "（抑え `min(late)` を取る所が窓の中に無い・`trend.flat_video_gain` の覆る条件 (2)）。"
                     "**`grew` も `blind` も 0 ですが、それは「伸びた本が無かった」ではありません** ＝ "
                     "**§7 (m) の『平らの中の伸びが 0 の回』に、この回を数えないこと**"
                     "（数えてよいのは `proves_alive is False` の回だけ）。")
    # **総再生が動かない窓で登録だけが動いたら、応答が丸ごと古いのではない**（`channel_growth` の註 (4)）
    if g["d_views"] == 0 and g["d_subs"]:
        flat += (f"**同じ窓で登録は {g['d_subs']:+d} 動いています** ＝ "
                 "**同じ `channels.list` の応答が丸ごと古いのではありません**"
                 "（動かないのは `viewCount` の刻みの側）。"
                 "＝ **これは「チャンネル全体に配りが来ていない」の証拠になりません** ——"
                 "外せるのは「総再生の数がこの窓で読めない」までです"
                 "（`channel_growth` の覆る条件 (4)）。")
    # **覆る条件 (1) を、次の回が手で数えなくてよいように道具が当てる**（`channel_video_delta` の註）
    conf = g["vid_confirmed"]
    if g["over"]:
        # **「3周 続いたか」は、この窓では数えられません**（`channel_over_blocks` の註・21:4x）——
        # 窓は台帳の両端なので伸びる一方で、`sum_confirmed` は単調に増えるだけ ＝
        # **同じ 1回の証拠が毎周 数え直され、新しい証拠なしに「3周」が埋まります**。
        # 数えるのは**重ならない塊**（1塊 ＝ 遅れの 2倍）。
        tail = (f"。**確かめられた伸びは {conf:+d}回**（複製の遅れ {REPLICA_LAG_H:.1f}時間 の外の読みで抑えた側）"
                "＝ **合計がチャンネルを越えました ＝ `record_channel` の覆る条件 (1) が引かれます**"
                "（触っている本の増えを、総再生が受け取っていない）。"
                f"**「{CHANNEL_FLAT_LAPS}周 続いたか」は、周ではなく「重ならない塊」で数えます**"
                f"（1塊 {CHANNEL_BLOCK_MIN_H:.1f}時間 ＝ 遅れの 2倍・`trend.channel_over_streak`）: "
                f"**いま {g['over_streak']}/{CHANNEL_FLAT_LAPS} 塊**"
                + (f"（切れた塊は {g['over_blocks']}個 ＝ **まだ {CHANNEL_FLAT_LAPS} に届きようがありません**）"
                   if not g["over_ready"] else "")
                + ("。**引かれました ＝ (m) の当て所ごと作り直すこと**" if g["over_drawn"]
                   else "。**この窓の `over` を「1周ぶん」と数え足さないこと** —— "
                        "同じ +N が次の周もこの窓に居ます")
                + _bulk_words(g) + "。")
    elif conf is None:
        tail = (f"（**窓 {g['span_h']:.1f}時間 ＜ 遅れ {REPLICA_LAG_H:.1f}時間** ＝ "
                "**この窓では伸びを確かめられません** —— `sum` の側だけで門を引かないこと。"
                "`channel_video_delta` の註）。")
    elif g["vid_sum"] > g["d_views"]:
        tail = (f"。**ただし、遅れの外で確かめられた伸びは {conf:+d}回**"
                f"（`sum` は「窓の中で**見えるようになった**再生」で、窓より前に付いたぶんを含みます ——"
                f"実測: 同じ本の生の読みが同じ 1時間 で 671 と 687 に割れています）"
                "＝ **(m) の門はこの窓では引けません**（`channel_video_delta` の註）。")
    else:
        tail = ("（**門は片側だけ** —— チャンネル ＞ 合計 の側は、"
                "`measure` が触っていない古い本で説明が付きます）。")
    cmp_ = (f"同じ窓の**本ごとの増えの合計 {g['vid_sum']:+d}回**（**窓の中で読み直した {g['vid_fresh']}本**"
            f"／基準を持つ {g['vid_n']}本・基準の無い {g['vid_skipped']}本 は"
            f"**この合計からだけ外した**（**確かめられた伸びには入っています** ——"
            f"抑えは窓の頭の点ではなく `min(late)`・`channel_video_delta` の註 23:0x）。"
            f"**伸びを出せるのは読み直した側だけ**）"
            + ("・食い違い ＝ 測れていません（両方 0）。" if g["mismatch"] is None
               else f"・食い違い **{g['mismatch'] * 100:.0f}%**" + tail))
    return (f"**チャンネル 登録 {g['subs']}（{g['d_subs']:+d}）・総再生 {g['views']}（{g['d_views']:+d}）**"
            f"（{g['laps']}周・点 {g['n']}件・窓 {g['span_h']:.1f}時間 ＝ **{g['views_per_h']:+.1f}回/時**）。"
            f"{rep}{step}{flat}登録率 ＝ {rate}。{cmp_}"
            + ("**この窓では、総再生が動かないことを「チャンネルが止まった」と読まないこと** ——"
               "本ごとの合計のほうが動いており、総再生はそれを受け取っていません"
               "（`cli.record_channel` の覆る条件 (1) が引かれている ＝ 2つは別の刻みで動く）。"
               if g["over"] else
               "**この数は本ごとの 0回 を読む前に見ること** —— チャンネルの総再生が動いていれば、"
               "0回 は**その本の配りの側**です（動いていなければ、本ではなくチャンネルの側を疑う）。")
            + "**チャンネルの `viewCount` は本ごとの合計と別の刻みで動きます**"
              "（覆る条件 (1) は `cli.record_channel` の註）。")


def channel_line_short(rows: list[dict]) -> str:
    """`channel_line` の**短い形**（`status` が印字する。2026-09-10 23:2x・optimizer・Opus。**API 0単位**）。

    **穴（この回に撃って見つけた）**: `channel_line`（**1,035字**）を
    **`status` と `trend` が同じ周に、1字も違わずに 2度** 印字していました
    （`cmd_status` の 394行 と `trend.report` の 1756行。**同じ関数・同じ引数**）。
    `optimizer` は毎周 その両方を撃つので、**同じ段落を 2度 読みます**（2,070字）。

    **なぜ 22:5x の物差しに映らなかったか**: `scripts/output_growth.py` は
    `trend` の出力**だけ**を測ります（`status` は API を撃つので古いコードで走らせられない ——
    その註の覆る条件 (3)）。＝ **重なりは、片方が測られない側に立っているので、
    伸びとしても重なりとしても数えられていませんでした。**
    **これは伸びではなく重複です** —— 門（+300字/周・2窓）が引かれるのを待つ物ではありません
    （2度目の印字は、1字も新しいことを言いません）。

    **どちらを短くしたか、と理由**: **短くしたのは `status` の側**です。
    `trend` の側に残したのは、そこが **`output_growth` に映る側**だから ——
    `trend` から消して `status` に残すと、同じ字が**測れない側へ移る**だけです
    （§7 (i) が名指ししている「伸びる先が測られない側へ移る」形・METHOD 冒頭の 13:2x と同じ病気）。

    **何を残したか**: **決め（verdict）と数**。落としたのは derivation
    （なぜその門か・どの註に書いてあるか・過去の実測）＝ §5／§6 に当てた形を、`print` の文に当てたもの。
    **判定は full と同じ `channel_growth()` の返りから作ります**（2つの口が別々に数えない）。

    **覆る条件**: (1) 短い行だけを見た回が判定を誤ったら（＝ 短い行に無い決めが要った）、
    その決めを**短い行へ引き上げてから**この行を書き直すこと（§5 の引用の覆る条件 (1) と同じ形）。
    (2) full と短い行が**違う verdict** を言った回が出たら、2つが別々に数えている ＝ 片方を消すこと
    （検査 `test_短い行と full は同じ判定を言う`）。
    **【2026-09-11 14:0x・optimizer・Opus】(2) は実物で引かれました。ただし手当ては「消す」ではありません。**
    同じ周に full は「**チャンネルは止まっていません**」（平らの中で本が +22回 伸びている・`flat_alive`）、
    短い行は「**チャンネルの側を外すこと**」＝ **逆の verdict** を印字していました
    （実物: 平ら 21周・11.5時間・上端 10.8時間 を越えた回）。
    **2つは別々に数えてはいません** —— どちらも同じ `channel_growth()` の返りから作っており、
    短い行が **`flat_alive` の欄を読んでいなかった**だけです。だから閉じ方は
    **欄を読ませること**で、(2) の「片方を消す」は当たりません。
    **(2) の書き直し**: full に**返りの新しい欄**から作る verdict を足したら、**同じ欄を短い行の枝にも当てること**。
    2つを**消して**片付けてよいのは、2つが本当に**別々に数えていた**ときだけです。
    **なぜ検査が捕まえなかったか**: 平らの検査（`test_over_the_upper_end_says_the_sample_is_one` ほか）の
    並びは `channel` の行だけで `measured` の行を持たず、**`flat_alive` は必ず False** でした
    ＝ **13:2x に足した枝を、1件も通っていません**（§5 教訓の形 4つ目 ＝ 検査は緑で、実物の形だけが抜けている）。
    検査 `test_短い行も平らの中の伸びを言う` ＋ 陽性対照（`measured` を外すと元の verdict へ戻る）。
    **【2026-09-11 17:4x・optimizer・Opus】同じ欄で 2度目。当てた枝が 1つ 足りていませんでした。**
    14:0x の直しは `and g["flat_readable"]` を残したので、**時間の門を通った平らでしか**反証を言いません。
    ところが `flat_video_gain` の註は「**手本 1例 の挟みを要らない**」＝ **時間の門と独立**と書いており、
    full は `flat_laps >= 2` で**無条件に**言います。＝ **上端に届いていない平らの中で本が伸びている回**は、
    full が「**チャンネルは止まっていません**」、短い行は「**上端に届いていない ＝ 読めません**」
    （＝ もっと長く平らが続けば読める、と次の回に読ませる弱い理由）だけを言っていました。
    撃って確かめた実物の形: 平ら 6.0時間（挟み 5.0〜7.0時間の中）・その中で本 **+60回**
    → full に「止まっていません」が在り、短い行には **1字も無い**。
    **型（§5 教訓の形 4つ目の族）**: **欄を枝に当てたら、その欄が独立に立つ枝を全部 数えること。**
    1つの枝に当てて閉じると、**残りの枝は「当てた」と書いてあるぶんだけ見えなくなります**。
    検査 `test_短い行は上端に届かない平らでも中の伸びを言う` ＋ 陽性対照。
    **同じ回に、その型で `over` の側も数えました ＝ 3件目は出る前に塞いであります**:
    `over_drawn`（塊が `CHANNEL_FLAT_LAPS` 続いた ＝ 「**(m) の当て所ごと作り直すこと**」）と、
    続いていないときの「**1周ぶんと数え足さないこと**」は、**full にしか在りませんでした**
    （短い行は `over` の verdict 1つ で止まっていた）。いまは 2つ とも短い行が言います
    （検査 `test_短い行も塊が門に届いたら当て所ごと作り直すと言う` ＋ 陽性対照・実物の形は 26時間 で 3塊）。
    (3) `trend` の側でも同じ段落が 2か所から出るようになったら、重なりは `status` だけの病気ではない ＝
    そのときは「毎周 印字する字」を**行ではなく段落の id** で数える口を足すこと。
    **この回に撃って確かめました（次の回は撃ち直さなくてよい）**: いまの `trend` の出力 **8,106字**の中で、
    同じ行の重複は **0件**・**12字 以上 の同じ文**の重複は **1つ・32字（0.4%）** ＝
    **`trend` の側に、この形の重なりは在りません**（重なっていたのは `status` との間だけ）。
    **0.4% を越えた回に、上の「段落の id」を足すこと。**
    """
    g = channel_growth(rows)
    if g["n"] < 2:
        return (f"**チャンネルの数の点: {g['n']}件** —— 増えを数えるには 2点 要ります"
                "（`cli.record_channel`・**API 0単位**）。")
    if g["span_h"] is None or g["span_h"] < CHANNEL_MIN_SPAN_H:
        return (f"**チャンネル 登録 {g['subs']}・総再生 {g['views']}**（点 {g['n']}件・"
                f"窓 {g['span_h']:.2f}時間 ＜ {CHANNEL_MIN_SPAN_H:.1f}時間 ＝ **まだ読まないこと**）。")
    # **verdict は full と同じ `g` から**（覆る条件 (2)）。
    if g["over"]:
        # **`over_drawn`（塊が 3つ 続いた）は `over` とは別の決め**を持ちます
        # （2026-09-11 17:4x に足した ＝ **同じ族の 3件目を、出る前に塞いだ側**）——
        # full だけが「**(m) の当て所ごと作り直すこと**」と「1周ぶんと数え足さないこと」を言い、
        # 短い行は `over` の verdict だけで、**どちらも 1字も言っていませんでした**。
        verdict = (f"**§7 (m) の覆る条件 (1) が引かれています**（いま {g['over_streak']}/"
                   f"{CHANNEL_FLAT_LAPS} 塊）＝ **総再生が動かないことを"
                   "「チャンネルが止まった」と読まないこと**"
                   + (f"。**塊が {CHANNEL_FLAT_LAPS} に届きました ＝ "
                      "(m) の当て所ごと作り直すこと**" if g["over_drawn"] else
                      "（**この窓の `over` を「1周ぶん」と数え足さないこと** —— "
                      "同じ +N が次の周もこの窓に居ます）")
                   # **短い行も同じ口から言うこと**（`channel_line_short` の覆る条件 (2)
                   # 「2つ が違う verdict を言ったら片方を消す」・2026-09-12 02:2x）
                   + _bulk_words(g))
    elif g["flat_laps"] >= CHANNEL_FLAT_LAPS and g["flat_alive"]:
        # **平らの中の反証は、時間の門より強い**（`flat_video_gain` の註・2026-09-11 13:2x）。
        # **full はこの反証を言い、短い行は言っていませんでした**（2026-09-11 14:0x に実物で割れた ＝
        # `channel_line_short` の覆る条件 (2) が引かれた回。`_short_flat_verdict` の註）。
        # **`flat_readable` を要らないこと**（2026-09-11 17:4x に 2度目を閉じた）——
        # 反証は同じ台帳の中だけで決まり、**手本 1例 の挟み（時間の門）を要りません**。
        # 14:0x は `and g["flat_readable"]` を残したので、**上端に届いていない平らの中で
        # 本が伸びている回**は、短い行だけが弱い理由（「上端に届いていない」）を言い、
        # **full の強い反証が落ちていました**（full は `flat_laps >= 2` で無条件に言う）。
        verdict = (f"**総再生は {g['flat_laps']}周（{g['flat_h']:.1f}時間）同じ読みで門"
                   f"（{CHANNEL_FLAT_LAPS}周）の上ですが、その平らの中で本は "
                   f"{g['flat_vid_confirmed']:+d}回 伸びています ＝ "
                   "**チャンネルは止まっていません。平らなのは `viewCount` の読みのほう**"
                   "（`trend.flat_video_gain`）＝ "
                   "**この平らを『本の 0回』の説明に使わないこと**")
    elif g["flat_laps"] >= CHANNEL_FLAT_LAPS and g["flat_readable"]:
        verdict = (f"**総再生は {g['flat_laps']}周（{g['flat_h']:.1f}時間）続けて同じ読み ＝ "
                   f"門（{CHANNEL_FLAT_LAPS}周）が引かれました** ＝ 本の題や形を疑う前に、"
                   "チャンネルの側を外すこと")
        if g["flat_vid_confirmed"] == 0 and g["flat_blind"]:
            verdict += (f"（**平らの中で伸びた {g['flat_grew']}本 のうち {g['flat_blind']}本 は"
                        "この窓では確かめられません** ＝ 「伸びが 0」ではなく「測れなかった」・"
                        "`trend.flat_video_gain`）"
                        # **短い行も同じ口から言うこと**（`channel_line_short` の覆る条件 (2)）
                        + blind_run_words(rows, short=True))
        elif g["flat_vid_confirmed"] == 0:
            verdict += ("（**平らの中の本の伸びは 0回** ＝ 向きは片側 —— "
                        "「だから止まった」ではない・`trend.flat_video_gain`）"
                        # **短い行も同じ口から言うこと**（`channel_line_short` の覆る条件 (2)）
                        + blind_run_words(rows, short=True, kind="false"))
    elif g["flat_laps"] >= CHANNEL_FLAT_LAPS:
        # **門は周で引けても、読みは引けません**（`_flat_span_h` の註・full と同じ口）
        # **門は挟みの上端**（2026-09-11 11:3x・`channel_growth` の決め）
        verdict = (f"**平らは {g['flat_h']:.1f}時間 で、実測の刻みの手前の平らで"
                   f"いちばん長いもの {g['step_flat_h']:.1f}〜{g['step_flat_h_hi']:.1f}時間"
                   f"（挟み・{_bench_words(g)}）の"
                   "**上端**に届いていない ＝ 「チャンネルが止まった」とは読めません**"
                   "（`trend.channel_steps`）")
        # **短い行も、訊けていないことを言うこと**（`channel_line_short` の覆る条件 (2)
        # 「2つ が違う verdict を言ったら片方を消す」・2026-09-12 14:1x に 3件目を**出る前に**塞いだ）。
        if g["flat_vid_confirmed"] is None:
            verdict += (f"（**平らの中の伸びは、遅れ {REPLICA_LAG_H:.1f}時間 より短いこの窓では訊けていません** ＝ "
                        "`blind == 0` を「伸びが 0 だった」と読まないこと・`trend.flat_video_gain`）")
    else:
        verdict = ("**本ごとの 0回 を読む前に見ること** —— 総再生が動いていれば、"
                   "0回 は**その本の配りの側**です")
    subs_note = ("" if not (g["d_views"] == 0 and g["d_subs"])
                 else f"（同じ窓で登録は {g['d_subs']:+d} ＝ 応答が丸ごと古いのではない）")
    conf = ("" if g["vid_confirmed"] is None
            else f"・確かめられた伸び **{g['vid_confirmed']:+d}回**")
    return (f"**チャンネル 登録 {g['subs']}（{g['d_subs']:+d}）・総再生 {g['views']}"
            f"（{g['d_views']:+d}）**（{g['laps']}周・窓 {g['span_h']:.1f}時間）{subs_note}"
            f"・本ごとの合計 {g['vid_sum']:+d}回{conf}。{verdict}。"
            "**derivation は `trend` の同じ行**（API 0単位・この行には写さない）。")


def ready_checks(rows: list[dict], within_h: float = 48.0,
                 now: dt.datetime | None = None) -> dict:
    """公開**前**の本の `readiness` の印（台帳 `ready_checked`）を数える
    （2026-09-10 16:2x・optimizer・Opus。**API 0単位**）。

    数えるのは**窓の中の本ごと**（既定 48時間 ＝ 予約から公開までは 10時間ほどなので、
    直近の 1〜2本 が入る）。**`ok` でない回が 1度でもあれば、その本を名指しで返します** ——
    「いま `ok` だから大丈夫」は、**落ちていた周が在ったこと**を打ち消しません
    （`readiness` が足された当の問いは「10:00 に本当に出るか」です）。

    **覆る条件は `cli.record_ready` の註。**
    """
    now = now or now_jst()
    rs = []
    for r in rows:
        if r.get("event") != "ready_checked" or "ok" not in r:
            continue
        try:
            at = dt.datetime.fromisoformat(r["at"])
        except (KeyError, ValueError):
            continue
        if (now - at).total_seconds() / 3600 <= within_h:
            rs.append(r)
    bad = [r for r in rs if not r.get("ok")]
    drift = [r for r in rs if r.get("meta_drift")]
    # **「1度でも」と「いまも」は別の問い**（2026-09-13 00:3x・optimizer・Opus が踏んで足した）。
    # 上の `bad` / `drift` は**窓の中に 1度でも在ったか**で、これは意図どおりです
    # （落ちていた周が在ったことは、あとで `ok` になっても消えない）。
    # **ただし印字は「いま」を言っていました** —— `drift` の文は
    # 「`yt.update_meta` を撃たない限り古いまま出ます」＝ **現在形**で、
    # 直したあとも 48時間 鳴り続け、次の回に**もう1度 `update_meta` を撃たせます**（API を使う側）。
    # 実物: `Edmce94ZVKs` 00:01:32 `meta_drift:["tags"]` → 00:04:07 `meta_drift:[]`（`hourly` が直した）。
    # ＝ **本ごとのいちばん新しい行**を別に返し、印字はそちらで現在形を言う（§5 教訓の形 7つ目）。
    latest: dict = {}
    for r in rs:
        vid = r.get("id")
        if vid not in latest or str(r.get("at")) > str(latest[vid].get("at")):
            latest[vid] = r
    bad_now = [r for r in latest.values() if not r.get("ok")]
    drift_now = [r for r in latest.values() if r.get("meta_drift")]
    return {"n": len(rs), "books": len({r.get("id") for r in rs}),
            "ok": len(rs) - len(bad), "bad": bad, "drift": drift,
            "latest": latest, "bad_now": bad_now, "drift_now": drift_now,
            "within_h": within_h}


def ready_line(rows: list[dict], now: dt.datetime | None = None) -> str:
    """`ready_checks` を1行にする（`trend` が毎周 印字する ＝ **次の回は覚えていなくてよい**）。"""
    q = ready_checks(rows, now=now)
    if q["n"] == 0:
        # **この文に「予約」の2字を入れないこと** —— `tests/test_studio_trend_pending.py` が
        # 「並びのどこにも 予約 が出ない」で `pending` の行の不在を見ています（2026-09-10 16:2x に踏んだ）。
        return (f"**公開前の本の処理の印: 0件**（直近 {q['within_h']:.0f}時間・台帳 `ready_checked`）—— "
                "**この 0 は「落ちた本が無い」ではなく「公開前の本がこの窓に無かった」**です"
                "（`cmd_status` は 10:00 前の本を持つ周にしか撃ちません）。")
    body = (f"**公開前の本の処理の印: {q['n']}件・{q['books']}本**"
            f"（**直近 {q['within_h']:.0f}時間**・台帳 `ready_checked`・追加 0単位）—— "
            f"**`ok` {q['ok']}件 / `ok` でない {len(q['bad'])}件**。"
            "**この件数は窓の中だけなので、周をまたいで減ります** ＝ "
            "**減りを「台帳が行を落とした」と読まないこと**（`ready_checks` の `within_h`）。")
    if q["bad"]:
        body += ("  !! " + "・".join(f"{r.get('id')} {str(r.get('at'))[:16]} "
                                     f"upload {r.get('upload')}／processing {r.get('processing')}／"
                                     f"失敗 {r.get('failure')}" for r in q["bad"][:3])
                 + " ＝ **公開の刻を疑う前に、この行を先に見ること**（`cli.record_ready` の覆る条件 (1)）。")
        # **「1度でも」と「いまも」を分けて言うこと**（`ready_checks` の 00:3x の註）
        body += (" **いちばん新しい印では `ok` でない本 "
                 f"{len(q['bad_now'])}本**"
                 + ("（＝ **いまは直っています**。上の名指しは「落ちていた周が在った」ことの記録）。"
                    if not q["bad_now"] else
                    f"（{'・'.join(str(r.get('id')) for r in q['bad_now'][:3])} ＝ **いまも落ちています**）。"))
    if q["drift"]:
        body += (f"  !! **台本と食い違った印が付いた回 {len(q['drift'])}件**"
                 f"（{'・'.join(sorted({x for r in q['drift'] for x in (r.get('meta_drift') or [])}))}）")
        if q["drift_now"]:
            body += (" ＝ **いまも食い違っています**（本 "
                     + "・".join(str(r.get("id")) for r in q["drift_now"][:3])
                     + "）—— `yt.update_meta` を撃たない限り古いまま出ます。")
        else:
            body += (" ＝ **いちばん新しい印では 0件 ＝ もう直っています**"
                     "（`yt.update_meta` を撃たないこと。この数は「出口を抜けた回が在った」ことの記録で、"
                     "直した回そのものは `trend.meta_fixes` が数えます）。")
    return body


def pair_gap_line(rows: list[dict], at: dt.datetime | None = None) -> str:
    """`pair_gap` を1行にする（`measure` が撃つ前に印字する）。"""
    g = pair_gap(rows, at)
    where = ("帯 %02d:00〜%02d:00 JST の中" % (DEAD_START, DEAD_END)) if g["band"] else "帯の外"
    if g["gap_min"] is None:
        return f"前の測りが台帳に在りません → この点は2点組の1点目・いまは{where}"
    if g["pairs"]:
        return (f"前の測りから {g['gap_min']:.1f}分（門 {MIN_PAIR_MIN:.0f}分）"
                f"→ **2点組に入ります**・いまは{where}")
    return (f"前の測りから {g['gap_min']:.1f}分（門 {MIN_PAIR_MIN:.0f}分）"
            f"→ **この測りは2点組に入りません**（§7 (2) の分母は動きません）。"
            f"あと {MIN_PAIR_MIN - g['gap_min']:.1f}分 待って撃ち直すこと・いまは{where}")


#: **重なりの窓の端が、刻み 1つ ぶん ずれうる幅**（時間）。`channel_steps` の `periods` の上端が
#: 読めるあいだはそちらを使い、この数は**刻みが 1つも載っていない枠の代理**です
#: （実測の周期 12.73／11.16時間・`channel_steps` の覆る条件 (1)）。
CHANNEL_OVERLAP_EDGE_H = 13.0


def report_vs_ledger(rows: list[dict], rep_rows: list[dict] | None = None) -> dict:
    """**一括レポート（a3）の日ごとの再生を、台帳（`videos.list` の包絡）と並べる。API 0単位。**

    §7 (o-4)(3) が「**複製から返らない唯一の口で、(m) を外から当てられるのはここだけ**」と
    名指ししている当ての、その並べ直しです（2026-09-11 18:4x・optimizer・Opus）。

    報告の日 D の期間は **16:00 JST D 〜 16:00 JST D+1**（`reporting.day_end_jst`）なので、
    **D までの累計** と、**D の終わりの時刻の台帳の包絡**が、同じものを指します。
    ＝ 差は「**台帳（videos.list）がその時刻に、真の数からどれだけ低かったか**」。

    **この回に撃った実測（穴 0日・4本）**:

        本                 齢 6.0h ちょうど       次の境目        その次
        gv1u7n_pCAQ    報告 694 / 台帳 458（**-34.0%**）   930 / 930（0）
        lQHX9LJ80Sg    報告 256 / 台帳 172（-32.8%）       494 / 448（-9.3%）   691 / 683（-1.2%）
        nQbVxuWpWw8    報告  42 / 台帳  28（-33.3%）        67 /  66（-1.5%）
        EkNqtkK49Bw    報告 127 / 台帳  85（-33.1%）       144 / 127（-11.8%）  145 / 140（-3.4%）

    **＝ 包絡でも足りていません。** `envelope()` の註は「1点は真の値を最大 28% 下に外す」と
    書いており、その手当てが**それまでの最大**でした。ところが **4本 とも、いちばん若い境目で
    -33% 前後**です ＝ **齢 6時間 の帯では 3つ の複製が**そろって**遅れており、
    最大を取っても埋まりません**（`envelope` は**周をまたいだ割れ**を直す手で、
    **全部の複製が同じだけ遅れている時間帯**には効かない）。
    差は齢とともに閉じます（-33% → -1〜-12% → 0）。

    **いちばん効く所**: 公開は 10:00 JST に固定・境目は 16:00 JST ＝
    **その本の最初の境目は 齢 6.0時間 ちょうど**。`trend.hold` が毎周「6h ちょうどの点が無いので
    挟みで読む」と書いている §1 の帯（70〜90%）の分子が、**複製から返らない口で 1本に 1つ**立ちます。
    **ただし分母（いまの再生）は台帳のままなので、割合は上限**（まだ伸びる本ほど下がる）。
    **判定（帯の中か外か）は `hourly`**（§5・§1 の行）—— ここは数を並べるまで。

    返り: `{"holes": 穴の日, "last_day": 最後の報告の日, "books": [...],
            "channel": {...}}`。`books` の 1点は
    `{"date", "end", "age_h", "cum", "led", "diff", "ratio"}`。

    **チャンネルの側の 1日 は、そのままでは読めません**（2026-09-13 01:0x・optimizer・Opus。
    **最初の重なりが立った回に足した**）: 総再生は**刻みで動く**ので、1日 の窓の差は
    「その窓に何回 配られたか」で決まります。**とくに最初の刻みは `censored`**
    （左端が台帳の先頭 ＝ 見始めた刻より前がどれだけ平らだったかは台帳に無い）で、
    その +1,625 は長い窓の平均で **33〜40時間ぶん**でした（`channel_steps` の覆る条件 (1)・02:3x）
    ＝ **その刻みを含む窓は、24時間 ぶんより多く抱えます。**
    実測 20260910（09/10 16:00〜09/11 16:00 JST）: **報告 797 対 台帳 1,665（+109%）** ——
    この 2.09倍 は「チャンネルが報告と別の物を数えている」ではなく、**窓が最初の刻みを含んだ**側です。
    → `overlap[i]["censored"]` を立て、**読むのは `read`（`censored` でない日）の累計だけ**。
    **許容は `periods` の上端 ÷ 日数**（端の誤りは刻み 1つ ぶんまでで、日を重ねると薄まる）。

    `channel` は `{"overlap": [{"date","rep","led","censored"}], "read": [...],
    "rep_sum", "led_sum", "ratio", "tol", "edge_h", "drawn", "first_step",
    "next_day", "predict", "first_t", "last_t"}`。

    **覆る条件**: (1) 若い境目の差が **3本 続けて ±5% の中**に入ったら、複製の遅れは
        この帯では消えている ＝ `envelope` の手当てで足りる（この段を書き直すこと）。
    (2) **報告の側が台帳より低い**点が、数え直し（`recounts()` が挙げる本）**以外**で出たら、
        報告は「その日までの全部」ではない ＝ 次元の足し方（`views_by_day`）を先に疑うこと。
    (3) 穴が在る回は `cum` が低く出ます（`reporting.missing_days`）——
        穴が 1日 でも在る回は、差を「複製の遅れ」と読まないこと。
    (4) **`read` の累計が許容（`tol`）を越えたら**（`drawn`）、チャンネルの `viewCount` は
        報告と同じ物を数えていません ＝ §7 (m) の当て所ごと作り直すこと。
        **越えるまでは、1日 の比で (m) を動かさないこと**（上の 20260910 がその 1例目）。
    (5) 報告に出ない本（消した本・非公開に戻した本）の再生が総再生に残るなら、
        差は**片側だけ**（台帳 ＞ 報告）に出ます ＝ `ratio` が**正の側だけ**で門を越え続けたら、
        疑うのは刻みではなく**報告の側の本の数**（`reporting` の `latest_rows` の本数と
        `yt` の本数を並べること）。
    """
    from . import reporting

    rep_rows = reporting.load_rows(reporting.STORE) if rep_rows is None else rep_rows
    holes = reporting.missing_days(rep_rows)
    days = sorted({r.get("date", "") for r in rep_rows if r.get("date")})
    last_day = days[-1] if days else None

    # **台帳の側は `series` + `envelope`**（`hold` と同じ口 ＝ 数え直しの峰も同じ規則で落ちる。
    # ここで生の `views` を自前で拾い直すと、同じ台帳から 2つ目の並びが立ちます）。
    mine = ours(rows)
    tl: dict[str, list[tuple[dt.datetime, int]]] = {}
    pub: dict[str, dt.datetime] = {}
    for vid, pts in series(rows).items():
        if vid not in mine or not pts:
            continue
        tl[vid] = sorted(zip((_at(p) for p in pts), envelope(pts)))
        pub[vid] = published_at(pts)

    def _env_at(vid: str, when: dt.datetime) -> int | None:
        last = None
        for t, v in tl.get(vid, []):
            if t <= when:
                last = v
        return last

    books = []
    for vid in sorted(tl):
        pts = []
        for d, _day, cum in reporting.cum_views(rep_rows, vid):
            end = reporting.day_end_jst(d)
            led = _env_at(vid, end)
            age = (end - pub[vid]).total_seconds() / 3600.0
            pts.append({"date": d, "end": end, "age_h": age, "cum": cum, "led": led,
                        "diff": (None if led is None else led - cum),
                        "ratio": (None if not cum or led is None else led / cum - 1.0)})
        if pts:
            books.append({"id": vid, "points": pts, "now": tl[vid][-1][1]})

    # チャンネルの側（(m) を外から当てる口）——**重なる報告の日が要ります。**
    cs = _channel_rows(rows)
    env = _channel_env_points(cs)
    st = channel_steps(rows)
    # **左端が台帳の先頭の平らに掛かる窓は、読めません**（`channel_steps` の `censored` と同じ理由）
    # —— その刻みは「見始めた刻より前のぶん」を抱えており、どの窓にも割り当てられません。
    first_step = st["steps"][0]["t1"] if st["steps"] else None
    ch: dict = {"overlap": [], "read": [], "first_t": (env[0]["t0"] if env else None),
                "last_t": (env[-1]["t1"] if env else None), "next_day": None, "predict": None,
                "first_step": first_step, "rep_sum": None, "led_sum": None,
                "ratio": None, "tol": None, "edge_h": None, "drawn": False}
    if env:
        tot: dict[str, int] = {}
        for r in reporting.latest_rows(rep_rows):
            tot[r.get("date", "")] = tot.get(r.get("date", ""), 0) + int(float(r.get("views") or 0))
        for d in days:
            end = reporting.day_end_jst(d)
            start = end - dt.timedelta(days=1)
            if start < env[0]["t0"] or end > env[-1]["t1"]:
                continue
            a = max((p["env"] for p in env if p["t1"] <= start), default=None)
            b = max((p["env"] for p in env if p["t1"] <= end), default=None)
            if a is None or b is None:
                continue
            ch["overlap"].append({"date": d, "rep": tot.get(d, 0), "led": b - a,
                                  "censored": first_step is None or start < first_step})
        ch["read"] = [o for o in ch["overlap"] if not o["censored"]]
        if ch["read"]:
            rep_sum = sum(o["rep"] for o in ch["read"])
            led_sum = sum(o["led"] for o in ch["read"])
            # **許容は日数で縮みます** —— 窓の端の誤りは「刻み 1つ ぶん」までで、
            # 日を重ねるとその 1つ が分母に薄まります（`periods` が空のあいだは代理）。
            edge = st["periods"]["max"] or CHANNEL_OVERLAP_EDGE_H
            tol = edge / (24.0 * len(ch["read"]))
            ratio = (led_sum / rep_sum - 1.0) if rep_sum else None
            ch.update({"rep_sum": rep_sum, "led_sum": led_sum, "ratio": ratio,
                       "tol": tol, "edge_h": edge,
                       "drawn": bool(ratio is not None and abs(ratio) > tol)})
        # **次に読める日**（重なりが 1日も無い回と、重なりが全部 `censored` の回の両方で要ります）。
        if last_day:
            nxt = (dt.datetime.strptime(last_day, "%Y%m%d").date() + dt.timedelta(days=1))
            while True:
                k = nxt.strftime("%Y%m%d")
                end = reporting.day_end_jst(k)
                start = end - dt.timedelta(days=1)
                # **`censored` の窓は「次に読める日」に数えません**（上と同じ門）。
                if (start >= env[0]["t0"] and end <= env[-1]["t1"]
                        and (first_step is None or start >= first_step)):
                    a = max((p["env"] for p in env if p["t1"] <= start), default=None)
                    b = max((p["env"] for p in env if p["t1"] <= end), default=None)
                    if a is not None and b is not None:
                        ch["next_day"], ch["predict"] = k, b - a
                    break
                if end > env[-1]["t1"]:
                    break
                nxt += dt.timedelta(days=1)
    return {"holes": holes, "last_day": last_day, "books": books, "channel": ch}


#: **報告が置かれるまでの時間**（期間の終わりから）。実測は 22.5〜25.8時間（`reported` の `made_h`）。
#: 台帳に `made_h` が在る回はそちらを使い、この数は**1度も撃っていない枠の既定**です。
REPORT_MADE_H = 26.0

#: **見込みを過ぎているのに報告がまだ置かれていない回**、次に撃ち直すまでの時間。
#: 毎周 撃つと Reporting API を無駄に叩き、撃たないと 1日 落ちるので、そのあいだ。
REPORT_RETRY_H = 3.0


def reporting_due(rows: list[dict], last_day: str | None,
                  now: dt.datetime | None = None) -> dict:
    """**`python -m studio.cli reporting` を、この回に撃つ番か**（台帳の `reported` の行から・API 0単位）。

    **なぜ要るか**（2026-09-12 17:5x・optimizer・Opus）: `report_vs_ledger_line` は
    「次の報告の日」と「置かれる見込みの刻」を毎周 印字していましたが、
    **その刻を過ぎたかも、最後に撃ったのがいつかも言っていませんでした** ＝
    §7 (o-4)(4)（**(m) を外から当てられる最初の重なり**）は、
    **読む側が自分で時計を見て、自分で思い出す**しかなかった。
    実測: 最後に撃ったのは 09/11 18:46 で、この回（09/12 17:5x）まで **23.1時間**
    —— そのあいだに 9周 が回り、**どの周も撃つ番だと言われていません**。
    §5 の「教訓の形 7つ目」（覆る条件を註に書いたら、その条件を読む**印字**も一緒に作ること）の族で、
    ここは覆る条件ではなく**次の手**の側でした。

    **これは `freshness` と別の問いです** —— `freshness` は「**置かれている報告**が
    どこまでの数か」を Reporting API に訊きます（＝ 撃たないと分からない）。
    こちらは「**撃つ番か**」を台帳と時計だけで言います（API 0単位）。

    返り: `{"last_at", "age_h", "made_h", "next_day", "eta", "due", "why"}`。

    **決め**: 撃つのは (i) 次の報告の日の見込みを過ぎていて、(ii) その見込みより後に
    まだ撃っていない（か、撃ってから `REPORT_RETRY_H` 過ぎた）回だけ。
    **「1日1回でよい」（§7 (o-4)）を刻で言い直したもの**で、門を増やしてはいません。

    **覆る条件**: (1) 見込みを過ぎて撃ったのに空だった回が **3回** 続いたら、
        遅れているのは報告ではなく `made_h` の見積り ＝ `REPORT_MADE_H` ではなく
        **台帳の `made_h` の最大**を使うこと（いまは最後の行の値）。
    (2) `REPORT_RETRY_H` の中に周が 1つも入らない枠が出たら（親の床が 3時間 を越えたら）、
        この数は床の側から引くこと（`quota` の床）。
    (3) 報告の日が **2日 以上** 飛んだ回が出たら、`next_day` は「最後の日 +1」では足りない
        ＝ `reporting.missing_days` の側から取ること。
    """
    from . import reporting

    now = now or dt.datetime.now(dt.timezone.utc)
    fired = [r for r in rows if r.get("event") == "reported"
             and r.get("id") == reporting.REPORT_TYPE]
    last_at = _at(fired[-1]) if fired else None
    made = next((r.get("made_h") for r in reversed(fired) if r.get("made_h")), None)
    made_h = float(made) if made else REPORT_MADE_H
    out: dict = {"last_at": last_at, "made_h": made_h,
                 "age_h": (None if last_at is None
                           else round((now - last_at).total_seconds() / 3600, 1))}
    if not last_day:
        out.update({"next_day": None, "eta": None, "due": True, "why": "never"})
        return out
    nxt = (dt.datetime.strptime(last_day, "%Y%m%d").date() + dt.timedelta(days=1))
    key = nxt.strftime("%Y%m%d")
    eta = reporting.day_end_jst(key) + dt.timedelta(hours=made_h)
    out.update({"next_day": key, "eta": eta})
    if now < eta:
        out.update({"due": False, "why": "early"})
    elif last_at is not None and last_at >= eta and \
            (now - last_at).total_seconds() / 3600 < REPORT_RETRY_H:
        out.update({"due": False, "why": "waited"})
    else:
        out.update({"due": True, "why": "due"})
    return out


#: **見込みを過ぎて撃ったのに報告の日が進まなかった回**が、この数だけ続いたら
#: 疑うのは報告ではなく `made_h` の見積り（`reporting_due` の覆る条件 (1)）。
REPORT_EMPTY_RUN_GATE = 3


def reporting_empty_run(rows: list[dict]) -> dict:
    """**見込みを過ぎて撃ったのに空だった回が、いま何回 続いているか**（台帳の `reported` だけ・API 0単位）。

    **なぜ要るか**（2026-09-12 18:4x・optimizer・Opus）: `reporting_due` の覆る条件 (1) は
    「見込みを過ぎて撃ったのに空だった回が **3回** 続いたら、遅れているのは報告ではなく
    `made_h` の見積り」と書いてありますが、**その回数を数える口が在りませんでした** ＝
    §7 (m) の `blind_run`（2026-09-12 16:0x）と**同じ族**で、
    「N回 続いたら」と書きながら、N を数える物が無い側です。

    **述語は 1つ**（§7 (m) 14:1x「`blind == 0` の意味は 3つ」の教訓）:
    **前の行の報告の日から引いた見込みを過ぎて撃ち、それでも報告の日が進まなかった回**。
    `rows == 0`（積んだ行が 0）では**数えません** —— 同じ日の報告を撃ち直した回も 0行 になり、
    「報告が置かれていない」と見分けが付きません。

    返り: `{"run", "gate", "drawn", "since", "day"}`。`since` は いまの連なりの 1回目の刻。

    **覆る条件**: (1) 連なりが門に届いたのに `made_h` を最大へ移しても当たらなかったら、
        遅れているのは見積りではなく **報告そのもの**（Reporting API の側）＝
        `reporting.freshness` を撃って、置かれている報告の日を直に見ること。
    (2) 報告の日が 2日 以上 飛ぶ枠が出たら、ここも `reporting.missing_days` の側から
        次の日を取ること（`reporting_due` の覆る条件 (3) と同じ穴）。
    """
    from . import reporting

    fired = [r for r in rows if r.get("event") == "reported"
             and r.get("id") == reporting.REPORT_TYPE]
    run, since, day = 0, None, None
    for prev, cur in zip(fired, fired[1:]):
        base = prev.get("last_day")
        at = _at(cur)
        if not base or at is None:
            run, since, day = 0, None, None
            continue
        nxt = (dt.datetime.strptime(base, "%Y%m%d").date() + dt.timedelta(days=1))
        key = nxt.strftime("%Y%m%d")
        made = cur.get("made_h") or prev.get("made_h") or REPORT_MADE_H
        eta = reporting.day_end_jst(key) + dt.timedelta(hours=float(made))
        if at >= eta and cur.get("last_day") == base:
            run += 1
            since = since or at
            day = key
        else:
            run, since, day = 0, None, None
    return {"run": run, "gate": REPORT_EMPTY_RUN_GATE,
            "drawn": run >= REPORT_EMPTY_RUN_GATE, "since": since, "day": day}


def reporting_empty_words(rows: list[dict]) -> str:
    """`reporting_empty_run` の句（**`reporting_due_words` の中だけで使う** ＝ 出どころは 1か所）。"""
    e = reporting_empty_run(rows)
    if not e["run"]:
        return ""
    head = (f"・**空振り {e['run']}/{e['gate']}回**"
            f"（{e['since'].astimezone(JST):%m/%d %H:%M} から・`trend.reporting_empty_run`）")
    if not e["drawn"]:
        return head
    return (head + f" ＝ **引かれました。報告の日 {e['day']} の遅れは `made_h` の見積りの側です** ——"
            "`REPORT_MADE_H`（最後の行の値）ではなく**台帳の `made_h` の最大**へ移すこと"
            "（`reporting_due` の覆る条件 (1)）")


def reporting_due_words(rows: list[dict], last_day: str | None,
                        now: dt.datetime | None = None) -> str:
    """`reporting_due` の 1行（**句の出どころは 1か所** ＝ ここ）。"""
    d = reporting_due(rows, last_day, now=now)
    now = now or dt.datetime.now(dt.timezone.utc)
    last = ("**1度も撃っていません**" if d["last_at"] is None else
            f"最後に撃ったのは **{d['last_at'].astimezone(JST):%m/%d %H:%M}**"
            f"（{d['age_h']:.1f}時間 前）")
    if d["why"] == "never":
        return ("  **`reporting` は 1度も積んでいません** —— "
                "`python -m studio.cli reporting` を撃つこと（**Data API 0単位**・3つ目の枠）")
    eta = d["eta"].astimezone(JST)
    gap = (eta - now).total_seconds() / 3600
    if d["why"] == "early":
        return (f"  **`reporting` は撃たなくてよい回です** —— {last}・次の報告の日 "
                f"**{d['next_day']}** の見込みは {eta:%m/%d %H:%M} JST ＝ **あと {gap:.1f}時間**"
                f"（`trend.reporting_due`・見込みの出どころは"
                f"**窓が閉じてから置かれるまでの {d['made_h']:.1f}時間** ＝ 台帳の `made_h`。"
                f"**この数は残り時間ではありません**）")
    if d["why"] == "waited":
        return (f"  **`reporting` は見込みの後に撃って、まだ空でした** —— {last}・"
                f"報告の日 **{d['next_day']}** は遅れている側 ＝ "
                f"**撃ち直すのは {d['last_at'].astimezone(JST) + dt.timedelta(hours=REPORT_RETRY_H):%m/%d %H:%M} JST から**"
                f"{reporting_empty_words(rows)}")
    return (f"  **この回に `python -m studio.cli reporting` を撃つこと** —— {last}・"
            f"報告の日 **{d['next_day']}** の見込み {eta:%m/%d %H:%M} JST を "
            f"**{-gap:.1f}時間 過ぎています**（**Data API 0単位**・3つ目の枠・`trend.reporting_due`）"
            f"{reporting_empty_words(rows)}")


def report_vs_ledger_line(rows: list[dict], rep_rows: list[dict] | None = None) -> str:
    """`report_vs_ledger` を1行にする（`trend` が毎周 印字する ＝ **次の回は覚えていなくてよい**）。"""
    from . import reporting

    g = report_vs_ledger(rows, rep_rows)
    due = reporting_due(rows, g["last_day"])
    dueline = reporting_due_words(rows, g["last_day"])
    if not g["books"]:
        return ("**一括レポート 対 台帳: 行がありません**（`python -m studio.cli reporting` を"
                "撃つこと・**Data API 0単位**・3つ目の枠）")
    holes = g["holes"]
    head = (f"**一括レポート（a3）対 台帳（`videos.list` の包絡）**（`trend.report_vs_ledger`・"
            f"**Data API 0単位**）: 最後の報告の日 **{g['last_day']}**・"
            + (f"**日に穴 {len(holes)}日**（{'・'.join(d[4:] for d in holes[:6])}"
               f"{' ほか' if len(holes) > 6 else ''}）＝ **累計はその日ぶん低く出ます。"
               "この回の差を『複製の遅れ』と読まないこと**（`reporting.missing_days`）。"
               if holes else "**日に穴 0日**。"))
    parts = []
    for b in g["books"]:
        seg = []
        for p in b["points"]:
            if p["led"] is None:
                continue
            age = f"齢{p['age_h']:.1f}h" if p["age_h"] is not None else p["date"][4:]
            seg.append(f"{age} 報告{p['cum']}/台帳{p['led']}"
                       + (f"（{p['ratio'] * 100:+.1f}%）" if p["ratio"] is not None else ""))
        if seg:
            parts.append(f"{b['id']} " + " → ".join(seg))
    body = ("  " + "／".join(parts)) if parts else ""
    # **齢 6.0h ちょうどの点**（10:00 JST 公開 ＋ 16:00 JST の区切り ＝ 1本に 1つ 立つ）。
    six = []
    for b in g["books"]:
        for p in b["points"]:
            if p["age_h"] is not None and 5.5 <= p["age_h"] <= 6.5 and b["now"]:
                six.append(f"{b['id']} **{p['cum'] / b['now'] * 100:.1f}%**"
                           f"（{p['cum']}/{b['now']}）")
            break
    sixline = ""
    if six:
        sixline = ("  **齢 6.0h ちょうどの割合（複製から返らない分子）**: " + "・".join(six)
                   + " ＝ §1 の帯（70〜90%）の分子が、この口では 1本に 1つ 立ちます"
                   "（**分母はいまの台帳なので、まだ伸びる本では上限**）。**判定は `hourly`**（§5）")
    ch = g["channel"]
    if ch["overlap"]:
        seen = "・".join(
            f"{o['date'][4:]} 報告 {o['rep']}回 対 台帳 {o['led']}回"
            + ("（**読めない日**）" if o["censored"] else "")
            for o in ch["overlap"])
        nxt = ""
        if ch["next_day"] is not None:
            nxt = (f"**次に読めるのは報告の日 {ch['next_day']}**"
                   f"（{reporting.day_end_jst(ch['next_day']) - dt.timedelta(days=1):%m/%d %H:%M}"
                   f"〜{reporting.day_end_jst(ch['next_day']):%m/%d %H:%M} JST）で、"
                   f"**台帳の側は いま {ch['predict']}回**。**その報告が置かれる見込みは"
                   f" {reporting.day_end_jst(ch['next_day']) + dt.timedelta(hours=due['made_h']):%m/%d %H:%M}**")
        if ch["read"]:
            r = ch["ratio"]
            chl = (f"  **(m) を外から当てた**: {seen} ＝ **読める日 {len(ch['read'])}日**・"
                   f"累計 報告 **{ch['rep_sum']}回** 対 台帳 **{ch['led_sum']}回**"
                   + (f"（**{r * 100:+.1f}%**・許容 **±{ch['tol'] * 100:.0f}%** ＝ "
                      f"刻みの周期 {ch['edge_h']:.1f}時間 ÷ {len(ch['read'])}日）"
                      if r is not None else "")
                   + (" ＝ **引かれました。チャンネルの `viewCount` は、報告と同じ物を数えていません** ——"
                      "§7 (m) の当て所ごと作り直すこと（`report_vs_ledger` の覆る条件 (4)）"
                      if ch["drawn"] else
                      " ＝ **同じ物を数えています**（許容の中 ＝ §7 (m) の読み方はこのまま）"))
        else:
            step = (f"{ch['first_step'].astimezone(JST):%m/%d %H:%M} JST"
                    if ch["first_step"] else "（刻みがまだ 1つも載っていません）")
            chl = ("  **(m) の重なりは立ちましたが、この日は読めません**: " + seen
                   + f" —— 窓が**最初の刻み**（{step}・`censored`）を含みます ＝ "
                     "台帳の側は**窓より前のぶん**を抱えており、"
                     "**見始めた刻より前がどれだけ平らだったかは台帳に在りません**"
                     "（`channel_steps` の覆る条件 (1)・02:3x の検算）。"
                     "**この比を (m) の読み方を変える根拠に使わないこと。**"
                   + ("  " + nxt if nxt else ""))
    elif ch["next_day"] is not None:
        chl = (f"  **(m) はまだ外から当てられません** —— 台帳の `channel` の行は"
               f" {ch['first_t']:%m/%d %H:%M} からで、報告の日は {g['last_day']} まで ＝ **重なりません**。"
               f"**いちばん早く当てられるのは報告の日 {ch['next_day']}**"
               f"（{reporting.day_end_jst(ch['next_day']) - dt.timedelta(days=1):%m/%d %H:%M}"
               f"〜{reporting.day_end_jst(ch['next_day']):%m/%d %H:%M} JST）で、"
               f"**台帳の側は いま {ch['predict']}回**。**その報告が置かれる見込みは"
               f" {reporting.day_end_jst(ch['next_day']) + dt.timedelta(hours=due['made_h']):%m/%d %H:%M}**"
               f"（置かれるまで {due['made_h']:.1f}時間 ＝ 台帳の `reported` の `made_h`）")
    else:
        chl = "  **(m) を外から当てる重なりが在りません**（`report_vs_ledger` の `channel`）"
    return "\n".join(x for x in (head, body, sixline, chl, dueline) if x)
